window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-preventiva-med-pre-05"]={"block":"med:med-preventiva-med-pre-05","label":"MED · MED PRE 05","count":446,"questions":[{"id":"med-preventiva-med-pre-05-281099","number":"281099","sourceNumber":"281099","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 30 anos é trazida ao pronto atendimento após ter sido encontrada\ndesacordada, com diminuição do ritmo\nrespiratório, pupilas mitóticas bradirreagentes e com várias\ncartelas de nitrazepam ao seu lado. Em relação às opções de manejo imediato, qual a alternativa\ncorreta quanto à droga a ser administrada neste caso.","options":{"A":"Flumazenil","B":"Carvão ativado","C":"Metoprolol","D":"Atropina","E":"Naloxona"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-281156","number":"281156","sourceNumber":"281156","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 12 anos, refere ter sido picado na perna direta por animal há 2 horas quando\nestava em mata, com dor no local desde\nentão. Exame físico: FC = 124 bpm, FT = 20 irpm, PA =\n100x60mmHg; membro inferior direito: edema até fossa poplítea e equimose em tornozelo. O\ndiagnóstico correto é:","options":{"A":"Acidente crotálico.","B":"Acidente botrópico.","C":"Acidente por loxosceles.","D":"Acidente elapídico.","E":"Acidente por quilópedes."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-247152","number":"247152","sourceNumber":"247152","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Das alternativas, qual pode indicar intoxicação aguda por sal de lítio?","options":{"A":"Ganho de peso.","B":"Hipotireodismo.","C":"Tremores grosseiros.","D":"Poliúra.","E":"Psoriase."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-159038","number":"159038","sourceNumber":"159038","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente psiquiátrica é levada desacordada por familiares à unidade básica de saúde.\nSegundo informações colhidas, a paciente ingeriu 10 comprimidos de diazepam 10 mg. Você está\natendendo na unidade sem equipamentos para garantir uma via aérea definitiva. Qual medicação\nvocê usaria para antagonizar a depressão respiratória causada pela droga?","options":{"A":"Naloxona.","B":"Neostigmina.","C":"Flumazenil.","D":"Sugamadex (Bridion®)."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-108769","number":"108769","sourceNumber":"108769","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 18 anos, masculino, residente no interior do Acre foi \"picado no pé direito\npor uma cobra\" há cerca de 4 horas. Relata\ndor moderada no local da picada e diz que sua perna\nestá \"inchando\". Nega outras queixas. Exame físico: BEG, LOTE, fácies atípica, eucárdico (FC: 88\nbpm) eupneico (FR: 18 irpm), PA: 120 x 80 mmHg, TA: 36ºC, AC: normal, AP: normal, abdome sem\nalterações, no pé direito há pequenos orifícios, edema se estendendo do pé até a região proximal\nda coxa direita, duas bolhas no dorso do pé direito, além de equimoses distribuídas pelo pé e perna\ndireitos. A classificação do acidente e a melhor conduta com relação à soroterapia é:","options":{"A":"Acidente leve / Soro antibotrópico.","B":"Acidente moderado / Soro antibotrópico.","C":"Acidente grave / Soro antibotrópico-crotálico.","D":"Aciedente grave / Soro antibotrópico-laquético."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-37085","number":"37085","sourceNumber":"37085","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Na intoxicação por barbitúricos está indicado o uso de:","options":{"A":"Flumazenil.","B":"Carvão ativado.","C":"Nitrilos.","D":"Vitamina C.","E":"Atropina."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-341041","number":"341041","sourceNumber":"341041","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 24 anos de idade, é atendida na Unidade de Pronto Atendimento 20 minutos\napós acidente na praia com um animal hidrozoário\nconhecido como caravela-portuguesa (Physalia\nphysalis). Ao exame, apresenta extensas placas urticariformes lineares em região posterior do\ntórax. Diante do caso e considerando as orientações do Ministério da Saúde, Indique a substância\nmais adequada a ser usada sobre a área afetada, ainda no local do acidente:","options":{"A":"Água mineral.","B":"Urina.","C":"Água de coco.","D":"Água do mar."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-341042","number":"341042","sourceNumber":"341042","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 24 anos de idade, é atendida na Unidade de Pronto Atendimento 20 minutos\napós acidente na praia com um animal hidrozoário\nconhecido como caravela-portuguesa (Physalia\nphysalis). Ao exame, apresenta extensas placas urticariformes lineares em região posterior do\ntórax. Diante do caso e considerando as orientações do Ministério da Saúde, Identifique\ncomplicações que mais comumente se associam ao acidente com o animal peçonhento envolvido\nno caso:","options":{"A":"Convulsões e hemólise.","B":"Paraplegia e diarreia.","C":"Arritmia e anafilaxia.","D":"Necrose e insuficiência renal aguda."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-341043","number":"341043","sourceNumber":"341043","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 24 anos de idade, é atendida na Unidade de Pronto Atendimento 20 minutos\napós acidente na praia com um animal hidrozoário\nconhecido como caravela-portuguesa (Physalia\nphysalis). Ao exame, apresenta extensas placas urticariformes lineares em região posterior do\ntórax. Diante do caso e considerando as orientações do Ministério da Saúde, Indique a conduta\nmais adequada, neste momento:","options":{"A":"Usar ácido acético a 5% tópico.","B":"Aplicar soro heterólogo intravenoso.","C":"Aplicar sulfadiazina de prata tópica.","D":"Aplicar glicerina líquida tópica."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-278615","number":"278615","sourceNumber":"278615","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Na ordem Himenóptera, estão incluídas abelhas, vespas e formigas, que têm no ferrão\no aparelho inoculador de veneno. Pode causar\nquadro alérgico, decorrente de poucas picadas,\nsendo correto o item:","options":{"A":"Em pessoa previamente desensibilizada, com manifestações locais ou sistêmicas, ou quadro\ntóxico, devido a ataque por múltiplas abelhas ou vespas.","B":"Em pessoa previamente sensibilizada, sem manifestações locais ou sistêmicas, ou quadro\ntóxico, devido a ataque por múltiplas abelhas ou vespas.","C":"Em pessoa previamente sensibilizada, com manifestações locais ou sistêmicas, ou quadro\ntóxico, devido a ataque por múltiplas abelhas ou vespas.","D":"Em pessoa previamente sensibilizada, com manifestações locais, mas não sistêmicas, ou\nquadro tóxico, devido à ataque por múltiplas abelhas ou vespas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-278618","number":"278618","sourceNumber":"278618","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A gravidade depende da quantidade de veneno inoculado pelos animais peçonhentos,\nda região atingida e da espécie envolvida","options":{"A":"nos acidentes botrópico e laquético, o quadro local costuma não ser proeminente, enquanto nos\nacidentes crotálico e elapídico, prevalecem as manifestações neurológicas sistêmicas, decorrentes\nda paralisia muscular.","B":"nos acidentes botrópico e laquético, o quadro local costuma ser proeminente, enquanto nos\nacidentes crotálico e elapídico, não ocorrem\nas manifestações neurológicas sistêmicas, decorrentes\nda paralisia muscular.","C":"nos acidentes botrópico e laquético, o quadro local costuma ser proeminente, enquanto nos\nacidentes crotálico e elapídico, prevalecem as\nmanifestações neurológicas sistêmicas, decorrentes\nda paralisia muscular.","D":"nos acidentes botrópico e laquético, o quadro local costuma ser proeminente, enquanto nos\nacidentes crotálico e elapídico, prevalecem as\nmanifestações neurológicas sistêmicas, sem ocorrer\nparalisia muscular."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-249281","number":"249281","sourceNumber":"249281","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Nos casos de intoxicações por carbamatos, se observa fosforilação de uma esterase\nespecífica do tecido nervoso, denominada\nesterase alvo neuropática (Neuropathy Target Esterase -\nNTE). Podemos apenas aceitar que:","options":{"A":"Embora a função bioquímica da NTE seja de uma fosfolipase/lisofosfolipase ainda não foi\nclaramente definida sua fisiologia e fisiopatologia.","B":"Embora a função bioquímica da NTE não seja de uma lisofosfolipase ainda não foi claramente\ndefinida sua fisiologia e fisiopatologia.","C":"Embora a função bioquímica da NTE não seja de uma fosfolipase ainda não foi claramente\ndefinida sua fisiologia e fisiopatologia.","D":"Embora a função bioquímica da NTE seja de uma fosfolipase/lisofosfolipase foi claramente\ndefinida sua fisiologia hormonal."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-249189","number":"249189","sourceNumber":"249189","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A intoxicação por inibidores de colinesterase progride estabelecendo um quadro de\nSíndrome Colinérgica Aguda. Sendo assim, indique o item errado:","options":{"A":"As manifestações podem ser do tipo muscarínicas, nicotínicas ou neurológicas, de acordo com\nos receptores colinérgicos correspondentes.","B":"A aparição e intensidade dos sintomas dependem de vários fatores como princípio ativo,\nformulação comercial, quantidade e duração da exposição, normalmente.","C":"As secreções abundantes decorrentes da inibição muscarínica são características.","D":"Nos quadros mais graves, os sintomas nicotínicos são os primeiros a aparecer."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-249192","number":"249192","sourceNumber":"249192","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Considerando identificar as principais manifestações da intoxicação aguda por\ninibidores de colinesterase as manifestações muscarínicas são listadas abaixo, indique o item\ncompletamente correto:","options":{"A":"Broncoespasmos, vômito e obstipação, incontinência urinária, dispneia, dor abdominal, fadiga\nrespiratória e disúria.","B":"Broncoespasmos, vômito e diarreia, incontinência urinária, dispneia, dor abdominal, fadiga\nrespiratória e disúria.","C":"Broncoespasmos, vômito e diarreia, continência urinária, dispneia, dor abdominal, fadiga\nrespiratória e poliúria.","D":"Broncodilatação, vômito e diarreia, incontinência urinária, dispneia, dor abdominal, fadiga\nrespiratória e disúria."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-219903","number":"219903","sourceNumber":"219903","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Com relação à intoxicação digitálica é INCORRETO afirmar que:","options":{"A":"Os níveis séricos de digoxina estão invariavelmente elevados nos pacientes intoxicados.","B":"Na intoxicação aguda, pode ocorrer hipercalemia, cuja intensidade se correlaciona com\nmortalidade.","C":"Hipocalemia, hipomagnesemia e hipercalcemia são distúrbios que favorecem a intoxicação.","D":"Tanto a digoxina como a digitoxina apresentam índice terapêutico baixo, o que favorece a\nintoxicação."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-182809","number":"182809","sourceNumber":"182809","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Há uma miscelânea de condições em que o ECG apresenta alterações peculiares, não\nsó nas cardiopatias, como também em doenças\nsistêmicas, em distúrbios metabólicos e na ação de\nmedicamentos. Sendo INADEQUADO frente à intoxicação digitálica o seguinte item:","options":{"A":"depressão de ST-T de concavidade inferior.","B":"onda T ?em colher?.","C":"diminuição do intervalo QTc.","D":"na intoxicação digitálica, podem ocorrer várias arritmias, predominando a extrassistolia\nventricular."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-134097","number":"134097","sourceNumber":"134097","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente com histórico de uso de anfetamina para exercícios físicos extenuantes\ndá entrada no hospital com agitação, miose e\nsudorese. Sua pressão arterial é de 210 x\n\n120 mmHg e sua frequência cardíaca é de 180 bpm. Qual das medicações abaixo listadas\napresenta contraindicação para essa situação?","options":{"A":"Metoprolol.","B":"Nitroprussiato.","C":"Diazepam.","D":"Diltiazem."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-110564","number":"110564","sourceNumber":"110564","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O acidente ofídico que mais frequentemente cursa com insuficiência renal é:","options":{"A":"botrópico.","B":"laquético.","C":"crotálico.","D":"elapídico.","E":"NDA."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-86626","number":"86626","sourceNumber":"86626","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente 23 anos, sexo feminino, fez uso de antidepressivo tricíclico como tentativa de\nsuicídio, chega à unidade hospitalar 40 minutos após o evento: Exame físico: confusa, taquicárdica,\npupilas midriáticas e hipotensa apresentando convulsões. Assinale as alternativas CORRETAS em\nrelação à conduta terapêutica (emergências clínicas): I ? Indução do vômito; II ? Lavagem gástrica\nseguida de carvão ativado na primeira hora; III ? Uso de benzodiazepínicos.","options":{"A":"Apenas afirmativas II e III estão corretas.","B":"Apenas afirmativa II está correta.","C":"Apenas afirmativas I e III estão corretas.","D":"Apenas afirmativa III está correta.","E":"Todas afirmativas estão corretas."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-86794","number":"86794","sourceNumber":"86794","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"As intoxicações agudas Exógenas são situações em que todo Médico de Família e\nComunidade deve estar preparado para atuar. No caso de intoxicação aguda por uso de\nbetabloqueadores, qual é o antídoto para esta condição?","options":{"A":"Flumazenil;","B":"Glucagon;","C":"Bicarbonato de Cálcio;","D":"Atropina;","E":"N-acetilcisteína"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-286712","number":"286712","sourceNumber":"286712","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem de 30 anos tira uma lata de cerveja da geladeira e rapidamente engole um\nbocado do seu conteúdo antes de perceber\nque não era cerveja. Dentro de alguns minutos, ele\napresenta cólicas abdominais graves, visão turva, espasmos e perda de consciência. A esposa\nrefere a equipe médica que colocou spray de barata na lata de cerveja e tinha deixado na geladeira\npara tentar eliminar as baratas e esqueceu de avisar ao marido. O pessoal da emergência verifica a\nembalagem e determina que é um organofosforado. Para neutralizar a atividade de inibição da\ncolinesterase do veneno de organofosforado, o homem deve receber qual dos seguintes antídotos:","options":{"A":"Metacolina.","B":"Piridostigmina.","C":"Edrofônio.","D":"Atropina."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-151945","number":"151945","sourceNumber":"151945","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Jovem de 16 anos chega ao pronto-socorro com dilatação pupilar, taquicardia,\nhipertensão, hipertermia e perda do sentido olfato. A droga provável usada foi:","options":{"A":"Teofilina.","B":"Cocaína.","C":"Barbitúrico.","D":"Prometazina."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-324689","number":"324689","sourceNumber":"324689","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 2 anos de idade, é levado à UPA com relato de sonolência, náuseas e vômitos\nhá 50 minutos. Após inicio do quadro, foi\nconstatado que o menor ingeriu bolinhas de naftalina. A\ngenitora informa ter colocado o produto, há dois dias, na gaveta que se encontrava aberta; que as\nbolinhas estavam em um pacote com 5 unidades, de menos de 1 cm de diâmetro, e que 3 delas\nforam encontradas. Ao exame, criança hipoativa, hidratada, eupneica, corada, afebril. Observa-se\nhipersalivação. Sem outros achados anormais no momento. Considerando o potencial tóxico do\nproduto, e que a criança permaneceu por 8 horas em observação, sem sintomas, indique a conduta\ncorreta:","options":{"A":"Manter internado por mais 12 horas, verificando sintomas respiratórios.","B":"Manter internado por mais 48 horas, verificando sintomas neurológicos.","C":"Conceder alta, com retorno, após 5 dias, para realizar Hemograma e Sumário de Urina.","D":"Conceder alta com observação domiciliar, por 5 a 7 dias, e retorno se tiver sintomas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-324690","number":"324690","sourceNumber":"324690","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 2 anos de idade, é levado à UPA com relato de sonolência, náuseas e vômitos\nhá 50 minutos. Após inicio do quadro, foi\nconstatado que o menor ingeriu bolinhas de naftalina. A\ngenitora informa ter colocado o produto, há dois dias, na gaveta que se encontrava aberta; que as\nbolinhas estavam em um pacote com 5 unidades, de menos de 1 cm de diâmetro, e que 3 delas\nforam encontradas. Ao exame, criança hipoativa, hidratada, eupneica, corada, afebril. Observa-se\nhipersalivação. Sem outros achados anormais no momento. O paciente, em questão, pode\napresentar complicação decorrente de:","options":{"A":"Lesões cáusticas pela acidez.","B":"Lesões cáusticas pela alcalinidade.","C":"Síndrome hipercolinérgica.","D":"Metahemoglobinemia com cianose."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-324691","number":"324691","sourceNumber":"324691","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 2 anos de idade, é levado à UPA com relato de sonolência, náuseas e vômitos\nhá 50 minutos. Após inicio do quadro, foi\nconstatado que o menor ingeriu bolinhas de naftalina. A\ngenitora informa ter colocado o produto, há dois dias, na gaveta que se encontrava aberta; que as\nbolinhas estavam em um pacote com 5 unidades, de menos de 1 cm de diâmetro, e que 3 delas\nforam encontradas. Ao exame, criança hipoativa, hidratada, eupneica, corada, afebril. Observa-se\nhipersalivação. Sem outros achados anormais no momento. No caso de ocorrer a complicação,\nconsidere as opções abaixo e indique a conduta adequada:","options":{"A":"Administrar carvão ativado.","B":"Fazer lavagem gástrica.","C":"Administrar azul de metileno.","D":"Administrar atropina."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-294457","number":"294457","sourceNumber":"294457","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem, 19 anos de idade, lavrador, dá entrada na emergência após acidente ofidico\npor jararaca, em pé esquerdo, há 48 horas.\nQueixa-se de dor intensa no local da picada. Nega\ncomorbidades. Ao exame físico, apresenta-se em regular estado geral, com FR: 22irpm, PA:\n140x90mmHg, FC: 100bpm, SatO?: 95%. Observam-se dois orifícios de inoculação, edema,\nequimose e lesões bolhosas no local da picada. Em relação ao tratamento geral desse paciente,\ndeve-se","options":{"A":"realizar torniquete, no atendimento inicial, para impedir a circulação do veneno.","B":"iniciar aciclovir, para cobertura de herpes, presente na saliva da serpente.","C":"realizar cobertura para anaeróbios, gram positivos e gram negativos, caso ocorra infecção\nsecundária.","D":"evitar opioides, para que os efeitos colaterais não se confundam com o efeito neurotóxico do\nveneno."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-294458","number":"294458","sourceNumber":"294458","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem, 19 anos de idade, lavrador, dá entrada na emergência após acidente ofidico\npor jararaca, em pé esquerdo, há 48 horas.\nQueixa-se de dor intensa no local da picada. Nega\ncomorbidades. Ao exame físico, apresenta-se em regular estado geral, com FR: 22irpm, PA:\n140x90mmHg, FC: 100bpm, SatO?: 95%. Observam-se dois orifícios de inoculação, edema,\nequimose e lesões bolhosas no local da picada. Em relação ao tratamento específico, o soro\n\nanti-veneno a ser aplicado é","options":{"A":"antibotrópico.","B":"antilaquético.","C":"anticrotálico.","D":"antielapídico."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-294459","number":"294459","sourceNumber":"294459","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem, 19 anos de idade, lavrador, dá entrada na emergência após acidente ofidico\npor jararaca, em pé esquerdo, há 48 horas.\nQueixa-se de dor intensa no local da picada. Nega\ncomorbidades. Ao exame físico, apresenta-se em regular estado geral, com FR: 22irpm, PA:\n140x90mmHg, FC: 100bpm, SatO?: 95%. Observam-se dois orifícios de inoculação, edema,\nequimose e lesões bolhosas no local da picada. Diante do quadro descrito, indique as\ncomplicações que esse paciente, mais provavelmente, poderá apresentar.","options":{"A":"Hemorragias, decorrentes de plaquetopenia e distúrbios de coagulação.","B":"Fáceis miastênica e ptose, decorrentes do efeito neurotóxico do veneno.","C":"Síndrome vagal, com diarreia, bradicardia, hipotensão.","D":"Rabdomiólise, devido ao efeito miotóxico do veneno."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-62893","number":"62893","sourceNumber":"62893","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente, 13 anos de idade, vem à emergência com quadro de sonolência, evoluindo a\ntorpor, acompanhado de hipotensão, hiporreflexia, cianose labial e depressão respiratória. Sem\nqualquer passado de doenças. Existe informação de conflito familiar. A principal suspeita desse\nquadro é uma síndrome tóxica. A síndrome tóxica que se enquadra nos sintomas apresentados e\nas drogas relacionadas são, respectivamente:","options":{"A":"Simpaticomimética e intoxicação por cocaína ou anfetamínicos.","B":"Extrapiramidal e intoxicação por lítio ou fenotiazínicos.","C":"Metemoglobinêmica e intoxicação por nitrofurantoína ou dapsona.","D":"Anticolinérgica e intoxicação por antidepressivo tricíclico ou atropina.","E":"Depressiva e intoxicação barbitúrica ou alcoólica."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-134676","number":"134676","sourceNumber":"134676","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente com dispneia aos médios esforços, edema em membros inferiores, prostração\ne dificuldade de dormir. Refere ter problema no\ncoração e utilizar medicação para \"coração\ninchado\". Qual dos aspectos abaixo seria compatível com intoxicação digitálica?","options":{"A":"Paciente refere enxergar as coisas amareladas.","B":"Aumento da frequência cardíaca.","C":"Taquisfigmia.","D":"Cialorreia."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-199655","number":"199655","sourceNumber":"199655","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O médico plantonista da enfermaria de cirurgia é chamado para atendimento de Parada\nCardiopulmonar (PCR). Trata-se de A.S.B.M., 55 anos, com neoplasia de mama recidivada e\nmetastática aguardando a possibilidade de quimioterapia de resgate. Foi internada para controle de\ndor e dispneia. A equipe de cuidados paliativos iniciou morfina em infusão contínua e escreveu no\nprontuário a vontade expressa da paciente de não ser reanimada, nem levada para UTI. A filha,\npresente na enfermaria, reiterou a vontade da mãe. A infusão contínua de morfina foi iniciada no\ndia anterior. No momento do atendimento, o exame da paciente indicou pupilas mióticas\npuntiformes, inconsciência e apneia com pulso carotídeo presente e fino. Qual a conduta imediata\nmais adequada a ser adotada pelo plantonista?","options":{"A":"Ventilar com máscara enquanto administra naloxone.","B":"Respeitar a vontade da paciente, permitindo a apneia evoluir para PCR.","C":"Iniciar ressuscitação cardiopulmonar com compressões cardíacas, imediatamente.","D":"Realizar entubação orotraqueal e mantê-la em ventilação mecânica na enfermaria."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-173003","number":"173003","sourceNumber":"173003","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Na Emergência, a mãe de uma criança de três anos de idade relata que a mesma foi\npicada por um inseto há cerca de 3 dias e que já recebeu um primeiro atendimento numa Unidade\nde Pronto Atendimento, cerca de duas horas após a picada. No momento, há dor aguda no local,\nvermelhidão, prurido e edema flogístico que evoluiu para enduração local; também há dificuldades\nde mobilidade no membro afetado. Na UPA, o médico havia conseguido identificar e retirar o ferrão.\nQual o inseto mais provável de ter causado essas alterações?","options":{"A":"Vespa.","B":"Arraia.","C":"Abelha.","D":"Formiga."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-51237","number":"51237","sourceNumber":"51237","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem jovem sofreu acidente ofídico há 4 horas. Apresenta ptose e incapacidade de\ndeambular. Que medicamento atuante no Sistema Nervoso Autonômico é indicado nesse caso?","options":{"A":"Clonidina.","B":"Adrenalina.","C":"Neostigmina.","D":"Amitriptilina."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-32528","number":"32528","sourceNumber":"32528","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Num paciente com intoxicação aguda e grave por propranolol, qual das medicações\nabaixo é a mais adequada ao tratamento?","options":{"A":"Atropina.","B":"Glucagon.","C":"Clonazepam.","D":"Cloreto de cálcio.","E":"Sulfato de Magnésio."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-30864","number":"30864","sourceNumber":"30864","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual a amostra mais apropriada para avaliar exposição ocupacional ao chumbo?","options":{"A":"Fezes.","B":"Cabelos.","C":"Suor.","D":"Sangue.","E":"Urina."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-30872","number":"30872","sourceNumber":"30872","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Adolescente com sintomas de falta de apetite, sonolência e desânimo vem recebendo\ntratamento medicamentoso e passou a apresentar\nrigidez muscular grave, hipertermia (temperatura\naxilar: 39,5°C), sudorese abundante, tremores e disfagia. Esses sintomas devem-se,\nprovavelmente, a que interação medicamentosa?","options":{"A":"Fluoxetina e fenelzina.","B":"Sertralina e imipramina.","C":"Risperidona e metilfenidato.","D":"Venlafaxina e sibutramina.","E":"Carbonato de lítio e anfetamina."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-37419","number":"37419","sourceNumber":"37419","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A ingestão de querosene por crianças ocorre, principalmente, em famílias de nível\nsocioeconômico menos favorecido, que conservam o líquido dentro de garrafas de refrigerantes ao\nalcance fácil das crianças. A conduta correta diante de uma criança que ingere querosene é:","options":{"A":"Lavagem gástrica com soro gelado.","B":"Uso de óleo mineral por sonda nasogástrica para diminuir a absorção de hidrocarbonetos.","C":"Uso de corticoide para evitar a pneumonia química.","D":"Tratamento de suporte com monitorização respiratória, renal e neurológica.","E":"Nenhuma das alternativas anteriores."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-9035","number":"9035","sourceNumber":"9035","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Severino, 12 anos, foi picado por uma aranha de pequeno tamanho. Inicialmente, o\nquadro passou despercebido, pois o acidente\npor esse animal é pouco doloroso. A lesão (picada)\nevoluiu com uma bolha, extensa ulceração e necrose. O paciente apresentou mal-estar, icterícia e\nurina escura. Qual a PROVÁVEL aranha envolvida nesse caso?","options":{"A":"Loxosceles (aranha marrom)","B":"Phoneutria (aranha armadeira)","C":"Caranguejeira","D":"Latrodectus sp (viúva-negra)"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-9125","number":"9125","sourceNumber":"9125","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"João, 18 anos, residente em Fortaleza, comparece à unidade de saúde após ?picada?\nde escorpião há cerca de 4 horas. Apresenta dor\nlocal. Considerando que ele tem\nmicroalbuminúria, não teve evento isquêmico coronariano e não tem insuficiência cardíaca ou renal,\nqual a classe de anti-hipertensivo de escolha?","options":{"A":"Inibidores da enzima conversora da angiotensina/antagonista do receptor da angiotensina.","B":"Beta-bloqueadores.","C":"Diuréticos de alça.","D":"Bloqueadores dos canais de cálcio."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-9109","number":"9109","sourceNumber":"9109","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre envenenamentos agudos, marque a alternativa INCORRETA:","options":{"A":"A descontaminação cutânea deve ser feita o mais precoce possível, por meio de lavagem\ncopiosa da area afetada com água ou soro fisiológico e neutralização química.","B":"Em caso de contato de agentes químicos com os olhos, a conduta é remover as lentes de\ncontato, se presentes, e lavar abundantemente\nos olhos com água ou soro fisiológico durante 15 a\n20 minutos.","C":"As contraindicações de lavagem gástrica são convulsões, agitação psicomotora ou ingestão de\ncáusticos.","D":"A mortalidade por ingestão de tóxicos é menor que 1%."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-365655","number":"365655","sourceNumber":"365655","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente foi levado pela esposa ao pronto-socorro com quadro de intoxicação por\nbenzodiazepínico. Qual é a indicação medicamentosa para esse caso?","options":{"A":"Adrenalina","B":"Atropina","C":"Flumazenil","D":"Naloxone"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-305295","number":"305295","sourceNumber":"305295","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma mulher de 30 anos é levada ao serviço médico de urgência, por familiares, com\nquadro de rebaixamento do nível de\nconsciência. Ao exame, apresenta-se bradipneica (FR=8irpm)\ne comatosa (glasgow 9). A mãe informa histórico de uso de heroína. Após estabilização clínica\ninicial qual é a conduta mais adequada?","options":{"A":"Hipotermia terapêutica.","B":"Lavagem gástrica com carvão ativado.","C":"Administração de flumazenil endovenoso.","D":"Administração de bicarbonato endovenoso.","E":"Administração de naloxona endovenosa."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-305308","number":"305308","sourceNumber":"305308","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino de 1 ano dá entrada em hospital após quadro convulsivo. Ao exame físico,\napresenta midríase, taquicardia, sudorese,\nhipertensão, piloereção e hiper-reflexia. Na anamnese, a\nmãe conta que o paciente está, há 2 dias, com obstrução nasal e espirros e, por estar com\ndificuldade para dormir devido à obstrução, usou medicamento em gotas que tinha em casa, nas\nnarinas da criança. Após seu uso, o paciente iniciou o quadro atual. Considerando o agente\nfarmacológico provável, trata-se de uma","options":{"A":"toxíndrome simpatomimética, que resulta da estimulação de nervos simpáticos (alfa e\nbeta-adrenérgicos) mediada pelas catecolaminas noradrenalina e adrenalina.","B":"toxíndrome anticolinérgica, que resulta da inibição das fibras parassimpáticas pós-ganglionares\nque liberam a acetilcolina, das fibras autônomas\npré-ganglionares, das placas mioneurais do\nmúsculo esquelético e de certas sinapses do sistema nervoso central.","C":"toxíndrome anticolinesterásica, em que ocorre inibição da enzima acetilcolinesterase, levando a\num acúmulo da acetilcolina nos receptores colinérgicos muscarínicos e nicotínicos.","D":"toxíndrome depressiva, que resulta da interferência na função adrenérgica do SNC,\nprincipalmente nos neurônios noradrenérgicos centrais.","E":"toxíndrome extrapiramidal, que resulta do aumento da ação da acetilcolina nas sinapses\nmuscarínicas e do antagonismo da dopamina no SNC."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-262468","number":"262468","sourceNumber":"262468","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em julho de 2020, um estudante de medicina veterinária do Distrito Federal teve um\nacidente ofídico com uma cobra naja. O estudante ficou em coma na unidade de terapia intensiva e\nrecuperou-se após receber o soro antiofídico. A cobra é originária de países da África e da Ásia, e\né\nconsiderada uma das mais venenosas do mundo. Até então, não se tinha conhecimento da espécie\nno Brasil. No que se refere aos acidentes com animais peçonhentos e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. Nos acidentes com aracnídeos, o\nenvenenamento é causado pela inoculação de toxinas por intermédio do aparelho inoculador\n(quelíceras) de aranhas, podendo determinar alterações locais e sistêmicas. O tratamento\nsoroterápico é indicado para pacientes classificados clinicamente como moderados ou graves nos\nacidentes com aranha marrom (Loxosceles) ou armadeira (Phoneutria). Em acidente com aranha\nviúva-negra (Latrodectismo), o tratamento é sintomático e de suporte.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-131835","number":"131835","sourceNumber":"131835","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A respeito do tratamento de acidentes ofídicos, assinale a alternativa correta.","options":{"A":"No acidente elapídico, pode-se, além do soro, utilizar atropina e anticolinesterásico.","B":"A administração de heparina sempre deve preceder o uso de antibotrópico.","C":"Reações tardias como urticária, febre e adenomegalia, após a administração do soro, ocorrem\napenas quando se utiliza de anticrotálico.","D":"O tratamento da insuficiência respiratória aguda deve ser a primeira medida no tratamento do\nacidente laquético.","E":"O uso de torniquete nos membros inferiores está especialmente indicado quando a serpente for\ndo gênero Bothrops."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-88736","number":"88736","sourceNumber":"88736","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente de cinquenta e cinco anos de idade foi levado ao hospital devido à\ntentativa de suicídio por meio da inalação\nde monóxido de carbono. No exame físico, o paciente\napresentou-se comatoso, acianótico e hemodinamicamente normal. A gasometria demonstrou pH =\n7; pCO? = 31; pO? = 93; HCO? = 7; BE = -4,1 e saturação de oxigênio = 91%. Em relação a esse\ncaso clínico, julgue o item que se segue. Recomenda-se a adoção de intubação orotraqueal do\npaciente e de ventilação com oxigênio a 100%.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-preventiva-med-pre-05-301260","number":"301260","sourceNumber":"301260","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente de 15 anos de idade procurou atendimento médico 24 horas após ter sido\npicado por formigas \"lava-pés\" (gênero Solenopsis) no dorso e na região lateral do pé direito.\n\nRelatou que, inicialmente, teve dor em queimação intensa, a qual posteriormente cedeu, e ele\npassou a sentir prurido local com\nsurgimento de pápulas. Um dia depois, notou que várias pápulas\nse tornaram pústulas, com eritema e persistência do prurido. Negou aparecimento de febre. O\nexame clínico confirmou a presença de algumas vesículas e pústulas íntegras no local informado,\nalém de leve edema e eritema perilesional. Considerando as recomendações do Ministério da\nSaúde e com base nesse caso clínico, julgue os itens de 17 a 20. No Centro-Oeste, a espécie de\nmaior importância nos acidentes por formigas é a lava-pés vermelha.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-301261","number":"301261","sourceNumber":"301261","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente de 15 anos de idade procurou atendimento médico 24 horas após ter sido\npicado por formigas \"lava-pés\" (gênero Solenopsis) no dorso e na região lateral do pé direito.\n\nRelatou que, inicialmente, teve dor em queimação intensa, a qual posteriormente cedeu, e ele\npassou a sentir prurido local com\nsurgimento de pápulas. Um dia depois, notou que várias pápulas\nse tornaram pústulas, com eritema e persistência do prurido. Negou aparecimento de febre. O\nexame clínico confirmou a presença de algumas vesículas e pústulas íntegras no local informado,\nalém de leve edema e eritema perilesional. Considerando as recomendações do Ministério da\nSaúde e com base nesse caso clínico, julgue os itens de 17 a 20. O paciente deve ser tratado com\nantibioticoterapia, pois as pústulas indicam infecção secundária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-301262","number":"301262","sourceNumber":"301262","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente de 15 anos de idade procurou atendimento médico 24 horas após ter sido\npicado por formigas \"lava-pés\" (gênero Solenopsis) no dorso e na região lateral do pé direito.\n\nRelatou que, inicialmente, teve dor em queimação intensa, a qual posteriormente cedeu, e ele\npassou a sentir prurido local com\nsurgimento de pápulas. Um dia depois, notou que várias pápulas\nse tornaram pústulas, com eritema e persistência do prurido. Negou aparecimento de febre. O\nexame clínico confirmou a presença de algumas vesículas e pústulas íntegras no local informado,\nalém de leve edema e eritema perilesional. Considerando as recomendações do Ministério da\nSaúde e com base nesse caso clínico, julgue os itens de 17 a 20. O uso de corticóides tópicos não\né recomendado em casos semelhantes ao descrito.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-301263","number":"301263","sourceNumber":"301263","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente de 15 anos de idade procurou atendimento médico 24 horas após ter sido\npicado por formigas \"lava-pés\" (gênero Solenopsis) no dorso e na região lateral do pé direito.\n\nRelatou que, inicialmente, teve dor em queimação intensa, a qual posteriormente cedeu, e ele\npassou a sentir prurido local com\nsurgimento de pápulas. Um dia depois, notou que várias pápulas\nse tornaram pústulas, com eritema e persistência do prurido. Negou aparecimento de febre. O\nexame clínico confirmou a presença de algumas vesículas e pústulas íntegras no local informado,\nalém de leve edema e eritema perilesional. Considerando as recomendações do Ministério da\nSaúde e com base nesse caso clínico, julgue os itens de 17 a 20. O uso de anti-histaminicos e\ncorticóides orais devem ser reservado para os casos em que há reações alérgicas de moderadas a\nintensas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-263350","number":"263350","sourceNumber":"263350","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um adolescente com 13 anos de idade é atendido no pronto-socorro devido à picada\nde escorpião no dedo indicador esquerdo. Em exame\nfísico, apresenta sinais vitais estáveis, dor\nintensa, hiperemia e formigamento no local da picada, associados a náuseas, vômitos, sudorese e\nsialorreia discretos. Além do alívio da dor, a conduta recomendada é:","options":{"A":"Observação domiciliar por 6 a 12 horas.","B":"Observação hospitalar por 6 a 12 horas.","C":"Soro antiescorpiônico (2 a 3 ampolas).","D":"Soro antiescorpiônico (4 a 6 ampolas)."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-291486","number":"291486","sourceNumber":"291486","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança de 7 anos de idade, moradora de zona rural, relata acidente por animal\ndesconhecido há 4 horas. No momento, refere formigamento no local da picada, boca seca,\ndiplopia, dificuldade de deglutinação, dores musculares generalizadas, oligúria e urina com\ncoloração vermelha escura. Ao exame físico, apresenta ptose palpebral bilateral e midríase. O\nresultado do exame de urina rotina evidenciou mioglobinúria. Exames de sangue ainda em\nprocessamento. Com base nesses dados, qual a soroterapia específica indicada ao quadro?","options":{"A":"Soro antibotrópico.","B":"Soro antiescorpiônico.","C":"Soro anticrotálico.","D":"Soro antielapídico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-273348","number":"273348","sourceNumber":"273348","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente feminina, de 20 anos, com história de etilismo prévio e diagnóstico de\ndepressão há 10 dias, quando foi iniciado\ntratamento com venlafaxina em progressão de dose. É\ntrazida ao pronto-socorro pelo namorado com quadro de agitação, confusão mental, febre e diarreia\niniciados há 12 horas. Ao exame físico foi observado ainda rigidez muscular e mioclonia. Qual o\ndiagnóstico mais provável?","options":{"A":"Intoxicação por álcool e metilenodioximetanfetamina.","B":"Síndrome serotoninérgica.","C":"Síndrome neuroléptica maligna.","D":"Diarreia infecciosa."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-175081","number":"175081","sourceNumber":"175081","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"São achados de uma Intoxicação Digitálica diversos aspectos no ECG, sendo\nINCORRETO apenas um dos itens listados:","options":{"A":"Depressão de ST-T de concavidade superior (onda T ?em colher?).","B":"Aumento do intervalo QTc.","C":"Na intoxicação digitálica, podem ocorrer várias arritmias, predominando a extrassistolia\nventricular.","D":"Presença das arritmias taquicardia bidirecional"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-175107","number":"175107","sourceNumber":"175107","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O Pediatra deve suspeitar de intoxicação exógena sempre que o paciente apresentar,\nEXCETO:","options":{"A":"Hipoglicemia severa.","B":"Crises convulsivas sem antecedente pessoal de epilepsia.","C":"Arritmia cardíaca em paciente jovem sem antecedente pessoal de doença cardíaca.","D":"Diarréia."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-175120","number":"175120","sourceNumber":"175120","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"As jararacas são responsáveis por 90% dos acidentes ofídicos no Brasil. As principais\ncomplicações do acidente botrópico são, EXCETO:","options":{"A":"Síndrome Compartimental.","B":"Necrose de partes moles.","C":"Insuficiência Respiratória Aguda.","D":"Infecção bacteriana no local da picada."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-158065","number":"158065","sourceNumber":"158065","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 52 anos de idade é levada ao pronto-socorro pelos respectivos familiares\nque a encontraram desmaiada na própria casa,\nao lado de um bilhete de suicídio e de várias\ncartelas vazias de diazepam. Na apresentação, a paciente está com Glasgow 7. Não se sabe o\nperíodo de tempo desde a ingestão do medicamento. Além das medidas de suporte à vida que\ndevem ser instituídas, nesse caso pode-se utilizar um antídoto. Considerando o caso clínico\ndescrito, assinale a alternativa que apresenta esse antídoto.","options":{"A":"N-acetilcisteína.","B":"Flumazenil.","C":"Naloxona.","D":"Carvão ativado.","E":"Bicarbonato de sódio."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-129014","number":"129014","sourceNumber":"129014","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente com 23 anos de idade foi vítima de acidente ofídico e procurou\natendimento médico queixando-se de pouca dor\nno local da picada, boca seca, diplopia, dificuldade\nde deglutição, dores musculares generalizadas, oligúria e urina com coloração vermelha escura. Ao\nexame, apresentou ptose palpebral bilateral, midríase e plegia dos pares cranianos III, IV e VI. O\nresultado do exame de urina evidenciou mioglobinúria. Com base nesse caso hipotético, assinale a\nalternativa que apresenta o tipo de acidente ofídico descrito.","options":{"A":"Crotálico.","B":"Botrópico.","C":"Laquético.","D":"Elapídico.","E":"Colubrídeo."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-138717","number":"138717","sourceNumber":"138717","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"No atendimento do Pronto-Socorro é admitido um jovem de 19 anos, de origem\nindígena, que narra ter sido vítima de uma\npicada de cobra na mão direita, há aproximadamente 30\nminutos, relatando dor local. Você constata edema e equimose local. Outros habitantes da aldeia\nonde reside o rapaz trouxeram a cobra sem vida ao hospital na esperança de que isso pudesse\najudar na identificação da espécie da cobra que o havia picado. À observação, nota-se que a cobra\ntem fosseta loreal e cauda lisa. Considerando o quadro clínico, as características da cobra e a\nepidemiologia brasileira dos envenenamentos por animais peçonhentos, que tipo de soro antiofídico\ndeverá ser administrado?","options":{"A":"Soro antilonômico.","B":"Soro anticrotálico.","C":"Soro antibotrópico.","D":"Soro antilaquético.","E":"Soro antielapídico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-368163","number":"368163","sourceNumber":"368163","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Considere que um homem chega ao pronto atendimento com relato de acidente ofídico.\nOs exames feitos demonstraram alteração da\natividade de protrombina, PTT e fibrinogênio. São\ndiagnósticos diferenciais desse acidente, exceto:","options":{"A":"Crotálico","B":"Elapídico","C":"Botrópico","D":"Laquético"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-336306","number":"336306","sourceNumber":"336306","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 24 anos, admitido na emergência após ingesta de uma cartela de fluoxetina e\nde diazepam em tentativa de suicidio há 1 hora.\nAo exame: PA: 130/80 mmhg, FC: 72 bpm, tempo\nde enchimento capilar preservado, glasgow 12, TAX: 36,7°C. A conduta mais adequada é:","options":{"A":"Monitorização hemodinâmica e observação","B":"Flumazenil","C":"Lavagem gástrica","D":"Administração de carvão ativado"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-283920","number":"283920","sourceNumber":"283920","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança de 3 anos é trazida ao pronto-socorro por ter ingerido, há cerca de 3\nhoras, alguns medicamentos de sua avó, que\ntem hipertensão arterial, asma e diabetes mellitus. A\ncriança é admitida no hospital com saturação arterial de 97%, frequência cardíaca de 45 bpm,\npressão arterial de 60 x 35 mmHg, frequência respiratória de 18 mpm e glicemia capilar de 250 g/dl.\nO mais provável medicamento envolvido na intoxicação desta criança é um:","options":{"A":"Diurético.","B":"Corticoide.","C":"Bloqueador do canal de cálcio.","D":"Inibidor da monoamina oxidase.","E":"Hipoglicemiante oral."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-255657","number":"255657","sourceNumber":"255657","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O médico regulador recebe uma ligação de uma Unidade de Saúde que está atendendo\num caso de intoxicação por produto não\nidentificado inalado pelo paciente. Que medida de suporte\nefetiva pode ser tomada para descontaminação inalatória? MARQUE A CORRETA:","options":{"A":"Oxigênio (gás umidificado a 100%).","B":"Nebulização com soro fisiológico 0,9%.","C":"Corticosteróide inalado por via oral.","D":"Aspiração com pressão positiva."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-246804","number":"246804","sourceNumber":"246804","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre o uso medicinal da planta Cannabis sativa, é errado afirmar que:","options":{"A":"Os mais conhecidos componentes farmacologicamente ativos são o THC (tetrahidrocanabidinol)\ne CDB (canabidiol).","B":"Tanto o THC quanto o CDB possuem efeitos psicoativos.","C":"O Conselho Federal de Medicina aprovou, em 2014, o uso da Cannabis para tratamento da\nepilepsia na criança e no adolescente, refratária ao tratamento convencional.","D":"Em maio de 2017 a Cannabis sativa foi incluida no Brasil na categoria de ?planta medicinal?.","E":"Frente às evidências científicas de qualidade, disponíveis no momento, a prescrição segura de\ncanabidinoides para o manejo de sintomas de transtorno do espectro autista não deve ser indicada."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-199622","number":"199622","sourceNumber":"199622","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher de 23 anos é admitida em pronto-socorro tendo sido encontrada em seu\ndomicílio com nível de consciência rebaixado.\nAo exame físico apresenta-se torporosa, com pupilas\nmióticas, com tremores e fasciculações, frequência respiratória = 10 irpm, frequência cardíaca =\n118 bpm, saturação periférica de O2 = 92%, sialorreia, roncos pulmonares difusos, bulhas\ncardíacas rítmicas e normofonéticas. Assinale a alternativa CORRETA sobre o caso relatado.","options":{"A":"Descontaminação gástrica e administração de carvão ativado são contraindicados devido ao\nrisco de broncoaspiração.","B":"Uso de benzodiazepínicos deve ser evitado devido ao risco de piora do quadro neurológico.","C":"A pralidoxima é a medicação mais eficaz na reversão dos sintomas respiratórios e deve ser\niniciada o mais precocemente possível.","D":"O tratamento farmacológico deve ser feito com atropina, a despeito da frequência cardíaca\nelevada."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-202758","number":"202758","sourceNumber":"202758","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Intoxicação exógena é o conjunto de efeitos nocivos representados por manifestações\nclínicas ou laboratoriais que revelam o\ndesequilíbrio orgânico produzido pela interação de um ou\nmais agentes tóxicos com o sistema biológico. Em relação à intoxicação exógena, marque ?V? para\nverdadeiro ou ?F? para falso: ( ) Agente tóxico é uma substância química, quase sempre de origem\nantropogênica, capaz de causar dano a um sistema biológico, alterando uma ou mais funções,\npodendo provocar a morte. ( ) Os complexos eventos envolvidos na intoxicação, desde a exposição\nàs substâncias químicas até o parecimento de sinais e sintomas, podem ser desdobrados, para fins\nde operacionalização da vigilância em saúde, em quatro fases descritas, tradicionalmente, como as\nfases da intoxicação. ( ) A fase de exposição corresponde ao contato do agente tóxico com o\norganismo. Nessa fase é importante considerar, entre outros fatores, a via de incorporação do\nagente tóxico, a dose ou concentração do mesmo, suas propriedades físico-químicas, bem como o\ntempo durante o qual se deu a exposição. ( ) Na fase clínica há evidências de sinais e sintomas, ou\nainda alterações patológicas detectáveis mediante provas diagnósticas, caracterizando os efeitos\nnocivos provocados pela interação da substância química com o organismo. ( ) A intoxicação\ncrônica pode manifestar-se por meio de inúmeras doenças, que atingem vários órgãos e\n\nsistemas, com destaque para os problemas neurológicos, imunológicos, endocrinológicos,\nhematológicos, dermatológicos, hepáticos, renais, malformações\ncongênitas, tumores, dentre\noutros.","options":{"A":"F ? F ? V ? V ? V","B":"F ? F ? V ? V ? F","C":"V ? F ? F ? V ? V","D":"V ? V ? V ? V ? V","E":"F ? F ? V ? F ? F"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-220305","number":"220305","sourceNumber":"220305","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente psiquiátrico ingeriu substância cáustica como tentativa de autoextermínio. Foi\nsolicitada uma endoscopia na urgência que apresentou ulcerações profundas no esôfago. Para\ndiagnóstico de conduta desse caso clínico, assinale a alternativa CORRETA:","options":{"A":"A endoscopia deveria ter sido evitada para diminuir risco de perfuração.","B":"A classificação de Zargar seria de 2b, o que pode orientar o tratamento adequado.","C":"A ingestão de ácidos causa mais lesões no esôfago do que no estômago.","D":"A sondagem nasogástrica está contraindicada."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-196748","number":"196748","sourceNumber":"196748","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Dr. Adivan é Teleconsultor de referência para Municípios do Interior e recebe uma\ndúvida sobre mordida de morcego, em que o\nprofissional pergunta se pode fazer a higiene da ferida\ncom água e sabão e procurar o serviço de saúde no dia seguinte (aproximadamente 6 horas após o\nacidente). Marque a CORRETA:","options":{"A":"Todos os ferimentos por morcego são considerados graves, a procura deve ser imediata","B":"Pode-se esperar por 12 horas para iniciar a vacina após o acidente com morcegos","C":"O tempo de 6 horas é o limite, não se pode esperar mais que isso","D":"Tudo vai depender do estado imunológico da pessoa afetada"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-148554","number":"148554","sourceNumber":"148554","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher de 26 anos admitida no pronto socorro com quadro agudo de agitação\npsicomotora, desorientação alopsíquica, tremores,\ndiaforese. Ao exame físico apresentava midríase\nbilateral, hipertonia muscular, hiperreflexia, sinal de Babinski positivo bilateralmente, PA=180x100\nmmHg, FC=124 bpm. O quadro clínico citado pode estar relacionado ao uso das seguintes\nsubstâncias, exceto:","options":{"A":"Metilenodioximetanfetamina.","B":"Ácido lisérgico dietilamino.","C":"Diacetilmorfina.","D":"Buspirona.","E":"Cocaína."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-155404","number":"155404","sourceNumber":"155404","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um lactente de 1 ano e 8 meses ingeriu um medicamento, acidentalmente, em altas\ndoses. Ao exame apresentava-se com hipoventilação, hipotensão e miose. A droga suspeita da\nintoxicação exógena e o seu antídoto são, respectivamente:","options":{"A":"Barbitúrico; flumazenil.","B":"Barbitúrico; n-acetilcisteína.","C":"Opioide; metadona.","D":"Opioide; naloxone.","E":"Opioide; cetamina."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-131645","number":"131645","sourceNumber":"131645","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um homem de 58 anos tenta o suicídio ingerindo grande quantidade de antidepressivos\ntricíclicos. Chega ao Pronto Socorro comatoso,\ntaquicárdico e com os familiares relatando um\nepisódio convulsivo. No eletrocardiograma, observa-se alargamento do QRS. A principal medida\nterapêutica específica a ser adotada é:","options":{"A":"Bicarbonato de sódio.","B":"Hemodiálise.","C":"Propranolol.","D":"Gluconato de cálcio.","E":"Fenitoína."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-102756","number":"102756","sourceNumber":"102756","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente admitido no pronto-socorro após tentativa de autoextermínio, apresentando\nsonolência, bradicardia, pupilas puntiformes\nbilateralmente, hipersalivação, tosse com secreção\nhialina e diarreia aquosa profusa, sem controle esfincteriano. Considerando o caso descrito, além\ndas medidas básicas iniciais de suporte à vida, assinale a alternativa que apresenta a MELHOR\nconduta para tentar reverter esse quadro.","options":{"A":"Administrar atropina EV 1 mg, de 10 em 10min, até a recuperação dos valores normais e dos\nníveis séricos de acetilcolinesterase.","B":"Administrar epinefrina EV 1 mg, de 10 em 10min, até correção completa da bradicardia, miose e\nsonolência.","C":"Administrar atropina EV 1 mg, de 10 em 10min, até melhorar a hipersalivação, broncorreia e\ndiarreia.","D":"Administrar neostigmina EV 1 mg, de 10 em 10min, até a recuperação dos valores normais e\ndos níveis séricos de acetilcolinesterase."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-77366","number":"77366","sourceNumber":"77366","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente 66 anos, com história de estenose aórtica moderada em ecocardiograma\nrealizado no ano de 2011, deu entrada no\npronto-socorro do HECI em setembro de 2013 em\nedema agudo de pulmão grave, foi intubada após sedação com midazolan fentanil e transferida ao\nCTI. No CTI foi medicada com diuréticos e antihipertensivos, foi mantida sob sedação apenas com\npropofol, repetido ecocardiograma mostrando agora estenose aórtica grave. Após melhora\nsignificativa da radiografia de tórax, cerca de 36 horas da admissão, foi suspensa sedação com\ndespertar imediato, porém devido à agitação psicomotora, foi extubada sem a realização do teste\nde respiração espontânea. Logo após, e devido extrema agitação psicomotora, hipertensão\n(210x100) e taquicardia sinusal (150bpm), apresentou recidiva do edema pulmonar sendo\nreintubada. Novamente medicada e sedada com propofol, sendo acrescido risperidona para\ncontrole da agitação psicomotora apresentada. Neste mesmo dia da reintubação e devido mudança\ndo aspecto secreção pulmonar, foi colhida cultura de aspirado traqueal. Um dia após iniciou febre.\nDois dias após, resultado da cultura do aspirado com S. aureus multisensível sendo iniciado\nOxacilina. Neste mesmo dia a febre permaneceu constante, elevada, em torno de 39,5-40 graus,\nacompanhada de tremores generalizados, refratária ao tratamento antitérmico e compressas de\ngelo. Manteve este mesmo padrão de febre persistente após 48 horas de antibiótico, acompanhado\nainda de labilidade pressórica significativa, leucocitose de 35000 com PCR de 60 e alteração leve\nde TGO e TGP. Hipótese diagnóstica e causa refratariedade da febre?: Em relação ao caso\ndescrito, marque a alternativa mais pertinente entre as abaixo:","options":{"A":"Dosagem de CK total e uso de dantrolene.","B":"Colher novas hemoculturas e fazer novo teste de sensibilidade a oxacilina.","C":"Realização de ecocardiograma transesofágico e contato com a equipe de cirurgia cardíaca.","D":"Realização de tomografia de seios da face e de mastoide.","E":"Realização de tomografia de crânio e início de Anfotericina B."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-87438","number":"87438","sourceNumber":"87438","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A intoxicação com qual das substâncias a seguir pode cursar com necrose por\nliquefação ocasionar saponificação das gorduras, dissolução de proteinas e emulsificação de\nmembranas lipídicas, levar à necrose tissular e à trombose de pequenos vasos?","options":{"A":"Organofosforados.","B":"Benzodiazepinicos.","C":"Ácidos.","D":"Álcalis.","E":"Anticolinérgicos."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-43987","number":"43987","sourceNumber":"43987","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma paciente de 35 anos, com antecedentes psiquiátricos, deu entrada no\n\nPronto-Socorro com história de rebaixamento de consciência após tentativa de suicídio. A mesma\nfoi encontrada próximo a várias caixas de\nremédios. À admissão, a paciente encontrava-se\nsonolenta, porém com períodos de agitação e euforia, com sudorese profusa, febril (38,5° C),\nhipotensa (90/50 mmHg), com abalos mioclônicos na face e no tronco e com hiperreflexia global.\nDentre os fármacos abaixo, qual o que mais provavelmente foi abusivamente ingerido pela\npaciente?","options":{"A":"Diazepam.","B":"Lamotrigina.","C":"Fluoxetina.","D":"Carbamazepina.","E":"Fenobarbital."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-8099","number":"8099","sourceNumber":"8099","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A atenção às intoxicações exógenas na emergência baseia-se em:","options":{"A":"Prevenção da Absorção para a ingestão tóxica de salicilatos, anticolinérgicos, tricíclicos,\nnarcóticos neuroléptico.","B":"Os eméticos, como xarope de ipeca, são usados na prevenção da absorção nos casos de\ningestão de salicilatos, cáusticos, petróleo e derivados.","C":"A dose do carvão ativado, VO ou por sonda, é indicada como emético para intoxicação com\nfenobarbital e digital.","D":"Os cárticos, como sulfato de magnésio, são eficazes e sem efeitos colaterais nas intoxicações\nexógenas.","E":"O tratamento medicamentoso específico da intoxicação e as depurações das substâncias tóxicas\ningeridas, renal e extra-renal são as primeiras medidas em todos os casos."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-355621","number":"355621","sourceNumber":"355621","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre intoxicações agudas, marque (V) para verdadeiro e (F) para falso ao que se\nafirma nos itens abaixo: ( ) Anfetaminas e\nderivados da ergotamina podem causar intoxicação com\nhiperatividade adrenérgica. ( ) Amitriptilina pode causar síndrome anticolinérgica com\nmanifestações de tremor, taquicardia e agitação. ( ) Carbamatos e organofosforados produzem\nsíndrome adrenérgica com quadro típico de bradicardia, miose, hipersalivação e fasciculações. ( )\nEm casos graves da síndrome de abstinência do álcool etílico, o paciente pode apresentar tremor,\nsudorese e confusão; nunca apresenta alucinações, convulsões e arritmias. ( ) Pralidoxima é um\ndos antídotos utilizados para intoxicação de organofosforados. Marque o item que apresenta a\nsequência correta, de cima para baixo:","options":{"A":"V - V- F - F - F","B":"V - V - F - F - V","C":"F - F - V - V - F","D":"F - F - F - V ? V"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-330067","number":"330067","sourceNumber":"330067","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Inúmeros são os mecanismos pelos quais uma substância ou um elemento químico age\nno nível tóxico que podem auxiliar o\nclínico na predição de sinais e sintomas frente a uma\nintoxicação aguda ou crônica. Considerando tais mecanismos, está descrito CORRETAMENTE:","options":{"A":"Asfixiantes simples, por competição pela hemoglobina, como faz o CO.","B":"Asfixiantes químicos, por ocupação do espaço pelo O2 na árvore traqueobrônquica alveolar.","C":"Inibições de enzimas possuidoras de grupos SH pelo chumbo, mercúrio e arsênio.","D":"Inibição da cadeia de formação da hemoglobina pelo gás sulfídrico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-331998","number":"331998","sourceNumber":"331998","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação aos cuidados no acidente botrópico podemos incluir:","options":{"A":"Atenção às feridas locais que se manifes- tam dolorosas, equimóticas e com edema significativo,\npodendo evoluir com comprometimento sistêmico\ncom choque, anúria e hemorragias graves.","B":"Indicação da quantidade de soroterapia específica para o acidente se baseia na classificação da\ngravidade da sintomatologia, devendo ser aplicada por via intravenosa em período até 72 horas do\nacidente.","C":"Soroterapia deve ser sempre específica para o tipo de acidente relatado; por isso a importância\nde se encontrar o animal responsável, a fim\nde solicitar o soro recomendado, não havendo\nrecomendação de repetições de doses.","D":"Escolha do antimicrobiano deve ser instituída o mais precocemente possível devido ao alto risco\nde infecção local, considerando os agentes patógenos presentes na cavidade oral da cobra."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-295391","number":"295391","sourceNumber":"295391","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Diante de um acidente por animal peçonhento, a ação imediata recomendada é:","options":{"A":"aplicar um torniquete no local da picada.","B":"colocar compressa de água doce gelada.","C":"lavar a região afetada e manter o paciente deitado.","D":"remover o veneno por sucção."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-318004","number":"318004","sourceNumber":"318004","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A maioria dos acidentes ofídicos no Brasil é ocasionada por serpentes do grupo\nBothrops, seguido pelo grupo Crotalus. As\nregiões brasileiras onde há maior incidência são Norte e\nCentro-Oeste. Os meses de maior frequência de acidentes são os quentes e chuvosos, períodos de\nmaior atividade em áreas rurais. Em relação aos acidentes ofídicos em pediatria, o principal exame\nutilizado tanto para diagnóstico como para avaliação de eficácia do tratamento é:","options":{"A":"Tempo de coagulação.","B":"Tempo de sangramento.","C":"Função renal.","D":"Enzimas musculares."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-258180","number":"258180","sourceNumber":"258180","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um homem de 45 anos foi internado em unidade de terapia intensiva com quadro de\ncrises epilépticas. Havia histórico de trauma\ncranioencefálico há seis meses; com fratura de calota\ncraniana e contusão cerebral frontal, sem necessidade de tratamento cirúrgico. Foi prescrito\ndiazepam 20 mg diluído EV e, em seguida, fenitoína na dose de 20 mg/kg realizado nas 8 horas\nseguintes e mantido a dose de 200 mg de 8/8 h de manutenção. O peso do paciente era de 70 kg\ne, após o medicamento, as crises cessaram. Cinco dias após, o paciente desenvolveu quadro de\nataxia, confusão mental e agitação psicomotora. No exame neurológico havia nistagmo bidirecional.\nNesse caso, qual a conduta a ser instituída?","options":{"A":"Colher um líquor, pois deve ter havido contaminação, e o paciente está apresentando quadro de\nencefalite.","B":"Dosar o nível sérico da fenitoína e suspender a droga, pois provavelmente é uma intoxicação\npela droga.","C":"Realizar uma tomografia, pois com o histórico de trauma deve ter feito um hematoma que\nagravou o caso.","D":"Pedir um hemograma e eletrólitos, pois deve ter tido uma infecção secundária à internação da\nUTI."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-257790","number":"257790","sourceNumber":"257790","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Adolescente ingeriu grande quantidade de benzodiazepínico, na tentativa de se matar.\nPorém, seu pai a encontrou caída, inconsciente, mas com vida, no chão do seu quarto, ao lado de\nalgumas caixas da medicação. Rapidamente, a levou ao pronto-socorro. O pediatra, sabendo\ndestas informações, deve prescrever:","options":{"A":"Naloxone.","B":"Gluconato de cálcio.","C":"N-acetilcisteína.","D":"Flumazenil."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-246558","number":"246558","sourceNumber":"246558","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre intoxicação em pediatria, julgue os itens a seguir. I. As exposições a intoxicações\nem crianças entre 6 e 12 anos são muito menos\ncomuns, correspondendo aproximadamente a 6%\ndos casos. II. As exposições tóxicas entre os adolescentes são primariamente intencionais ou\nocupacionais. III. As intoxicações por organofosforados comumente se manifestam clinicamente\ncom sialorreia, lacrimejamento e midríase bilateral. Pode-se afirmar que:","options":{"A":"todos os itens estão certos.","B":"apenas os itens I e II estão certos.","C":"apenas os itens II e III estão certos.","D":"apenas os itens I e III estão certos.","E":"nenhum item está certo."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-241727","number":"241727","sourceNumber":"241727","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sabe-se que mais de 90% das intoxicações de crianças ocorre em ambiente domiciliar\ne a maioria envolve uma única substância.\nConsiderando-se as intoxicações exógenas em\nPediatria, julgue os itens seguintes. I. A ingestão é a via mais comum de intoxicação,\ncorrespondendo a cerca de 77% dos casos. II. Aproximadamente metade dos casos de intoxicação\nexógena envolve um produto de uso doméstico não farmacológico. III. Mais de 85% dos casos de\nintoxicação exógena em pediatria não requerem intervenção médica, por se tratar de um produto\npouco tóxico ou cujo contato (ingesta, inalação etc) ocorreu com quantidade insuficiente para\nproduzir toxicidade. Pode-se afirmar que:","options":{"A":"apenas os itens I e II estão corretos.","B":"todos os itens estão corretos.","C":"apenas o item I está correto.","D":"apenas o item II está correto.","E":"nenhum dos itens está correto."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-215377","number":"215377","sourceNumber":"215377","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A intoxicação crônica pode manifestar-se por meio de inúmeras doenças, que atingem\nvários órgãos e sistemas; somente está INADEQUADA uma das alternativas. Indique-a.","options":{"A":"Destaque para os problemas neurológicos, imunológicos, endocrinológicos, hematológicos,\ndermatológicos, hepáticos, renais, malformações congênitas, tumores, entre outros.","B":"Os efeitos danosos sobre a saúde humana aparecem no decorrer de uma única exposição, que\nnormalmente ocorrem durante longos períodos de tempo.","C":"Os quadros clínicos são indefinidos, inespecíficos, sutis, gerais, de longa evolução e muitas\nvezes irreversíveis.","D":"Os diagnósticos são difíceis de serem estabelecidos e há uma maior dificuldade na associação\ncausa/efeito, principalmente quando há exposição de longo prazo a múltiplos produtos."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-210554","number":"210554","sourceNumber":"210554","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Com relação aos achados oculares associados às intoxicações exógenas, assinale a\ncorrelação correta entre o sintoma e o agente.","options":{"A":"Miose: anfetaminas.","B":"Midríase: narcóticos.","C":"Nistagmo: paracetamol.","D":"Oftalmoplegia: nicotina.","E":"Crise oculógira: haloperidol."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-215388","number":"215388","sourceNumber":"215388","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Intoxicação exógena é o conjunto de efeitos nocivos representados por manifestações\nclínicas ou laboratoriais que revelam o\ndesequilíbrio orgânico produzido pela interação de um ou\nmais agentes tóxicos com o sistema biológico. Podemos, apenas, aceitar como CORRETO um\nitem. Aponte-o.","options":{"A":"Os complexos eventos envolvidos na intoxicação, desde a exposição às substâncias químicas\naté o aparecimento de sinais e sintomas, não\npodem ser desdobrados.","B":"A compreensão destas fases permite definir melhor as abordagens do ponto de vista de\nvigilância em saúde, assistência, prevenção e promoção da saúde das populações expostas e\nintoxicadas por substâncias químicas.","C":"Corresponde ao contato do agente tóxico com o organismo. Nessa fase não é importante\nconsiderar, entre outros fatores, a via de\nincorporação do agente tóxico, a dose ou concentração do\nmesmo, suas propriedades físico-químicas, bem como o tempo durante o qual se deu a exposição.","D":"A suscetibilidade da população exposta é, também, fator sem importância a ser considerado."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-215397","number":"215397","sourceNumber":"215397","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"As intoxicações às substâncias químicas podem ser agudas e crônicas, e poderão se\nmanifestar de forma leve, moderada ou grave, a depender da quantidade da substância química\nabsorvida, do tempo de absorção, da toxicidade do produto, da suscetibilidade do organismo e do\ntempo decorrido entre a exposição e o atendimento médico. As intoxicações agudas são\ndecorrentes de uma única exposição ao agente tóxico ou mesmo de sucessivas exposições, desde\nque ocorram num prazo médio de 24 horas, sendo INADEQUADO apenas um item. Marque-o.","options":{"A":"Podendo causar efeitos imediatos sobre a saúde.","B":"Na intoxicação aguda, o estabelecimento da associação causa/efeito é mais evidente, uma vez\nque se conhece o agente tóxico.","C":"Pode ocorrer de forma leve, moderada ou grave.","D":"Manifesta-se através de um conjunto de sinais e sintomas, que se apresentam de forma\nprogressiva, alguns minutos ou algumas horas após\na exposição excessiva de um indivíduo ou de\num grupo de pessoas."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-215410","number":"215410","sourceNumber":"215410","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Vale salientar que um indivíduo com intoxicação aguda também pode apresentar sinais\ne/ou sintomas de intoxicação crônica. Assim,\npodemos CONCORDAR que, sempre que alguém sair\nde um quadro de intoxicação aguda,","options":{"A":"não deve ser seguido ambulatoriamente para investigação de efeitos tardios e, se for o caso,\nmonitoramento da exposição de longo prazo e investigação de intoxicação crônica.","B":"deve ser seguido ambulatoriamente para investigação de efeitos tardios e, se for o caso,\nmonitoramento da exposição de longo prazo e investigação de intoxicação crônica.","C":"deve ser seguido ambulatoriamente para investigação de efeitos agudos apenas, se for o caso,\nmonitoramento da exposição de longo prazo e investigação de intoxicação crônica.","D":"deve ser seguido ambulatoriamente para investigação de efeitos tardios e, se for o caso,\nmonitoramento da exposição de longo\n\nprazo, mas não da investigação de intoxicação crônica."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-217060","number":"217060","sourceNumber":"217060","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 82 anos, sexo feminino, portadora de hipertensão e osteoartrite de quadril\nem uso de crônico de tramadol, admitida com\nconfusão mental de 12 horas de evolução, nega\nfebre ou diarreia. Ao exame, escala de coma de Glasgow 10, estável hemodinamicamente, glicemia\ncapilar de 72, pupilas mióticas, sem rigidez de nuca ou deficit focais, TC de crânio, ECG e rastreio\nlaboratorial com EAS normais. Acerca do manejo clínico, assinale a alternativa correta.","options":{"A":"Recomenda-se teste terapêutico com naloxona.","B":"É indicada RM de crânio para investigação de evento cerebrovascular.","C":"Punção lombar e EEG são mandatórios nesses casos.","D":"Deve-se proceder com intubação orotraqueal.","E":"A antibioticoterapia deve anteceder o rastreio laboratorial."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-202695","number":"202695","sourceNumber":"202695","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual é o acidente ofídico mais comum em nosso estado, e que pode cursar com lesão\nrenal aguda?","options":{"A":"Botrópico.","B":"Crotálico.","C":"Elapídico.","D":"Lachético."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-201714","number":"201714","sourceNumber":"201714","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Leia o caso clínico a seguir. P., de 19 anos, apresenta febre alta há quatro dias que\nevolui com frequência cardíaca de 130 bpm,\ntaquipneia, pressão arterial oscilando entre 95 x 50\nmmHg e 170 x 100 mmHg, rigidez muscular, tremores e, há 24 horas, desorientação temporal e\nespacial, flutuação do nível de consciência, discurso confuso e alucinações visuais. Previamente\nera hígido, exceto pelo diagnóstico recente de esquizofrenia para o qual foi medicado com\nhaloperidol, 10 mg por dia, há cerca de duas semanas. O hemograma vem com leucócitos de\n16.000, sem desvio à esquerda, CPK de 12.000 (VR = 22 a 334); DHL = 800 (240?480); TGO = 120\n\n(VR até 40); TGP = 130 (VR até 56). O EAS veio sem leucocitúria, a radiografia de tórax está\nnormal. Exame do liquor sem indícios de\ninfecção. Tomografia de crânio sem lesões expansivas ou\nhemorrágicas. Hemocultura ainda sem resultado. Qual é o diagnóstico mais provável e qual é a\nconduta adequada?","options":{"A":"Sepse de origem desconhecida com delirium ? aumentar a dose do haloperidol e\nantibioticoterapia de largo espectro.","B":"Meningite asséptica ? manter o haloperidol e sintomáticos até resolução espontânea.","C":"Síndrome neuroléptica maligna ? suspender haloperidol e iniciar bromocriptina.","D":"Síndrome catatônica da esquizofrenia ? trocar o antipsicótico por um de segunda geração."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-217054","number":"217054","sourceNumber":"217054","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O termo \"intoxicação exógena\" refere-se às consequências clínicas e/ou bioquímicas\ndecorrentes da exposição aguda a substâncias encontradas no ambiente ou isoladas. Sobre as\nintoxicações na infância, assinale a alternativa correta.","options":{"A":"Na toxíndrome anticolinérgica, predominam os efeitos parassimpatolíticos, como rubor facial,\nretenção urinária, agitação psicomotora, alucinações e delírios.","B":"Na toxíndrome anticolinesterásica, em que ocorre inibição da enzima acetilcolinesterase,\npredominam os efeitos simpatomiméticos, como\nexcitação cardíaca e do sistema nervoso central.","C":"A intoxicação por cianeto é potencialmente fatal e ocorre exclusivamente por ingestão de\nalimentos/drogas em que está presente.","D":"Na intoxicação por ingestão de produtos de limpeza (alvejantes, desinfetantes e detergentes),\ndeve-se estimular vômito e realizar lavagem\ngástrica e carvão ativado o mais breve possível.","E":"A intoxicação por plantas é, normalmente, intencional, resultante da curiosidade em conhecer o\nambiente. Por sua característica exploradora, crianças acima dos 10 anos de idade costumam ser\nas principais vítimas."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-178796","number":"178796","sourceNumber":"178796","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente do sexo feminino, 17 anos, é trazida pelos familiares que informam que ela\ningeriu vários comprimidos de clonazepam e\namitriptilina há aproximadamente 50 minutos. Ao\nexaminá-la foram notadas as seguintes alterações: Glasgow 8 (resposta ocular: 2; resposta verbal:\n2; resposta motora: 4), pupilas midríaticas fotorresponsivas, FC: 58 bpm, PA: 94x68 mmHg, FR: 19\nirpm; SpO2: 94%em ar ambiente. Eletrocardiograma de emergência demonstra BAV 2º grau Mobitz\ntipo I. São condutas possíveis a serem tomadas, exceto:","options":{"A":"administrar Flumazepil.","B":"realizar lavagem gástrica.","C":"admistrar carvão ativado em múltiplas doses.","D":"intubação orotraqueal e ventilação mecânica.","E":"alcalinização sérica com carga de sódio."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-187585","number":"187585","sourceNumber":"187585","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A tríade coma, miose e depressão respiratória é muito sugestiva de superdosagem de:","options":{"A":"cocaína.","B":"álcool.","C":"opioides.","D":"benzodiazepínicos."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-174136","number":"174136","sourceNumber":"174136","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um atendimento preciso e rápido é essencial para a ausência de sequelas quando uma\ncriança sofre intoxicação exógena. Para isto, qual a correlação entre a substância tóxica e o\nrespectivo antídoto?","options":{"A":"Benzodiazepínicos - naloxone.","B":"Opiáceos - atropina.","C":"Bloqueadores beta-adrenérgicos - glucagon.","D":"Organofosforados - flumazenil."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-157263","number":"157263","sourceNumber":"157263","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Para qual das intoxicações exógenas a seguir estão contraindicados a lavagem gástrica\ne o carvão ativado?","options":{"A":"Antidepressivos tricíclicos.","B":"Corrosivos (ácidos e álcalis).","C":"Digoxina.","D":"Inseticidas Organofosforados.","E":"Metanol."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-154616","number":"154616","sourceNumber":"154616","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual medicação é utilizada para combater os efeitos da overdose de opioides no\nrecém-nascido na sala de parto?","options":{"A":"atropina","B":"dobutamina","C":"milrinona","D":"naloxona","E":"dopamina"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-150780","number":"150780","sourceNumber":"150780","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Criança é trazida para a emergência por ingestão de soda cáustica. Após medidas\ngerais adotadas, o médico deverá prescrever:","options":{"A":"Gelatina dissolvida em água ou clara de ovo.","B":"Xarope de ipeca.","C":"Lavagem gástrica.","D":"Carvão ativado."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-136615","number":"136615","sourceNumber":"136615","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente, sabidamente usuário de substâncias ilícitas, dá entrada no hospital agitado,\ncom dor torácica, dispneia e mal-estar\ngeral. Seu monitor cardíaco demonstra alteração de\nrepolarização de VE, além de uma taquicardia de 180 bpm. Sua pressão é de 195 x 120 mmHg.\nAcompanhante refere uso de cocaína. Qual das condutas abaixo PODE agravar o quadro de\nintoxicação?","options":{"A":"Propranolol.","B":"Diazepam.","C":"Haloperidol.","D":"Nitroprussiato de Sódio."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-127260","number":"127260","sourceNumber":"127260","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Apresenta interesse clínico, o conhecimento dos antídotos relacionados à\nintoxicação, tanto por venenos, quanto por medicações, estando INCORRETA, a seguinte\nrelação, assinale-a.","options":{"A":"Paracetamol / Acetilcisteína.","B":"Diazepan / Naloxone.","C":"Metanol / Etanol.","D":"Carbamato / Atropina."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-111382","number":"111382","sourceNumber":"111382","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação às intoxicações exógenas, que associação não representa uma opção\nterapêutica?","options":{"A":"Barbitúrico X hemodiálise.","B":"Fenobarbital X diurese alcalina.","C":"Monóxido de carbono X Oxigenoterapia hiperbárica.","D":"Lítio X hemodiálise.","E":"Salicilatos X hemodiálise."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-103736","number":"103736","sourceNumber":"103736","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 6 anos, proveniente de área rural, queixa-se de dor na mão direita quando\nestava brincando em uma área pedregosa. Houve\npiora do quadro e o paciente evoluiu com\nhipertensão arterial, taquicardia, taquipneia e edema agudo pulmonar. Além do suporte avançado\nde vida, esse paciente deve fazer uso de:","options":{"A":"Altas doses de atropina.","B":"Soro antibotrópico.","C":"Soro antiescorpiônico ou antiaracnídeo.","D":"Soro antitetânico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-78143","number":"78143","sourceNumber":"78143","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Na madrugada do dia 27 de janeiro de 2013, 232 vítimas adultas jovens faleceram\nimediatamente durante o incêndio em uma boate\nna cidade de Santa Maria, RS. Dos sobreviventes\n88 pacientes foram admitidos em UTIs com graves lesões inalatórias e extensões variáveis de\nsuperficie corporal queimada, além de outros traumatismos de gravidade moderada em sua\nmaioria. Esse foi o segundo maior incêndio em número de vítimas fatais na história brasileira.\n\nJORNAL BRASILEIRO DE PNEUMOLOGIA 2013. Considerando-se a dimensão dessa tragédia,\ninúmeros foram os esforços para o atendimento às vítimas. Em situações como essas, quais são\nos principais agentes de intoxicação?","options":{"A":"Cianeto de hidrogênio e monóxido de carbono.","B":"Cianeto de hialuridôneo e monóxido de carbono.","C":"Cianeto de hidrogênio e dióxido de hialuridôneo.","D":"Cianeto de hialuridôneo e dióxido de carbono."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-78150","number":"78150","sourceNumber":"78150","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A síndrome neuroléptica maligna é uma complicação associada ao uso de\nantipsicóticos. Embora rara, é considerada grave e\nsua ocorrência está associada a uma taxa de\nmortalidade entre 20 e 30%. Constitui um sintoma tipicamente encontrado em pacientes nesta\ncondição:","options":{"A":"hiperpirexia","B":"ideação suicida","C":"agranulocitose","D":"diarreia profusa"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-85396","number":"85396","sourceNumber":"85396","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente do sexo feminino, 47 anos de idade, deu entrada no Pronto-Socorro com\nquadro de confusão mental de início\nprogressivo há dois dias. Associado ao quadro sonolência,\nletargia, mudança de humor e de personalidade, movimentos anormais e tremores nas mãos e,\nsegundo o acompanhante, diminuição do volume urinário. Ao exame físico, apresenta PA: 60 x 40\nmmHg, alguns hematomas nos MMSS e tronco. Sem hepato ou esplenomegalia. Icterícia discreta\n(+4/4+). Ritmo respiratório irregular. Feito ECG: bradicardia sinusal. Antecedentes: crises\nconvulsivas na adolescência em uso diário de carbamazepina e fenitoína. Faz uso esporádico de\nálcool. História de cefaleia com uso frequente de analgésicos (paracetamol) em excesso. Nega\ntabagismo, HAS ou DM. Sobre o caso acima, assinale a alternativa CORRETA.","options":{"A":"Deve-se iniciar anticoagulação com heparina de baixo peso molecular.","B":"É necessária a avaliação laboratorial: AST; ALT; TAP/INR; dosagens de fator V e VII da\ncoagulação.","C":"Avaliação laboratorial deve incluir D-dímero, BNP, glicemia e troponina.","D":"Punção lombar é mandatória nesse caso."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-85382","number":"85382","sourceNumber":"85382","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O consumo de drogas ilícitas é um problema grave de saúde pública mundial. No Brasil,\nestima-se que existam 900.000 usuários de cocaína. Em vista desse quadro, é importante saber\nlidar com os dependentes e com as consequências crônicas e agudas do uso de cocaína e crack.\n\nSobre esse assunto, verifica-se o seguinte:","options":{"A":"os sintomas psicóticos da intoxicação aguda por cocaína devem ser tratados com neurolépticos\nfenotiazínicos como a clorpromazina.","B":"o dissulfiran apresenta benefício no tratamento do dependente de cocaína, aumentando a\npossibilidade de manutenção em abstinência.","C":"pela análise do cabelo é possivel fazer diagnóstico do consumo de cocaína de até 360 dias\npregressos.","D":"a dosagem de cocaína e seus metabólicos nos líquidos corporais tem valor no diagnóstico do\nuso crônico dessas substâncias."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-48503","number":"48503","sourceNumber":"48503","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Toxicômano dá entrada na emergência com crise convulsiva. O médico que o atende\nsuspeita de intoxicação aguda por cocaína, porque há concomitantemente:","options":{"A":"Hipotermia e nistagmo.","B":"Arritmia cardíaca e nistagmo.","C":"Arritmia cardíaca e hipertermia.","D":"Hipotermia e hipertensão arterial.","E":"Hipotermia e hipotensão arterial."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-49029","number":"49029","sourceNumber":"49029","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente do sexo masculino, encontrado caído na rua, aparentando meia-idade,\ninconsciente e em fasciculação, roupa suja de\nvômitos, fezes e urina. Ao exame físico: miose;\nsialorreia; broncorreia; PA inaudível; FC de 35 bpm e sem sopro cardíaco. Ap. respiratório: sibilos\ne\nroncos inspiratórios e expiratórios. Abdome com ruídos hidroaéreos aumentados. Baseado no caso\nclínico, marque a alternativa CORRETA:","options":{"A":"A intoxicação digitálica é muito comum nos pacientes com insuficiência cardíaca sistólica e a\nsíncope por baixo débito é muito comum.","B":"O botulismo é uma doença neuromuscular grave decorrente da exotoxina botulínica que é\nproduzida pelo Clostridium botulinum.","C":"A intoxicação com organofosforados é comum mesmo nos grandes centros devido ao uso de\ninseticidas organofosforados (malathion) para o combate da epidemia de dengue.","D":"A intoxicação por carbamato/paraquat ocorre principalmente em lavradores, e apresenta, além\ndos sintomas neuromusculares, a plegia do nervo oculomotor extrínseco e tetraparesia flácida\nproximal.","E":"Pacientes com epilepsia que fazem uso irregular podem apresentar uma hiperreatividade\nlevando a um quadro de intoxicação exógena por\nantidepressivos tricíclicos."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-35612","number":"35612","sourceNumber":"35612","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um homem de 24 anos dá entrada no pronto-socorro com queixa de dor em aperto na\nregião retroesternal. Relata ter usado cocaína inalatória há cerca de 40 minutos. Está sudoreico,\ncom extremidades frias, pupilas dilatadas e fasciculações na pálpebra esquerda; pulso = 124\nbat/min, PA = 180 x 90, T = 36,9ºC, frequência respiratória de 24 mr/min, com ausculta cardíaca e\npulmonar normais, pulsos centrais e periféricos palpáveis e simétricos. O médico deve de imediato:","options":{"A":"Administrar betabloqueador VO ou EV.","B":"Administrar flumazenil EV.","C":"Confirmar a intoxicação através de exame de urina.","D":"Solicitar eletrocardiograma.","E":"Administrar naloxona IM ou EV."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-34090","number":"34090","sourceNumber":"34090","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança de um ano de idade, sexo masculino, foi picada por um escorpião quando\nbrincava no quintal de sua casa há cerca de duas horas. A mãe disse que a criança apresentava\nchoro contínuo desde o momento do acidente. Ao exame: chorava muito e foi observado um ponto\núnico de picada no pé direito. Apresentava dispneia leve e bradicardia. Que conduta deve ser\ntomada, nesse caso?","options":{"A":"Anestésico local e observar durante algumas horas\n\npara avaliar a necessidade de aplicação do soro antiescorpiônico.","B":"Anestésico local associado ao soro antiescorpiônico endovenoso, sem diluição.","C":"Anestésico local e anti-inflamatório não hormonal de horário.","D":"Anestésico local e teste de sensibilidade antes da\naplicação do soro antiescorpiônico."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-176140","number":"176140","sourceNumber":"176140","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Lactente de 1 ano e 6 meses de vida, internado na UTI Pediátrica por pneumonia com\nderrame pleural, evoluiu com fadiga progressiva, gemência e queda da saturação de oxigênio,\napesar da instituição da ventilação não invasiva. Durante a intubação, o bebê apresentou\ndiminuição da expansibilidade torácica muito reduzida e necessidade de aumento de pressão para\nventilação adequada. O antagonista que deverá ser administrado para reverter a rigidez torácica é:","options":{"A":"Flumazenil","B":"Neostigmina","C":"Naloxane","D":"Pralidoxima","E":"Etomidato"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-131923","number":"131923","sourceNumber":"131923","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Correlacione o agente tóxico e seu respectivo antídoto.","options":{"A":"Acetaminofeno - Piridoxina.","B":"Opióides - Octreotide.","C":"Varfarina - vitamina K.","D":"Organofosforado - Azul de Metileno.","E":"Metemoglobinizantes - Dexferroxamin."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-105708","number":"105708","sourceNumber":"105708","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Analise as afirmativas abaixo e marque a opção CORRETA:","options":{"A":"No Brasil, o acidente ofídico mais comum é o crotálico e o que mais mata é o botrópico.","B":"O acidente elapídico é o único dentre os acidentes ofídicos que não causa sintomas\nneurológicos.","C":"O acidente ofídico é o acidente com animais peçonhentos mais comum no Brasil.","D":"O acidente botrópico pode levar a fácies miastênica e mialgia generalizada.","E":"O acidente crotálico é o único dentre os acidentes ofídicos que pode provocar rabdomiólise."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-342370","number":"342370","sourceNumber":"342370","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente do sexo masculino, de 19 anos de idade, residente na Comunidade Mauá do\nMunicípio de Codó, Estado do Maranhão, foi picado por uma cobra iararacucu, na face lateral da\nperna direita, quando caçava em campo aberto com seu pai, cerca de 15:00 h do dia 21 de\nfevereiro de 2019, deu entrada na Unidade de Pronto Atendimento com sintomatologia Grave:\nalterações locais intensas, hemorragia grave, hipotensão/choque, insuficiência renal, anúria; pode\nhaver distúrbio na coagulação. Considerando a espécie da cobra e gravidade do acidente, qual a\nmelhor conduta?","options":{"A":"administrar Soro antibotrópico (pentavalente), 2 a 4 ampolas.","B":"administrar Soro anticrotálico, 5 ampolas.","C":"administrar Soro antibotrópico (pentavalente) e anticrotálico, 12 ampolas.","D":"administrar Soro antielapídico (bivalente), 20 ampolas.","E":"administrar Soro antibotrópico (pentavalente) e antiluético, 10 ampolas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-342404","number":"342404","sourceNumber":"342404","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre a Monkeypox é INCORRETO afirmar:","options":{"A":"Os primatas não humanos (macacos) são reservatórios do vírus.","B":"O aumento recente da incidência guarda relação com a interrupção da vacinação contra a\nvaríola.","C":"Na África o aumento da incidência tem relação com a maior invasão de habitats de animais que\nsão reservatórios do vírus.","D":"A Transmissão se dá por gotículas de saliva ou respiratórias.","E":"O contato com exsudato de feridas promove a transmissão."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-342411","number":"342411","sourceNumber":"342411","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale a opção que contém o antídoto indicado para as intoxicações por paracetamol.","options":{"A":"Atropina","B":"Piridoxina","C":"Flumazenil","D":"N-Acetilcisteína","E":"Glucagon"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-308628","number":"308628","sourceNumber":"308628","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente do sexo masculino, de 19 anos de idade, residente na Comunidade Mauá do\nMunicípio de Codó, Estado do Maranhão, foi picado por uma cobra jararacucu na face lateral da\nperna direita, quando caçava em campo aberto com seu pai. Cerca de 15h do dia 21 de fevereiro\nde 2019, deu entrada na Unidade de Pronto Atendimento com sintomatologia grave: alterações\nlocais intensas, hemorragia grave, hipotensão/choque, insuficiência renal, anúria; pode haver\ndistúrbio na coagulação. Considerando a espécie da cobra e gravidade do acidente, qual a melhor\nconduta na situação descrita?","options":{"A":"Administrar Soro antibotrópico (pentavalente), 2 a 4 ampolas.","B":"Administrar Soro anticrotálico, 5 ampolas.","C":"Administrar Soro antibotrópico (pentavalente) e anticrotálico, 12 ampolas.","D":"Administrar Soro antielapidico (bivalente), 20 ampolas.","E":"Administrar Soro antibotrópico (pentavalente) e antilaquetico, 10 ampolas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-308645","number":"308645","sourceNumber":"308645","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A história e o exame físico são extremamente importantes na avaliação inicial do\npaciente com intoxicação aguda no pronto-socorro. Nesse contexto, a presença de\n\nmiose-bradicardia e hipersalivação aponta para:","options":{"A":"síndrome dissociativa.","B":"síndrome de hiperatividade adrenérgica.","C":"síndrome hipoativa.","D":"síndrome anticolinérgica.","E":"síndrome colinérgica."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-278927","number":"278927","sourceNumber":"278927","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre as intoxicações por agrotóxicos, muito comum em trabalhadores rurais, assinale\na opção correta:","options":{"A":"Os organofosforados aumentam a ação da enzima acetilcolinesterase.","B":"A maioria das intoxicações agudas é causada pelos agrotóxicos organoclorados.","C":"Os carbamatos reduzem a atividade da enzima acetilcolinesterase.","D":"Os inseticidas utilizados na pulverização têm baixa absorção cutânea e por isso mesmo têm\nbaixo impacto nos quadros de intoxicações.","E":"Apresentam, de uma forma geral, quadro clínico caracterizado por sinais e sintomas que\nocorrem pelo aumento da ação da acetilcolinesterase."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-244647","number":"244647","sourceNumber":"244647","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente do sexo masculino, se 19 anos de idade, residente na Comunidade Mauá do\nmunicípio de Codó, Estado do Maranhão, foi picado por uma cobra jararacucu, na face lateral da\nperna direita, quando caçava em campo aberto com seu pai, cerca de 15h, do dia 21 de fevereiro\nde 2019, deu entrada na Unidade de Pronto Atendimento com sintomatologia Grave: alterações\nlocais intensas, hemorragia grave, hipotensão/choque, insuficiência renal, anúria; pode haver\ndistúrbio na coagulação. Considerando a espécie da cobra e a gravidade do acidente, a melhor\nconduta é administrar soro","options":{"A":"antibotrópico (pentavalente), 2 a 4 ampolas.","B":"anticrotálico, 5 ampolas.","C":"antibotrópico (pentavalente) e anticrotálico, 12 ampolas.","D":"antielapídico (bivalente), 20 ampolas.","E":"antibotrópico (pentavalente) e antilaquético, 10 ampolas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-250397","number":"250397","sourceNumber":"250397","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente procedente do interior do estado foi vítima de picada de cobra e apresenta o\nseguinte quadro clínico: dois orifícios em perna esquerda, com formigamento no local, sem dor.\n\nApesar de responder a solicitação tem dificuldade de manter olhos abertos. Queixa de visão turva e\ndiplopia. Apresenta mal-estar, irritabilidade, náuseas, cefaleia e mialgia. Relata ainda diurese\nescura. Com o quadro clínico citado, a qual grupo pertence a serpente responsável pelo acidente?","options":{"A":"Bothrops.","B":"Crotalus.","C":"Lachesis.","D":"Micrurus.","E":"Etapidae."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-203585","number":"203585","sourceNumber":"203585","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale a opção que reúne as alterações clínicas da síndrome colinérgica nas\nintoxicações exógenas.","options":{"A":"Agitação/midríase/taquicardia.","B":"Coma/hipertemia/taquicardia.","C":"Agitação/hipotermia/bradicardia.","D":"Coma/miose/bradicardia.","E":"Coma/hipertemia/taquicardia."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-139961","number":"139961","sourceNumber":"139961","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 20 anos chega ao pronto-socorro, após uso de cocaína, apresentando\nagitação psicomotora e sudorese. A pressão arterial\né de 200 x 120 mmHg, e a frequência cardíaca\né de 138 bpm. A melhor conduta terapêutica é:","options":{"A":"Propranolol.","B":"Nifedipina sublingual.","C":"Metroprolol.","D":"Benzodiazepínicos.","E":"Furosemida."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-87504","number":"87504","sourceNumber":"87504","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Escolar de 6 anos de idade, 25 kg, apresenta febre intermitente há 3 dias sem outras\nqueixas. Mãe vem fazendo uso regular de 10\nml de Tylenol bebê a cada 6h para controle de picos\nfebris. A cerca de 12h, evoluiu com vômitos incoercíveis que não melhoram com a administração de\n25 gts de Plasil. Admitido no pronto-socorro pediátrico, o exame físico inicial revela icterícia\n1+/4+,\ndistensão abdominal, fígado palpável a 2 cm do rebordo costal direito. Exames laboratoriais\nmostram leucograma 12.400 leucócitos/mm³ com 52% de segmentados sem desvio, TGO 560 U/L,\nTGP 487 U/L, bilirrubina direta 4,8 mg/dl. Ultrassonografia de abdômen total com hepatomegalia e\nascite. Qual o diagnóstico mais provável e tratamento adequado?","options":{"A":"Intoxicação por acetaminofeno; acetilcisteína oral ou EV;","B":"Gastrite; bloqueador H2;","C":"Hepatite B; imunoglobulina hiperimune;","D":"Hepatite A; vacina anti-hepatite A;","E":"Hepatite transinfecciosa; antibioticoterapia EV."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-65624","number":"65624","sourceNumber":"65624","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação à rabdomiólise, é CORRETO afirmar que:","options":{"A":"O consumo de álcool etílico é uma das mais importantes causas de miopatia e rabdomiólise,\nsendo responsável por 20% dos casos.","B":"A mioglobinúria é uma característica invariável da rabdomiólise e sua ausência exclui o\ndiagnóstico.","C":"Hiperfosfatemia e hipercalcemia são observadas precocemente com frequência na rabdomiólise.","D":"A dosagem da CK, por si só, já permite predizer quais pacientes progredirão para insuficiência\nrenal mioglobinúrica.","E":"A Coagulação Intravascular Disseminada (CIVD) é uma complicação que raramente ocorre na\nrabdomiólise."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-52460","number":"52460","sourceNumber":"52460","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"As assertivas abaixo correlacionam substâncias e medicamentos com os respectivos\nantídotos e/ou antagonistas. Assinale a\nassociação CORRETA:","options":{"A":"Intoxicação por betabloqueadores ? glucagon.","B":"Intoxicação por cianetos ? ácido dimercaptosuccínico.","C":"Intoxicação por chumbo ? azul de metileno.","D":"Intoxicação por hipoglicemiantes orais ? fitomenadiona.","E":"Intoxicação por opioides ? flumazenil."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-330852","number":"330852","sourceNumber":"330852","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 20 anos, do sexo masculino, chega ao pronto socorro após ser picado por\ncobra no tornozelo direito, há 3h, em zona\nrural próximo a Cuiabá. Ele chega apresentando:\nsonolência, prostração, vômitos, fáceis miastênica (ptose palpebral bilateral e flacidez da\nmusculatura da face), diplopia e mialgia importante. Refere pouca dor na região da picada. Quando\nfoi passada a sonda vesical, constatou-se urina de cor escura (cor de chá preto). Esse caso trata-se\nde um acidente do tipo","options":{"A":"Botrópico.","B":"Crotálico.","C":"Laquético.","D":"Elapídico."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-316010","number":"316010","sourceNumber":"316010","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Correlacione agente tóxico e seu respectivo antídoto:","options":{"A":"Acetaminofeno; piridoxina","B":"Opioides; octreotida","C":"Varfarina; vitamina K","D":"Organofosforado; azul de metileno","E":"Metemoglobinizante; desferroxamina"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-274117","number":"274117","sourceNumber":"274117","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente, J.R.S., 29 anos, deu entrada no PA apresentando vômito, tontura, dor de\ncabeça, fala arrastada e diarreia. A esposa\nrelatou que o paciente começou a se queixar de\nparestesia na língua e na região perioral, a apresentar náusea, fraqueza progressiva bilateral dos\nmembros superiores e inferiores, cerca de 30 min depois da ingestão de ensopado de vísceras de\npeixe Baiacu. Análise dos restos do ensopado detectou níveis elevados de tetrodotoxina (TTX), que\natua como","options":{"A":"bloqueador dos receptores de sódio voltagem dependente.","B":"agonista de receptores de potássio.","C":"inibidor dos receptores de nicotínicos de acetilcolina.","D":"ativador dos receptores de cálcio tipo L."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-254187","number":"254187","sourceNumber":"254187","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre o uso de carvão ativado como medida de descontaminação, assinale a\nalternativa INCORRETA:","options":{"A":"Absorve a maioria dos fármacos ingeridos quando administrado dentro de 1 hora da ingestão.","B":"Sua administração em pessoas torporosas ou comatosas deve ser feito com proteção de via\naérea (intubação traqueal).","C":"Seu uso deve ser rotineiro nas ingestões de álcalis como a soda cáustica e de solventes\norgânicos como gasolina ou querosene.","D":"O carvão atividade é administrado por via oral ou via SNG a cada 4 horas podendo ser repetido\npor até 10 doses."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-214602","number":"214602","sourceNumber":"214602","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um trabalhador rural de 28 anos dá entrada no PS trazido por amigos, com história de\npicada por cobra há três horas, sem visualização de detalhes do animal, que fugiu. O paciente\nrefere dor local leve. Também queixa-se de mialgia, dificuldade para articular bem as palavras e\nvisão embaçada e dupla. Exames laboratoriais mostram alterações relevantes como tempo de\ncoagulação alargado, leucocitose sem desvio à esquerda e EAS com urina de aspecto escuro,\nporém sem hematúria. O quadro clínico-laboratorial descrito permite o diagnóstico de qual tipo de\nacidente ofídico?","options":{"A":"Botrópico.","B":"Laquético.","C":"Elapídico.","D":"Crotálico."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-221386","number":"221386","sourceNumber":"221386","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Das alternativas citadas abaixo, qual é a que NÃO representa uma suspeita de\nintoxicação exógena?","options":{"A":"Arritmia cardíaca em paciente jovem sem antecedente pessoal de doença cardíaca.","B":"Hipoglicemia severa.","C":"Crises convulsivas sem antecedente pessoal de epilepsia.","D":"Diarreia."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-217947","number":"217947","sourceNumber":"217947","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"São contraindicações à lavagem gástrica, em caso de intoxicação:","options":{"A":"Colecistectomia recente.","B":"Varizes abdominais grosseiras.","C":"Ingestão de hidrocarbonetos com alta volatilidade.","D":"Hipersialose."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-208547","number":"208547","sourceNumber":"208547","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O fármaco considerado antídoto para a toxicidade causada pela atropina é:","options":{"A":"adrenalina","B":"fenilefrina","C":"fisostigmina","D":"propranolol","E":"tropicamida"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-177329","number":"177329","sourceNumber":"177329","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma mulher de 30 anos foi admitida na Unidade Básica de Saúde com história de\ningestão intensional de soca cáustica há 45\nminutos. Ao exame físico, está consciente, com SatO?\n\n= 96%, FC = 85 bpm e PA = 110 x 70 mmHg; a orofaringe revela edema de mucosa e ulcerações.\nA conduta deve abranger, com a paciente em jejum:","options":{"A":"acesso venoso periférico e remoção para hospital terciário para realizar endoscopia digestiva\nnas primeiras 24 horas","B":"passagem de sonda gástrica, manutenção em drenagem e encaminhamento da paciente para\nserviço de endoscopia digestiva nas primeiras 72 horas","C":"passagem de sonda nasoenteral, dieta enteral precoce para evitar translocação bacteriana e\nencaminhamento da paciente para serviço de endoscopia digestiva","D":"passagem de sonda gástrica, lavagem gástrica com soro fisiológico a 0,9% e encaminhamento\nda paciente, nas primeiras 12 horas, para serviço\nde endoscopia digestiva","E":"acesso venoso periférico, passagem de sonda gástrica, evitando a estenose esofágica, e\nremoção para hospital terciário para endoscopia digestiva em 72 horas."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-159407","number":"159407","sourceNumber":"159407","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher de 19 anos é trazida à UPA de Sinop, inconsciente, por tentativa de suicídio\ncom ingestão de raticida cumarínico e sedativos\nbenzodiazepínicos há menos de uma hora.\n\nAssinale a alternativa CORRETA em relação ao manejo deste caso.","options":{"A":"Deve ser procedida a intubação traqueal antes da administração de carvão ativado via sonda\nnasogástrica.","B":"Deve ser procedida realização imediata de lavado gástrico para reduzir a absorção das\nsubstâncias ingeridas quando administrado em até 1 hora da sua ingestão.","C":"Está indicada administração de N-acetilcisteína e bicarbonato de sódio via sonda nasogástrica.","D":"Atualmente a administração de carvão ativado está reservada para os casos de intoxicação\naguda por álcalis cáusticos."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-159426","number":"159426","sourceNumber":"159426","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente masculino, 45 anos, cortador de cana, foi picado por uma Jararaca em\ntornozelo direito. No atendimento inicial são esperadas as seguintes manifestações, EXCETO:","options":{"A":"Ptose palpebral.","B":"Hematúria.","C":"Bolha e Equimose no local da picada.","D":"Edema na região da picada."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-156449","number":"156449","sourceNumber":"156449","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"VMT, 22 anos, sexo feminino, levada ao pronto-socorro pelo namorado após tentativa\nde suicídio. Ao exame, apresentava-se com Glasgow\n10, miótica, bradicárdica, com muitas\nsecreções brônquicas e sibilos difusos. Qual agente é compatível com a síndrome apresentada?","options":{"A":"Raticida cumarínico.","B":"Amitriptilina.","C":"Fenobarbital.","D":"Organofosforados."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-75424","number":"75424","sourceNumber":"75424","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino de 8 anos de idade foi picado por cobra. Quando examinado, duas horas após\no acidente ofídico, o menino apresentava-se\ncom dor intensa, edema importante e bolhas no\nmembro afetado, hematúria macroscópica e Pressão Arterial (PA) ? de 80 x 30 mmHg. Exame de\nsangue ? incoagulável. (Pressão Arterial para essa idade: sistólica varia de 88?110 mmHg e\ndiastólica de 58?78 mmHg). Para o tratamento, o médico precisa classificar o quadro quanto à\ngravidade e prescrever o tipo de soro adequado para o caso. Assinale a alternativa que apresenta a\nclassificação do caso e o tipo de soro que essa criança deve receber.","options":{"A":"Caso moderado e soro anticrotálico.","B":"Caso moderado e soro antibotrópico.","C":"Caso grave e soro antibotrópico.","D":"Caso grave e soro antilaquético."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-332986","number":"332986","sourceNumber":"332986","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino de 2 anos deu entrada no pronto-socorro após ter ingerido um frasco de\nparacetamol. O pediatra de plantão deverá estar atento para o risco de a criança apresentar:","options":{"A":"sinais de hepatotoxicidade.","B":"hemólise maciça.","C":"depressão respiratória.","D":"sintomas extrapiramidais."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-333018","number":"333018","sourceNumber":"333018","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente com 14 anos estava fazendo uma trilha em local de mata nativa e foi picado\nno tornozelo direito. Apresentou imediata e\nsignificativa dor local, com edema que rapidamente\nprogrediu pela perna e, após 1 hora, atingiu a coxa, dificultando a deambulação. Apresentou\nequimoses e pequenas bolhas de conteúdo seroso no local da picada e não foi observada qualquer\nmanifestação neurológica. Essa apresentação clínica caracteriza um acidente:","options":{"A":"Botrópico.","B":"Elapídico.","C":"Loxoscélico.","D":"Escorpiônico."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-309773","number":"309773","sourceNumber":"309773","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente com história de ingesta intencional de 20 comprimidos de clonazepam há\nduas horas da admissão. Qual medicamento\nestaria indicado em caso de depressão respiratória\nneste caso?","options":{"A":"Flumazenil","B":"Dipirona","C":"Vitamina K","D":"N-acetil cisteina","E":"Domperidona"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-286104","number":"286104","sourceNumber":"286104","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Febre é uma queixa comum nos pacientes de clínica médica. Pode estar relacionada a\ndoenças infecciosas, síndromes inflamatórias neoplásicas, doenças auto-imunes. Em qual das\ncausas abaixo, o uso de dantrolene é terapia específica no controle:","options":{"A":"Síndrome neuroléptica maligna","B":"Lúpus eritematoso sistêmico","C":"Neutropenia febril","D":"Crise tireotóxica","E":"Sepse"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-274962","number":"274962","sourceNumber":"274962","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Decorre da compressão do feixe vasculonervoso consequente ao grande edema que se\ndesenvolve no membro atingido, produzindo isquemia de extremidades. As manifestações mais\nimportantes são: dor intensa, parestesia, diminuição da temperatura do segmento distal, cianose e\ndéficit motor. SOUSA, T. C.J. Picadas de cobras, aranhas e escorpiões. In: GUSSO G. (Org);\nLOPES, J. M. C. (Org); DIAS, L. C Tratado de Medicina de Família e Comunidade: princípios,\nformação e prática. 2a. ed. Porto Alegre. Artmed, 2019. A descrição se refere a uma das possíveis\ncomplicações de acidentes com animais peçonhentos considerados graves. Assinale a alternativa\nem que está corretamente nomeada.","options":{"A":"Infecção secundária, sem abcesso.","B":"Síndrome compartimental.","C":"Isquemia renal secundária.","D":"Insuficiência respiratória aguda.","E":"Choque."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-274965","number":"274965","sourceNumber":"274965","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A vítima queixa-se de dor em queimação no local da picada, associada à edema: febre\ne mal-estar podem ocorrer. Após 24 horas, a\nlesão evolui tipicamente com uma bolha ou equimose\ncentral circundada por um halo pálido (isquêmico), seguido de uma área de eritema. Ao longo dos\ndias, a lesão central evolui para necrose, que pode atingir grande extensão e profundidade. O\nacidente também pode dar origem a um quadro de víscera, que envolve febre, calafrios, cefaleia,\nnáuseas, vômitos, urina cor de \"lavado de carne\", icterícia e anemia, podendo evoluir para\ncoagulação intravascular e insuficiência renal aguda. A descrição refere-se às manifestações de\nacidente ocasionado por um animal peçonhento do gênero (SOUSA, T. C. J. Picadas de cobras,\naranhas e escorpiões. In: GUSSO, G. (Org.); LOPES, J. M. C. (Org.); DIAS, L. C. Tratado de\nMedicina da Família e Comunidade: princípios, formação e prática (2ª ed. Porto Alegre: Artmed,\n2019):","options":{"A":"Loxosceles.","B":"Phoneutria.","C":"Latrodectus.","D":"Tityus.","E":"Micrurus."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-221279","number":"221279","sourceNumber":"221279","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Das alternativas citadas abaixo, qual é a que NÃO representa uma suspeita de\nintoxicação exógena?","options":{"A":"Arritmia cardíaca em paciente jovem sem antecedente pessoal de doença cardíaca.","B":"Hipoglicemia severa.","C":"Crises convulsivas sem antecedente pessoal de epilepsia.","D":"Diarreia."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-214032","number":"214032","sourceNumber":"214032","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Considerando os acidentes com a serpentes laquéticas e elapídicas, assinale V para as\nafirmativas verdadeiras e F para as falsas. ( ) O quadro clínico decorrente do acidente com láquesis\npode ser confundido com o de crotalos, uma vez que os seus venenos apresentam atividades\nfisiopatológicas semelhantes, assim os pacientes podem apresentar náuseas, vômitos, sudorese,\ndores abdominais, diarreia, hipotensão e choque. ( ) Os pacientes picados por serpentes laquéticas\ndevem ser obrigatoriamente monitorados continuadamente, e a hipotensão deve ser prontamente\ncorrigida com cristaloides, acrescentando-se, se necessário, fármacos vasoativos. ( ) Assim como\nnos acidentes com os botropes, na região da picada de serpentes elapídicas, não há alterações\nsignificativas pela ausência de ação inflamatória local, mas pode haver mialgia localizada, e o\npaciente apresenta sinais com sialorreia, constrição de garganta, deglutição difícil, disfonia,\nnáuseas e vômitos, bem como sintomas neurológicos e diminuição progressiva da força muscular. (\n\n) Nos acidentes com serpentes elapídicas, a atenção ao padrão respiratório é primordial e, em\nhavendo sinais de insuficiência respiratória,\ndevem ser feitos a intubação do paciente com cânula\nendotraqueal e o suporte ventilatório por meio de ventilação pulmonar mecânica. ( ) As\nmanifestações de origem vagal nos acidentes elapídicos indicam maior gravidaade, o que exige\numa maior dose de soro antiveneno (20 ampolas ao invés de 10). Assinale a sequência correta de\ncima para baixo.","options":{"A":"V - F - V - F - F","B":"F - V - V - F - V","C":"V - F - F - V - V","D":"F - V - F - V - F","E":"V - V - F - V - V"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-177158","number":"177158","sourceNumber":"177158","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente masculino, 19 anos, picado no antebraço direito por uma serpente. Admitido e\ninternado no Hospital em cerca de 2 horas após. Apresentando edema discreto no antebraço\ndireito, dor intensa no local, náuseas e vômitos, que coincidiam com cólicas abdominais\nparoxísticas, além de sudorese, visão turva, discreta epistaxe e diarréia; a frequência cardíaca, ao\ninício com 108 batimentos por minuto, chegando a 62 após a soroterapia e pressão arterial em\n130/80 mmHg; tempo de sangria em 4 min 15 seg, tempo de coagulação acima de 15 min, tempo\nde protrombina acima de 1 minuto. Após o anti-veneno o paciente evoluiu com melhora clínica;\ncontinuou assintomático até receber alta no terceiro dia, curado (textro extraído do artigo PARDAL\net al, 2007). Qual tipo desse veneno?","options":{"A":"Coagulante, proteolítico e hemorrágico","B":"Neurotóxico, miotóxico, coagulante","C":"Proteolítico, hemorrágico, coagulante e neurotóxico","D":"Neurotóxico pré e pós-sináptico"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-177162","number":"177162","sourceNumber":"177162","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente masculino, 19 anos, picado no antebraço direito por uma serpente. Admitido e\ninternado no Hospital em cerca de 2 horas após. Apresentando edema discreto no antebraço\ndireito, dor intensa no local, náuseas e vômitos, que coincidiam com cólicas abdominais\nparoxísticas, além de sudorese, visão turva, discreta epistaxe e diarréia; a frequência cardíaca, ao\ninício com 108 batimentos por minuto, chegando a 62 após a soroterapia e pressão arterial em\n130/80 mmHg; tempo de sangria em 4 min 15 seg, tempo de coagulação acima de 15 min, tempo\nde protrombina acima de 1 minuto. Após o anti-veneno o paciente evoluiu com melhora clínica;\ncontinuou assintomático até receber alta no terceiro dia, curado (textro extraído do artigo PARDAL\net al, 2007). Quanto ao gênero da cobra, assinale o CORRETO:","options":{"A":"Bothrops","B":"Crotalus","C":"Micrurus","D":"Laquesis"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-152329","number":"152329","sourceNumber":"152329","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre o tratamento com soro antiescorpiônico, considere as seguintes afirmações. I.\nDeve ser administrado por via oral.; II. Deve ser administrado independentemente do peso ou da\nidade do paciente.; III. Cada hora de atraso na aplicação do soro representa aumento de 13% no\nrisco de morte dos pacientes. É CORRETO o que se afirma, APENAS, em:","options":{"A":"I e II.","B":"I e III.","C":"II e III.","D":"II."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-155622","number":"155622","sourceNumber":"155622","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"J.P.H., de 44 anos, é internado no hospital 18 horas após ter ingerido uma grande\nquantidade de um medicamento desconhecido,\nna forma de comprimido. Apresenta-se confuso,\ntaquipneico, queixa-se de náusea, zumbido, e sua temperatura é de 39°C. As pupilas estão\nbilateralmente iguais e estão com um diâmetro de 3 mm e são reativas. Logo após sua chegada, o\npaciente começa a vomitar, a gasometria é significativa para um quadro misto, consistindo em\nalcalose respiratória e acidose metabólica. Os sintomas do paciente são sugestivos de uma\noverdose de:","options":{"A":"Aspirina.","B":"Acetaminofeno.","C":"Oxicodona.","D":"Difenidramina.","E":"Lítio."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-151007","number":"151007","sourceNumber":"151007","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Danilo com 7 anos de idade foi passar o final de semana no sítio dos avós e enquanto\nestava jogando bola, foi vítima de uma picada\nde cobra. Quais primeiros socorros devem ser\nrealizados?","options":{"A":"Lavar o local da picada com água e sabão e garrotear o membro.","B":"Lavar o local da lesão com água e sabão e manter o membro acometido elevado.","C":"Realizar pequenos cortes no local da lesão para drenagem do veneno.","D":"Sucção no local da picada e garroteamento do membro."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-81121","number":"81121","sourceNumber":"81121","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em uma suspeita de uma criança intoxicada por um opiáceo, o antídoto de escolha é:","options":{"A":"Naloxone","B":"Biperideno","C":"Flumazenil","D":"Atropina","E":"Fisostigmina"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-60228","number":"60228","sourceNumber":"60228","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paulo, 53 anos, morador do Pantanal sul-matogrossense, refere que há 18h foi vítima\nde picada de jararaca em dorso do pé esquerdo.\nApresenta-se pálido, com dor intensa e edema\nlocal com flictenas. É correto afirmar:","options":{"A":"Trata-se do gênero Crotalus responsável pela maioria dos acidentes ofídicos no Brasil.","B":"Seu veneno é proteolítico, coagulante e hemorrágico.","C":"Deve ser administrado o soro anticrotálico o mais breve possível, pois o tempo de exposição e\nvolume inoculado do veneno interfere na gravidade.","D":"Introdução de antimicrobianos está contraindicada.","E":"O torniquete pode minimizar a gravidade do acidente quando o socorro demorar."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-64932","number":"64932","sourceNumber":"64932","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Jovem de 16 anos é trazido ao pronto-socorro com história de ingestão de álcool e uso\nde crack, apresentando-se agitado,\nagressivo, sudoreico, taquicardíaco e com palidez importante.\nAo exame físico, apresenta frequência cardíaca de 150 bpm e pressão arterial de 190 x 110 mmHg.\nAo ser monitorizado, apresenta o seguinte traçado (VER IMAGEM): O paciente deve ser\ninicialmente tratado com:","options":{"A":"Propranolol e Diazepam.","B":"Nitroprussiato de sódio e Haloperidol.","C":"Manobra vagal e Propranolol.","D":"Adenosina e Diazepam.","E":"Manobra vagal e Haloperidol."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":["question_bank/media/medcurso/med-preventiva-med-pre-05/64932.png"],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-45959","number":"45959","sourceNumber":"45959","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um dos grupos de drogas que frequentemente são utilizadas com efeitos\nsedoanalgésicos são os benzodiazepínicos. Sobre estas drogas é CORRETO afirmar que:","options":{"A":"Apresenta alto índice terapêutico, propriedades ansiolíticas, sedativas e anticonvulsivantes e\ncausa amnésia anterógrada.","B":"Apresenta alto índice terapêutico, propriedades analgésicas marcantes, sedativas e\nanticonvulsivantes e causa amnésia anterógrada.","C":"Apresenta alto índice terapêutico, propriedades ansiolíticas, sedativas e anticonvulsivantes e\nnão causa amnésia.","D":"Apresenta propriedades ansiolíticas, sedativas e anticonvulsivantes e causa amnésia\nanterógrada, mas tem baixo índice terapêutico.","E":"Apresenta alto índice terapêutico, propriedades ansiolíticas, sedativas e anticonvulsivantes,\ncausa amnésia anterógrada e não apresenta risco de\ndesencadear síndrome de abstinência após\nsua retirada."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-45942","number":"45942","sourceNumber":"45942","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O envenenamento ocorrido pela inoculação do veneno do escorpião através do ferrão\npode causar alterações locais e sistêmicas e\no tipo de conduta terapêutica deve ser individualizada\npara cada caso dependendo da gravidade e idade dos pacientes. Considerando o quadro clínico e\no tratamento do envenenamento podemos ter: I- Presença apenas de dor no local da picada; o\ntratamento exige apenas sintomático para alívio da dor. II- O soro antiescorpiônico deve ser feito\nnos casos considerados moderados e graves. III- Os casos graves com óbitos estão associados ao\nescorpião amarelo e cuja picada ocorre em crianças abaixo de 14 anos sendo indicado infusão de\nsoro nesses casos nas primeiras horas após envenenamento. IV- As manifestações sistêmicas nos\ncasos graves são caracterizados por: vômitos, sialorreia, taquipneia e taquicardia. Qual assertiva\nestá corretas em relação a clínica e tratamento:","options":{"A":"I","B":"I e II","C":"II e III","D":"I, II, III","E":"I, II, III, IV"},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-34505","number":"34505","sourceNumber":"34505","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Quais dos sintomas abaixo são compatíveis com Síndrome Anticolinesterásica em\nquadro de Intoxicação Exógena:","options":{"A":"Sudorese e Salivação.","B":"Rubor Facial e Mucosas Secas.","C":"Hipertermia e Taquicardia.","D":"Mídriase e Retenção Urinária.","E":"Alucinações e Delírio."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-31912","number":"31912","sourceNumber":"31912","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Com relação à intoxicação exógena em crianças, é INCORRETO afirmar:","options":{"A":"O xarope de ipeca não é mais recomendado no tratamento inicial da intoxicação.","B":"A lavagem gástrica é de eficácia duvidosa e não deve ser mais realizada rotineiramente.","C":"O uso do carvão ativado deve ser usado na primeira hora após ingestão do tóxico para maior\neficácia.","D":"O reconhecimento da toxíndrome, juntamente com os exames laboratoriais, permite a\nidentificação mais rápida do agente causal e, consequentemente, a realização do tratamento\nadequado.","E":"Na etapa de eliminação do tóxico que já foi absorvido, com o objetivo de provocar uma diurese\nforçada e desde que o medicamento tenha um baixo volume de distribuição, utiliza-se, ainda, de\nescolha, o furosemida."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-330476","number":"330476","sourceNumber":"330476","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A doença monkeypox (varíola dos macacos) foi identificada em 1958, e é endêmica em\nalguns países africanos. Em maio de 2022, foram identificados casos na Europa e a doença\ndisseminou-se por vários países, incluindo o Brasil. Sobre a monkeypox é CORRETO afirmar:","options":{"A":"A principal forma de contágio ocorre por via sexual, com predomínio de casos em homens que\nfazem sexo com homens, sendo considerada uma infecção sexualmente transmissível","B":"Constitui medida de precaução em relação à atividade sexual, abstenção durante toda a\nevolução da doença e o uso de preservativo não elimina o risco de contágio","C":"É característico da monkeypox lesões em várias formas de evolução, observando-se\nfrequentemente a presença de máculas, pápulas,\nvesículas, pústulas e crostas em uma mesma\nregião do corpo","D":"Os macacos são considerados os principais reservatórios da doença"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-330529","number":"330529","sourceNumber":"330529","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Criança de dois anos de idade é atendida no Pronto Atendimento com quadro de febre\ne lesões vesiculares em face e membros, de\nsurgimento há sete dias. O médico que atende a\ncriança levanta a suspeita de Monkeypox. Em relação à doença, é CORRETO afirmar:","options":{"A":"A incubação dura em média de seis a 16 dias e pode chegar a 40 dias","B":"A manifestação cutânea típica é do tipo maculopapular, associada a febre e linfadenopatia","C":"O paciente deixa de transmitir a doença quando a crosta desaparece e há reepitelização","D":"Os sintomas duram de dois a sete dias"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-263060","number":"263060","sourceNumber":"263060","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Carlos, nove anos de idade, brincou durante o dia no jardim de sua casa. Pela\nmadrugada, acordou com dor no dorso da mão direita que apresenta uma lesão bolhosa, com\nprovável conteúdo serossanguinolento, com dois pontos sugerindo inoculação e uma área\neritematosa ao redor. Considerando a história e o aspecto da lesão, o acidente por animal\npeçonhento MAIS PROVÁVEL é:","options":{"A":"Aranha do gênero Loxosceles.","B":"Aranha do gênero Phoneutria.","C":"Escorpião ? Tityus serrulatus.","D":"Lacraia."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-174743","number":"174743","sourceNumber":"174743","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"C.D.E., 26 anos, sexo masculino, lavrador, foi vítima de picada de cobra em MIE. Cerca\nde 1 hora depois, apresentou no local da\npicada dor intensa, edema, equimose importante e\nformação de bolhas. Nega parestesias, dificuldades visual e respiratória. Ao exame não se\nconstatou ptose palpebral. O aspecto macroscópico da urina sugere hematúria. Em relação aos\nacidentes ofídicos, e a este particularmente, assinale a alternativa CORRETA:","options":{"A":"A dose do soro deve ser proporcional ao peso do paciente.","B":"A realização prévia de garroteamento do membro acometido e realização de um corte no local\npara sucção são medidas recomendadas.","C":"A dose do soro deve ser aplicada na região da picada.","D":"Há risco de insuficiência renal aguda e síndrome de compartimento."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-127414","number":"127414","sourceNumber":"127414","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação aos acidentes por animais peçonhentos e suas manifestações clínicas\nassociadas, marque a alternativa ERRADA:","options":{"A":"Acidente botrópico: não produz sintomas locais, exceto parestesia que progride pelo membro\npicado até acometimento da musculatura respiratória e asfixia.","B":"Acidente crotálico: dor na nuca, diminuição da visão e dificuldade para falar.","C":"Acidente por aranha do gênero loxosceles: edema, eritema e flictena no local da picada,\nevoluindo até úlcera extensa de difícil cicatrização.","D":"Escorpionismo: dor local, agitação, taquicardia, vômitos e priapismo."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-60340","number":"60340","sourceNumber":"60340","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"No que concerne aos acidentes ofídicos no Brasil, de grande relevância na área rural,\nsão válidas as seguintes afirmativas, EXCETO:","options":{"A":"A fácies miastênica ou neurotóxica constitui a expressão clínica mais comum no envenenamento\npor coral verdadeira (gênero Micrurus), ao\npasso que no envenenamento por surucucu-pico-de-jaca\n(gênero Lachesis) as manifestações clínicas são indistinguíveis daquelas observadas no acidente\nbotrópico, a menos que, no acidente laquético, apareçam manifestações vagais como bradicardia,\nhipotensão arterial, cólicas abdominais e diarreia.","B":"As manifestações locais (dor, edema, equimose, formação de bolhas e necrose cutânea) são\nevidentes nos acidentes por Crotalus durissus, mas inexpressivas nos acidentes por serpentes do\ngênero Bothrops.","C":"O gênero Bothrops responde pela maior parte das serpentes peçonhentas encontradas no País,\nao passo que o gênero Crotalus é representado\npor uma única espécie (Crotalus durissus).","D":"O veneno de Crotalus durissus provoca manifestações neurológicas (turvação visual, ptose\npalpebral, oftalmoplegia), rabdomiólise, mioglobinúria e insuficiência renal aguda."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-55348","number":"55348","sourceNumber":"55348","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 20 anos, lavrador, chega ao CTI, transferido de hospital do interior, com\nhistória de acidente ofídico há 48 horas. Apresenta-se com edema intenso na perna direita, algo\nconfuso e oligoanúrico. Exames iniciais mostram: Hb = 18 g%; ureia = 120 mg%; creatinina = 2,5\nmg%; glicose = 88 mg% e CPK total = 12000 Ul. Considerando-se o caso acima, quais seriam as\nalterações laboratoriais compatíveis com o quadro clínico do paciente?","options":{"A":"Hipercalemia e hipercalcemia.","B":"Hiperuricemia e hipofosfatemia.","C":"Hipocalemia e hipofosfatemia.","D":"Hipocalcemia e hipermagnesemia."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-342051","number":"342051","sourceNumber":"342051","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 24 anos de idade, é atendida na Unidade de Pronto Atendimento 20 minutos\napós acidente na praia com um animal hidrozoário\nconhecido como caravela-portuguesa (Physalia\nphysalis). Ao exame, apresenta extensas placas urticariformes lineares em região posterior do\ntórax. Diante do caso e considerando as orientações do Ministério da Saúde, Indique a substância\nmais adequada a ser usada sobre a área afetada, ainda no local do acidente:","options":{"A":"Água mineral.","B":"Urina.","C":"Água de coco.","D":"Água do mar."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-342052","number":"342052","sourceNumber":"342052","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 24 anos de idade, é atendida na Unidade de Pronto Atendimento 20 minutos\napós acidente na praia com um animal hidrozoário\nconhecido como caravela-portuguesa (Physalia\nphysalis). Ao exame, apresenta extensas placas urticariformes lineares em região posterior do\ntórax. Diante do caso e considerando as orientações do Ministério da Saúde, Identifique\ncomplicações que mais comumente se associam ao acidente com o animal peçonhento envolvido\nno caso:","options":{"A":"Convulsões e hemólise.","B":"Paraplegia e diarreia.","C":"Arritmia e anafilaxia.","D":"Necrose e insuficiência renal aguda."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-342053","number":"342053","sourceNumber":"342053","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 24 anos de idade, é atendida na Unidade de Pronto Atendimento 20 minutos\napós acidente na praia com um animal hidrozoário\nconhecido como caravela-portuguesa (Physalia\nphysalis). Ao exame, apresenta extensas placas urticariformes lineares em região posterior do\ntórax. Diante do caso e considerando as orientações do Ministério da Saúde, Indique a conduta\nmais adequada, neste momento:","options":{"A":"Usar ácido acético a 5% tópico.","B":"Aplicar soro heterólogo intravenoso.","C":"Aplicar sulfadiazina de prata tópica.","D":"Aplicar glicerina líquida tópica."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-262938","number":"262938","sourceNumber":"262938","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação ao acidente crotálico, assinale a alternativa incorreta.","options":{"A":"Em poucas horas pode ocorrer sangramento. A apneia pode ser causada pela fraqueza\nmuscular global e progressiva.","B":"Eritema, bolhas e equimose podem surgir precocemente no local da picada.","C":"Mialgia generalizada e insuficiência renal aguda (necrose tubular) são frequentemente\nobservadas.","D":"Ptose palpebral bilateral, disfagia e diplopia estão geralmente presentes."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-266631","number":"266631","sourceNumber":"266631","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Com os desmatamentos e as mudanças climáticas, os animais silvestres procuram se\nreorganizar e muitas vezes podem ser encontrados em zonas urbanas, aumentando os acidentes\npor animais peçonhentos. São condutas adequadas nos primeiros socorros em caso de acidente\nofídico, EXCETO:","options":{"A":"Manter o acidentado em repouso, evitando que ele corra ou que se locomova por seus próprios\nmeios.","B":"Aplicar álcool sobre o local da picada e cobrir com faixa sem compressão do local.","C":"Manter o membro picado mais elevado do que o restante do corpo.","D":"Levar o animal causador do acidente ao serviço de saúde, se for possível."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-253904","number":"253904","sourceNumber":"253904","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Salivação e sudorese intensa, bradicardia e miose caracterizam-se como sinais clínicos\nda intoxicação por:","options":{"A":"Organoclorados","B":"Mercúrio","C":"Solventes orgânicos","D":"Organofosforados"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-238644","number":"238644","sourceNumber":"238644","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação às intoxicações exógenas, assinale a alternativa incorreta.","options":{"A":"Bicarbonato de sódio via oral deve ser administrado após a ingestão de ácidos, a fim de\nneutralizar quimicamente estes agentes.","B":"N-acetilcisteína pode ser útil nas intoxicações por acetaminofeno.","C":"Não se deve induzir êmese após a ingestão de álcalis.","D":"Agitação, psicose e convulsões podem ser tratadas com benzodiazepínicos nas intoxicações por\nanfetaminas."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-254597","number":"254597","sourceNumber":"254597","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A respeito da intoxicação com ecstasy pode-se afirmar:","options":{"A":"É derivado da cocaína, mas mais purificado que o crack.","B":"Pode causar hipertermia, desidratação, hiponatremia, convulsões, crises hipertensivas, arritmias,\nalucinação.","C":"Sua excreção é 75% hepática, e tem início de ação após 60 minutos.","D":"Normalmente a osmolaridade urinaria está reduzida e a osmolalidade sérica está aumentada."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-254599","number":"254599","sourceNumber":"254599","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente foi picado por cascavel. Desta forma a melhor forma de prevenir a\ninsuficiência renal inclui:","options":{"A":"O acidente ofídico crotálico impõe risco de rabdomiólise com mioglobinúria. O tratamento inclui\nhidratação e uso de diuréticos osmóticos.","B":"Depleção de glutamato que pode ser revertido com administração de acetilcisteína.","C":"Vasoplegia, que causa hipotensão, maior responsável pela insuficiência renal no acidentes\ncrotálicos, deve ser tratada com noradrenalina.","D":"O veneno age com interrupção do funcionamentos dos receptores nos ductos coletores. Melhor\nmedicação é a furosemida."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-238662","number":"238662","sourceNumber":"238662","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Analise o quadro clínico a seguir. Um lactente de 2 anos de idade é levado ao\n\npronto-atendimento devido a choro inconsolável durante a madrugada enquanto dormia em colchão\nno chão, em um barracão, numa área de\nocupação. Ao exame, o paciente estava irritado, com\nmácula eritematosa em antebraço esquerdo, sudorese profusa, bradicárdico e com crepitações à\nausculta pulmonar bilateralmente. Diante desse quadro, é correto afirmar:","options":{"A":"O paciente pode ter sido picado por um escorpião amarelo, e o quadro é considerado grave,\nsendo necessária a infusão de soro específico.","B":"Trata-se de um quadro clínico sugestivo de erucismo por lagarta Lonomia sp, e o paciente\nnecessita receber antifibrinolítico.","C":"O pediatra deve pensar em picadura por Crotalus sp, realizar um torniquete no local da picada e\ntransferir o paciente para outro hospital.","D":"O quadro clínico é sugestivo de acidente com aranha armadeira, Phoneutria sp, e o paciente\ndeverá receber alta com analgésicos comuns."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-254603","number":"254603","sourceNumber":"254603","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Correlacione as colunas tendo em vista a intoxicação e o antídoto a ser utilizado:\n\nA-metemoglobinemia; B-benzodiazepínicos; C-opióide; D-monoxido de carbono; E-paracetamol;\n1-naloxona; 2-flumazenil; 3-azul de metileno;\n4-oxigênio; 5-acetilcisteína","options":{"A":"A1;B2;C3;D4:E5","B":"A3;B2;C1;D4;E5","C":"A5;B1;C2;D4;E3","D":"A3;B1;C2;D4;E5"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-239897","number":"239897","sourceNumber":"239897","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Os acidentes ofídicos representam sério problema de saúde pública nos países\ntropicais pela frequência com que ocorrem e pela\nmorbimortalidade que ocasionam. Existem no\nmundo aproximadamente 3000 espécies de serpentes, das quais de 10 a 14% são consideradas\npeçonhentas. Assinale a alternativa que contem uma característica de cobra peçonhenta:","options":{"A":"Cauda afinando lentamente.","B":"Presença da fosseta loreal.","C":"Cabeça arredondada.","D":"Pupilas arredondadas."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-203897","number":"203897","sourceNumber":"203897","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"M.S.D.A., 26 anos, sexo feminino, admitida na unidade de pronto atendimento com\nquadro de rebaixamento de nível de\nconsciência, associado a vômitos de repetição e salivação\nexcessiva. Familiares relataram que a paciente foi vista assintomática pela última vez cerca de 2\nhoras antes da admissão hospitalar. Paciente com história prévia de depressão, em\nacompanhamento irregular com psiquiatra e uso irregular do medicamento amitriptilina. Nas últimas\nsemanas, estava exteriorizando ?vontade de morrer?. Ao exame apresentava sudorese intensa,\nbroncorreia e fasciculações. PA = 100 x 50 mmHg; FC = 44 bpm (ECG mostrando bradicardia\nsinusal); FR = 30 irpm; satO? = 90% em ar ambiente, com esforço respiratório moderado; ECG = 7\n(Ao:1, Rv:2, Rm:4); e pupilas mióticas. Considerando o quadro clínico descrito, assinale a\nalternativa CORRETA:","options":{"A":"O quadro é compatível com uma síndrome anticolinérgica e provavelmente desencadeado por\nintoxicação por antidepressivo tricíclico (amitriptilina).","B":"A prioridade no tratamento da paciente é o manejo adequado de via aérea e prescrição de\nbicarbonato endovenoso.","C":"A prioridade no tratamento da paciente é o manejo adequado de via aérea e prescrição de\natropina endovenosa.","D":"Os efeitos desse tipo de intoxicação, que ocorre sobre os receptores nicotínicos, geralmente são\nsustentados por mais de 48 horas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-200518","number":"200518","sourceNumber":"200518","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O veneno de aranha que é proteolítico e hemolítico, podendo determinar quadros\ngraves de anemia, icterícia, hemólise, púrpura\ne insuficiência renal pertence ao gênero:","options":{"A":"Lycosa (aranha tarântula).","B":"Latrodectus (aranha negra).","C":"Loxosceles (aranha marrom).","D":"Phoneutria (aranha armadeira)."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-217198","number":"217198","sourceNumber":"217198","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre o controle de convulsões em pacientes intoxicados sintomáticos, assinale V\n(verdadeiro) e F (falso):\n\n( ) A administração de naloxone ev, é a primeira escolha.\n\n( ) A administração de propofol não é recomendada para lactentes e criança pré-escolares.\n( ) O midazolan está contraindicado em casos de\nestado epiléptico refratário.\n\n( ) Se houver suspeita de intoxicação alcoólica aguda em adolescentes, com comprometimento do\nnível de consciência, pode-se administrar tiamina e glicose a 50%.\n\nAssinale a afirmativa que contém a sequência CORRETA:","options":{"A":"V ? F ? V ? F.","B":"V ? F ? F ? V.","C":"F ? V ? F ? V.","D":"F ? V ? V ? F."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-181334","number":"181334","sourceNumber":"181334","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação à abordagem inicial e ao tratamento específico das intoxicações agudas,\nassinale a alternativa INCORRETA.","options":{"A":"Taquicardia, confusão mental, pupilas midriáticas e pele seca, quente e avermelhada são\ncaracterísticas típicas da síndrome colinérgica.","B":"Dor precordial, infarto do miocárdio, emergência hipertensiva, acidente vascular cerebral e\narritmias podem ocorrer nas intoxicações por cocaína e anfetaminas.","C":"Bradipneia, rebaixamento do nível de consciência e pupilas mióticas são sintomas de\nintoxicação por opioide.","D":"Ácido valproico, etanol, metformina e salicilatos podem causar intoxicação com acidose\nmetabólica grave e persistente."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-181344","number":"181344","sourceNumber":"181344","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O carvão ativado é contraindicado nas seguintes situações, EXCETO:","options":{"A":"Ingestão de substâncias corrosivas como ácidos ou bases.","B":"Ingestão de hidrocarbonetos.","C":"Substâncias que não são adsorvidas pelo carvão como álcool e ferro.","D":"Paciente intubado, em ventilação mecânica."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-179301","number":"179301","sourceNumber":"179301","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 23 anos, com relato de tentativa de auto-extermínio por ingestão de\nraticida. Ao exame ele apresenta taquicardia, dor abdominal, incontinência fecal e urinária,\nhipersalivação, aumento da secreção brônquica, dispneia, sudorese e miose. Diante do quadro\ndescrito, assinale a alternativa INCORRETA.","options":{"A":"Nas intoxicações por organofosforados e carbamatos, há despolarização sustentada do neurônio\npós-sináptico pelo aumento da acetilcolina em todo o organismo.","B":"Os carbamatos são encontrados em muitos inseticidas domésticos e causam inibição irreversível\nda acetilcolinesterase.","C":"A intoxicação por organofosforados pode ocorrer através da pele, assim como pela sua ingestão.","D":"A síndrome intermediária é caracterizada por paralisia de musculatura apendicular proximal,\nmúsculos flexores do pescoço, nervos cranianos e respiratórios."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-177990","number":"177990","sourceNumber":"177990","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre os acidentes crotálicos é correto afirmar, EXCETO:","options":{"A":"Em geral cursam com muita dor local.","B":"São pouco importantes, diferindo dos acidentes botrópico e laquético.","C":"Sintomas neurológicos como fácies miastênica, surgem nas primeiras horas após a picada.","D":"A principal complicação, em nosso meio, é a Insuficiência Renal Aguda (IRA)."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-181997","number":"181997","sourceNumber":"181997","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Considerando os casos de intoxicações exógenas, assinale a alternativa que apresenta\na associação INCORRETA entre causa e antídoto,\nnesta sequência:","options":{"A":"Metanol ? Fomepizole.","B":"Organofosforados ? Atropina.","C":"Cianeto ? Edetato Dicobáltico (EDTA dicobáltico).","D":"Benzoadiazepínicos ? Naloxona."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-179304","number":"179304","sourceNumber":"179304","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"As intoxicações agudas na infância, juntamente com outros acidentes, constituem uma\ndas principais causas de óbito em crianças e\nadolescentes. Em relação às intoxicações, assinale a\nalternativa INCORRETA.","options":{"A":"Há suspeita de intoxicação, quando o paciente apresenta quadro clínico que não se enquadra\nem\n\ndoenças conhecidas.","B":"Há suspeita de intoxicação em criança que estava bem e inicia subitamente com quadro grave,\npois\n\npode ter ingerido algum medicamento.","C":"Há suspeita de intoxicação em toda criança em coma sem causa aparente.","D":"Em criança com suspeita de intoxicação o tratamento deve ser agressivo mesmo em caso de\nprodutos pouco tóxicos."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-179269","number":"179269","sourceNumber":"179269","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Pré-escolar de quatro anos, gênero feminino, peso relatado 20kg, é levada ao\n\npronto-socorro com relato de há 30 minutos ter ingerido 15 comprimidos que estavam em cima da\nmesa. A mãe acredita serem comprimidos de sulfato ferroso que a avó estava em uso. A criança\napresentou um episódio de vômito após a ingestão. Encontra-se no momento chorosa e irritada,\nmas interage com o examinador. Considerando o quadro descrito, a conduta MAIS apropriada no\nmomento é a de:","options":{"A":"Lavagem gástrica com solução salina.","B":"Alcalinização gástrica com bicarbonato.","C":"Retirada endoscópica dos comprimidos.","D":"Administração de carvão ativado por enema."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-158237","number":"158237","sourceNumber":"158237","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança de 5 anos (20 kg) e um adulto de 45 anos (78 kg) foram picados na perna\npor uma cascavel, sendo o acidente ofídico\nclassificado como grave em ambos. A dose de soro\nantiofídico a ser administrada a cada um será:","options":{"A":"A mesma, baseada na gravidade do acidente.","B":"Diferente, baseada no peso de cada um.","C":"Diferente, a dose da criança será metade da dose do adulto.","D":"A mesma, baseada no sítio da picada, desde que o tempo decorrido para o atendimento seja\nigual."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-153134","number":"153134","sourceNumber":"153134","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem, 34 anos, dá entrada em pronto-socorro duas horas após a piacada por cobra\nnão identificada, com quadro de edema e dor\nintensa no local, dor abdominal em cólica, diarreia,\nnáuseas, vômitos e escurecimento da urina. PA = 80 x 54 mmHg e FC= 48 bpm. Exames\nlaboratoriais mostraram TC (tempo de coagulação) incoagulável. Este acidente ofífico é melhor\nclassificado como:","options":{"A":"Laquético.","B":"Botrópico.","C":"Crotálico.","D":"Elapídico.","E":"O quadro clínico não é compatível com acidente ofídico."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-163408","number":"163408","sourceNumber":"163408","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"T.P.B., 27 anos, sexo feminino, do lar, foi atendida no pronto-socorro após atentar\ncontra a própria vida ingerindo soda\ncáustica. Em relação a este caso, assinale a alternativa\nCORRETA:","options":{"A":"Em longo prazo, pode ocorrer degeneração maligna.","B":"As lesões gástricas geralmente afetam mais o fundo.","C":"Por ser álcali, deve ter produzido necrose de coagulação.","D":"Uma medida adequada seria provocar vômitos."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-158251","number":"158251","sourceNumber":"158251","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma pessoa é picada por uma serpente de grande porte do gênero elapídico, caso não\nseja tratada com soro anti-ofídico seu provável óbito dever-se-á a:","options":{"A":"Insuficiência respiratória;","B":"Sepse de foco cutâneo;","C":"Síndrome de compartimento de extremidades;","D":"Insuficiência renal."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-164000","number":"164000","sourceNumber":"164000","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual das seguintes alterações não seria encontrada na avaliação clínica e nos exames\ncomplementares de uma criança de 2 anos, vítima de um acidente escorpiônico clinicamente\ngrave?","options":{"A":"Aumento de CK e CK-MB.","B":"Bradicardia sinusal.","C":"Distúrbio de coagulação.","D":"Taquicardia sinusal."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-103063","number":"103063","sourceNumber":"103063","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 38 anos, jogadora profissional de vôlei, admitida no pronto-socorro, trazida\npelo SAMU com relato de intoxicação exógena mista há 5 horas por 20 ml de paracetamol (200\nmg/ml), 10 comprimidos de amitriptilina de 25 mg, 5 comprimidos de diazepam de 5 mg e 10\ncomprimidos de simeticona. Admitida sonolenta, porém orientada no tempo e no espaço,\nobedecendo a comandos verbais e estável hemodinamicamente. Sobre esse caso clínico, assinale\na alternativa CORRETA:","options":{"A":"Deve-se realizar apenas eletrocardiograma, exames laboratoriais e medidas de suporte à vida,\ninicialmente.","B":"Deve-se iniciar, imediatamente, N-acetilcisteína para prevenção de hepatite fulminante, devido à\nintoxicação por paracetamol.","C":"Deve-se realizar lavagem gástrica até o completo esvaziamento gástrico (saída apenas de soro)\ne depois administrar carvão ativado para\nreduzir a absorção dos medicamentos.","D":"Deve-se realizar hiper-hidratação e alcalinização urinária para aumentar a excreção da\namitriptilina."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-347427","number":"347427","sourceNumber":"347427","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um menino com 2 anos chega para atendimento no serviço de urgência com a mãe,\nque conta que ele ingeriu desinfetante há\nmenos de uma hora. Ao exame, a criança apresenta-se\nconsciente, irritada, chorosa, normotérmica, corada e hidratada, exalando um leve odor de\ndesinfetante pela boca. Suas conjuntivas estão claras, as pupilas, isocóricas e fotorreativas; o\nritmo\ncardíaco é regular em 2 tempos, sem sopros. Além disso, apresenta: perfusão periférica normal;\nfrequência cardíaca de 120 batimentos por minuto; pressão arterial de 80 x 50 mmHg; frequência\nrespiratória de 20 incursões por minuto, eupneica; murmúrio vesicular fisiológico sem ruídos\nadventícios. A conduta inicial no atendimento dessa criança é","options":{"A":"usar agentes neutralizantes ou substâncias diluentes, como leite e água.","B":"fazer lavagem gástrica e utilizar carvão ativado para adsorver a substância.","C":"induzir vômito para eliminar a maior quantidade possível da substância ingerida.","D":"examinar a mucosa oral e observar por 2 a 4 horas para verificar se permanece íntegra."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-318562","number":"318562","sourceNumber":"318562","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma comunidade ribeirinha vive próxima de uma barragem que está sendo construída\nem um rio. Uma das consequências ambientais\ndesse represamento das aguas é a redução do\nnível do rio, o que prolonga o período de aguas baixas (vazantes) na região. Em contrapartida à\nconstrução da barragem, a empreiteira e os entes públicos associados à sua implantação\npromoveram ações que eliminaram o desmatamento no entorno dessa comunidade, que é atendida\npor uma Equipe de Saúde da Família. O médico de Família e comunidade da equipe pretende\nrealizar uma ação educativa para alertar os moradores locais quanto aos impactos da mudança\nambiental na saúde. Nessa situação, que problema de saúde esse médico deverá abordar,\nconsiderando-se o provável aumento em sua frequência?","options":{"A":"Acidentes ofídicos.","B":"Acidentes com arraia.","C":"Acidentes escorpiônicos.","D":"Intoxicação por mercúrio."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-319976","number":"319976","sourceNumber":"319976","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Pré-escolar de três anos de idade, sexo masculino, previamente hígido, foi levado à\nemergência, apresentando agitação psicomotora, midríase, boca seca e rubor facial. A mãe dele\ninformou que tinha percebido os sintomas havia uma hora, ao chegar do trabalho. O menor fica em\ncasa com a irmã, de 10 anos, durante o período da tarde, até a mãe retornar do trabalho. Conforme\no quadro clínico apresentado, trata-se de intoxicação por","options":{"A":"dipirona.","B":"salbutamol.","C":"clorpromazina.","D":"dexclorfeniramina."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-319981","number":"319981","sourceNumber":"319981","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Pré-escolar de 3 anos e 4 meses de idade deu entrada no pronto-socorro apresentando\nrigidez e espasmos musculares e hipertermia.\nNão apresentava dificuldade respiratória. Ausculta\ncardíaca sem anormalidades. Sem história prévia de doença cardíaca. O paciente estava\nrecebendo oxigenoterapia quando um primo dele, de quatro anos, deu entrada no mesmo hospital,\ncom quadro semelhante. Ambos haviam passado as últimas 12 horas na casa da avó materna, que\nhá anos faz tratamento de esquizofrenia e hipertensão arterial. As evidências clínicas dessa\nhistória\ninduzem a necessidade de o médico investigar","options":{"A":"cardiopatia congênita cianótica.","B":"intoxicação exógena por captopril.","C":"intoxicação exógena de haloperidol.","D":"ingestão exógena por benzodiazepínico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-311414","number":"311414","sourceNumber":"311414","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"No atendimento a pacientes vítimas de acidente botrópico (jararaca), é correto afirmar\nque:","options":{"A":"abscesso não é uma complicação neste tipo de acidente, estando mais associado ao acidente\ncrotálico.","B":"é indicado solicitar o tempo de coagulação na admissão e após 24h de observação do doente.\n\nSe o Tempo de Coagulação permanecer alterado, está indicada dose adicional de soro\nantibotrópico.","C":"devido à ação proteolítica do veneno botrópico, está indicado o uso de torniquetes, a fim de\nevitar a necrose tecidual.","D":"o tratamento consiste na administração de soro antibotrópico (SAB) endovenoso em 8 - 10\nampolas para quadros leves, e 10 -12 ampolas para quadros graves.","E":"se estabelecido o diagnóstico de síndrome compartimental, a fasciotomia deve ser evitada para\nnão disseminar o veneno botrópico, mesmo que as\ncondições de hemostasia do paciente permitam."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-297554","number":"297554","sourceNumber":"297554","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Pacientes vítimas de intoxicações exógenas são comuns nos prontos-atendimentos,\nportanto o conhecimento da droga causadora de\nintoxicação bem como o seu tratamento imediato\ncom seu antídoto quando possível e fundamental a todo medico que atua na emergência. Marque a\nalternativa que contém a correlação entre o agente tóxico e o antídoto correto:\n\n1-benzodiazepínicos; 2-Acetominofem; 3-Carbamatos; 4- Opiodes; ( ) n-Acetilcisteína; ( ) Atropina;\n(\n\n) Naloxana; ( ) Flumazenil","options":{"A":"2-3-1-4.","B":"2-3-4-1.","C":"3-2-1-4.","D":"3-2-4-1."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-277738","number":"277738","sourceNumber":"277738","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem, 60 anos, internado devido a câncer de estômago metastático. Durante\navaliação médica, observou-se que o paciente se\nencontrava sonolento, com pupilas mióticas e\nfrequência respiratória de 6 irpm. A medicação mais provavelmente implicada na intoxicação e o\nantídoto são, respectivamente:","options":{"A":"Benzodiazepínico e flumazenil.","B":"Metanol e fomepizol.","C":"Tricíclico e bicarbonato de sódio.","D":"Paracetamol e acetilcisteína.","E":"Opioide e naloxona."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-215698","number":"215698","sourceNumber":"215698","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"No Brasil são notificados a cada ano cerca de 25.000 casos de acidentes ofídicos com\numa taxa de morte de cerca de 0.5%. No\natendimento ao paciente vítima de acidentes ofídicos, a\nidentificação da serpente pode ser feita por alguma pessoa com conhecimento básico desses\nanimais. Sobre esses acidentes no Brasil, é CORRETO afirmar que:","options":{"A":"No Brasil, os principais gêneros de interesse médico são representados por Bothrops, Crotalus e\nLachesis.","B":"Cerca de 80% dos acidentes ocorre em membros superiores, em mãos de trabalhadores rurais.","C":"Entre as ações biológicas dos venenos das serpentes, a mistura de diversas proteínas induz\nações com efeitos proteolítico, coagulante, hemorrágico, neurotóxico e miotóxico.","D":"Dentre os acidentes ofídicos, os mais frequentes são aqueles causados por serpentes do gênero\nLachesis, cuja principal representante é a cascavel.","E":"Em acidentes provocados pelo gênero Bothrops, sinais e sintomas locais são exuberantes, e\nmanifestações sistêmicas como mal-estar, prostração, sudorese, náuseas, vômitos, sonolência,\nsecura na boca e insuficiência respiratória podem ser descritas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-215901","number":"215901","sourceNumber":"215901","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Pré-escolar, 4 anos de idade, encontrado desacordado ao lado de cartela de verapamil\nda avó, que estava vazia. Nos casos de\nintoxicação exógena por bloqueador de canal de cálcio em\npediatria, quanto a sua condução, deve-se: I. Realizar a remoção de agente toxicológico, reduzindo\nassim, a diminuição da exposição do organismo, reduzindo o tempo e/ou superfície de exposição.\n\nII. A lavagem gástrica e o uso do carvão ativado pode ser uma alternativa no caso acima, por se\ntratar de intoxicação por verapamil em criança. III. Realizar medidas que promovam a excreção\nrápida do agente toxicológico absorvido pelo organismo, como diurese forçada pelo uso de\ndiuréticos. IV. Gluconato de cálcio pode fazer parte do arsenal terapêutico no caso em questão. A\nalternativa que contém todas as afirmativas CORRETAS é:","options":{"A":"I e III.","B":"II e IV.","C":"I, II, III e IV.","D":"I e IV.","E":"II, III e IV."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-181847","number":"181847","sourceNumber":"181847","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Nos casos de intoxicação exógena em pediatria, quanto a sua condução, deve-se: I.\nRealizar screening toxicológico: aspirado de conteúdo gástrico ate 4 horas após a ingestão, coleta\nde sangue e urina entre 4 e 24 horas apos ingestão. II. Deve-se realizar a remoção do agente\ntoxicológico, reduzindo assim, a diminuição da exposição do organismo, reduzindo o tempo e/ou\nsuperfície de exposição. III. A lavagem gástrica não é mais indicada como rotina. IV. Deve-se\nrealizar medidas que promovam a excreção rápida do agente toxicológico absorvido pelo\norganismo, como diurese forçada pelo uso de diuréticos. V. O uso de antídotos, quando indicados,\ndevem sempre ser realizados. A alternativa que contém todas as afirmativas corretas é:","options":{"A":"I e III","B":"II e IV","C":"I e IV","D":"II, III e IV","E":"I, II, III, IV e V"},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-104703","number":"104703","sourceNumber":"104703","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 26 anos deu entrada numa emergência cerca de 1 hora após ingerir\nchocolate de origem suspeita com os seguintes sinais: rebaixamento do nível de consciência,\ntaquipneica com muita secreção em vias aéreas superiores, hipersalivação, sudorese, diarreia\nprofusa e pupilas mióticas. Trata-se de uma provável:","options":{"A":"intoxicação por etanol.","B":"quadro de diarreia aguda osmótica.","C":"Intoxicação por ?chumbinho?, produto a base de organofosforados.","D":"intoxicação por salicilato.","E":"acidente vascular isquêmico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-104705","number":"104705","sourceNumber":"104705","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Criança com 2 anos é trazida ao pronto-socorro pela mãe em estado torporoso,\nsudoreico e com salivação intensa. Mãe informa\nque o início dos sintomas foi agudo e observou\nquando retornou do banho já que a criança brincava na cozinha. Ao exame observa-se miose e\nbradicardia. A conduta mais adequada e provável diagnostico são:","options":{"A":"decúbito elevado, oxigenioterapia e lavagem gástrica. intoxicação por cianeto.","B":"lavagem gástrica imediata, estimular vômito, uso de antídoto específico. Intoxicação por\nOrganofosforado.","C":"estabilização (ABC), hidratação venosa, oxigenioterapia e uso de antídoto. Intoxicação\nmedicamentosa.","D":"anaminese rápida, avaliação clínica rápida e objetiva, suporte vital (ABC) e monitorização,\nidentificação do agente causal, lavagem gástrica\ncom carvão ativado, atropina. Intoxicação por\nOrganofosforado.","E":"anamenese detalhada. Avaliação clinica.\n\nmonitorização. Lavagem gástrica com carvão ativado. Intoxicação por barbitúricos."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-345546","number":"345546","sourceNumber":"345546","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Relacione os agentes tóxicos com os respectivos antídotos/antagonistas: 1.\nOrganofosforados. 2. Indutores de metemoglobinemia. 3. Metanol. 4. Benzodiazepínicos. 5.\nopiáceos. 6. Paracetamol. 7. Paraquat. ( ) flumazenil; ( ) n-acetilcisteína; ( ) terra de Fuller; (\n)\nnaloxone; ( ) azul de metileno; ( ) etanol; ( ) atropina + pralidoxima","options":{"A":"4, 6, 7, 5, 2, 3, 1","B":"4, 2, 7, 5, 6, 3, 1","C":"4, 6, 1, 5, 2, 3, 7","D":"4, 6, 7, 2, 5, 3, 1","E":"4, 2, 7, 6, 5, 3, 1"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-313510","number":"313510","sourceNumber":"313510","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem de 45 anos de idade, agricultor, sem comorbidades, deu entrada no\npronto-socorro com quadro que se iniciou há 3 horas de náuseas, vômitos, diarreia, agitação\n\npsicomotora, broncorreia, bradicardia (42 batimentos por minuto), taquidispneia, saturando 90% em\nar ambiente. Durante a avaliação neurológica, nota-se que as pupilas estavam isocóricas e\nmióticas. Antes de extrair dados da história clínica com a esposa do paciente, ele evolui com crise\nconvulsiva, necessitando de intubação orotraqueal após controle medicamentoso da\ndescompensação neurológica. Além das medidas de suporte hemodinâmico iniciais, seria\nrecomendado inicialmente:","options":{"A":"Naloxone intravenoso.","B":"Flumazenil intravenoso.","C":"Lavagem gástrica e carvão ativado.","D":"Bicarbonato de sódio a 8,4% intravenoso.","E":"Atropina 5 mg intravenoso."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-257204","number":"257204","sourceNumber":"257204","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente, 45 anos, chega ao setor de emergência do pronto socorro com quadro de\nsialorreia, sudorese intensa, dispneia importante e cólicas abdominais. O exame físico revelava\nmiose, bradicardia e ausculta pulmonar com roncos difusos e intensos. Sem outras anormalidades\nimportantes. O mesmo é agricultor. Baseado no caso clínico, o médico que fez o atendimento\nindicou o uso da seguinte droga:","options":{"A":"Fomepizole.","B":"Pralidoxima.","C":"Flumazenil.","D":"N-acetilcisteína.","E":"Naloxone."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-284547","number":"284547","sourceNumber":"284547","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em caso de acidente ofídico, o tempo até o início dos sintomas e para a apresentação\nclínica é muito variável, dependendo da\nespécie envolvida, da localização da picada e da\nquantidade de veneno inoculada na vítima. Uma das complicações potenciais locais é a necrose\ndos tecidos, sobretudo agravada pelo garrote. Este tipo de complicação está relacionado sobretudo\ncom o veneno de ação:","options":{"A":"Proteolítico","B":"Neurotóxico","C":"Hemorrágico","D":"Quelante","E":"Coagulante"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-212539","number":"212539","sourceNumber":"212539","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente trazido por familiares após tentativa de suicídio por uso de um determinado\nraticida. No rótulo do produto havia a\ninformação de que a substância se tratava de um carbamato.\nAssinale a alternativa que corresponde às prováveis alterações presentes no exame físico ou\nquadro laboratorial do paciente:","options":{"A":"Hipersalivação, hipersecreção brônquica e fasciculações musculares.","B":"Pupilas puntiformes não fotorreagentes, com ventilação superficial e irregular.","C":"Acidose metabólica grave com anion gap elevado, com insuficiência renal aguda.","D":"Prolongamento do intervalo QT, com predisposição a taquiarritmia ventricular polimórfica\nsustentada.","E":"Sangramentos espontâneos de pele, mucosas e cavidades."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-85851","number":"85851","sourceNumber":"85851","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem, 44 anos, agricultor, dá entrada no pronto-socorro após tentativa de suicídio por\ningestão de substância não identificada. Estava agitado, confuso e havia apresentado um episódio\nconvulsivo durante o transporte para o hospital, com duração de dois minutos. Referia dor\nabdominal intensa, com náuseas, vômitos e um episódio diarreico. Respirava com dificuldade, com\nausculta evidenciando crépitos grossos difusos. Observou-se também tremores grosseiros e\nmiofasciculações em tronco e membros superiores. PA = 148/90 mmHg; FC = 110 bpm; FR = 28\nirpm; T = 37,2°C; SatPO2 em ar ambiente = 88%. Levando-se em consideração o quadro do\npaciente, a droga que deverá ser administrada no manejo é:","options":{"A":"Bicarbonato de sódio.","B":"Atropina.","C":"Adrenalina.","D":"Flumazenil.","E":"N-Acetilcisteína."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-85859","number":"85859","sourceNumber":"85859","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem, 34 anos, dá entrada em Pronto-Socorro duas horas após ser picada por cobra\nnão identificada, com quadro de edema e dor\nintensa no local, dor abdominal em cólica, diarreia,\nnáuseas, vômitos e escurecimento da urina. PA = 80/54 mmHg e FC = 48 bpm. Exames\nlaboratoriais mostraram TC (Tempo de Coagulação) incoagulável. Este acidente ofídico é melhor\nclassificado como:","options":{"A":"Laquético.","B":"Botrópico.","C":"Crotálico.","D":"Elapídico.","E":"O quadro clínico não é compatível com acidente ofídico."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-351050","number":"351050","sourceNumber":"351050","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Lactente de 2 anos foi trazido à emergência após ter ingerido um produto de limpeza\nque os cuidadores não souberam informar. O\nacidente ocorreu há menos de uma hora e a criança\napresenta-se com salivação, estridor, vômitos, muito irritada por dor na boca e abdominal, recusa\npara engolir. No manejo deste paciente analise as assertivas abaixo e a relação proposta entre\nelas. I ? Após o cuidado de suporte está indicado o uso de carvão ativado 1g/kg. PORQUE II ? O\ncarvão vegetal tem maior probabilidade de ser eficaz quando administrado dentro de uma hora\napós a ingestão. A respeito destas asserções, assinale a opção correta.","options":{"A":"As asserções I e II são proposições verdadeiras, e a II é uma justificativa da I.","B":"As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa da I.","C":"A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.","D":"A asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","E":"As asserções I e II são proposições falsas."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-148948","number":"148948","sourceNumber":"148948","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"No atendimento de um setor de emergência costumam chegar pacientes pediátricos\ncom intoxicações exógenas, principalmente por\ningestão. Nestes casos, podemos afirmar que a\nlavagem gástrica:","options":{"A":"Tem indicação ideal na ingestão de querosene.","B":"Pode ser utilizada em até 6 horas do ocorrido, em casos especiais.","C":"Está indicada em todas as intoxicações nas primeiras duas horas do ocorrido.","D":"Pode ser indicada em intoxicações potencialmente fatais, na primeira hora do ocorrido.","E":"Os estudos mostram alta efetividade e deve ser tentada sempre que os agentes ingeridos forem\nmedicamentos."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-78486","number":"78486","sourceNumber":"78486","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"As intoxicações são uma entidade frequente em pronto atendimento pediátrico. Com\nrelação às produzidas por cáusticos de base forte:","options":{"A":"Produzem necrose de coagulação.","B":"Produzem necrose de liquefação.","C":"No tratamento os vômitos devem ser estimulados.","D":"A neutralização por ácidos é útil.","E":"Antibióticos profiláticos devem ser instituídos."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-70847","number":"70847","sourceNumber":"70847","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale a alternativa correta sobre a lavagem gástrica na criança com intoxicação\nexógena.","options":{"A":"Está indicada em todas as intoxicações nas primeiras duas horas do ocorrido.","B":"Pode ser utilizada até 6 horas do ocorrido, em casos especiais.","C":"Pode ser indicada em intoxicações potencialmente fatais, na primeira hora do ocorrido.","D":"Tem indicação ideal na ingestão de querosene.","E":"Os estudos mostram alta efetividade e deve ser tentada sempre que os agentes ingeridos forem\nmedicamentos."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-44591","number":"44591","sourceNumber":"44591","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 42 anos, relata 24 horas de evolução de lesão eritematosa, dolorosa em\nregião interna de membro inferior direito. Ao exame: observa-se uma placa eritematosa, com área\nnecrótica central. As alternativas seguintes fazem parte do diagnóstico diferencial da lesão,\nexceto:","options":{"A":"Acidente por Loxosceles.","B":"Vasculite.","C":"Acidente por Latodrectus.","D":"Síndrome de sweet.","E":"Pioderma gangrenoso."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-35051","number":"35051","sourceNumber":"35051","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale a alternativa CORRETA sobre a ingestão de substâncias cáusticas:","options":{"A":"A ingestão de produtos ácidos geralmente tem pior prognóstico que a ingestão de produtos\nálcalis.","B":"Uma endoscopia deve ser realizada em todos os pacientes sintomáticos.","C":"Deve-se tentar imediatamente após a ingestão, a tentativa de neutralização do produto ingerido,\nquando este for conhecido.","D":"Uma parcela significante destes pacientes apresentará, no futuro, carcinoma esofágico.","E":"Deve-se estimular o vômito em casa antes de procurar o atendimento médico."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-354939","number":"354939","sourceNumber":"354939","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre o tema acidentes com animais peçonhentos, analise as afirmativas a seguir e\nassinale a alternativa CORRETA:","options":{"A":"O acidente elapídico é o único dentre os acidentes ofídicos que não causa sintomas\nneurológicos","B":"O acidente ofídico é o acidente com animais peçonhentos mais comum no Brasil","C":"O acidente botrópico pode levar a fácies miastênica e mialgia generalizada","D":"O acidente crotálico é o único dentre os acidentes ofídicos que pode provocar rabdomiólise"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-360915","number":"360915","sourceNumber":"360915","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Criança de 6 anos, morador da zona rural, é trazido à emergência com dificuldade para\nrespirar, deambular, mantém queda palpebral bilateral (olhar miastenico). O pai refere que 12 horas\nantes o filho sentiu uma picada no tornozelo, mas não encontrou nenhum animal próximo ou sinal\nde lesão. Durante o exame físico não é notado sinal de picada no membro referido, durante a\ncoleta de exames verifica-se urina escurecida, cor avermelhado-amarronzada, e o tempo de\ncoagulação estava aumentado. Sua suspeita diagnóstica é:","options":{"A":"Acidente com escorpião amarelo.","B":"Acidente com Loxosceles.","C":"Acidente crotálico.","D":"Acidente com Celenterados.","E":"Acidente botrópico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-366044","number":"366044","sourceNumber":"366044","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente masculino, 35 anos, lavrador, morador da zona rural de Campina Grande do\nSul-PR. Trazido ao pronto-socorro do Hospital Angelina Caron relatando ter sentido picada de\ncobra no tornozelo há aproximadamente 2 horas, enquanto trabalhava na lavoura. Queixa de dor\nintensa no local da mordida, edema crescente, equimose e sangramento local. O exame físico\nrevela dois pontos de picada no tornozelo direito, com edema desde o terço médio da perna até o\nretropé, além de equimose local. PA 85/50 mmHg, FC 112, sudorese profusa. O paciente não\nidentificou a cobra mas, considerando o quadro clínico apresentado e a epidemiologia de acidentes\nofídicos no estado do Paraná, qual agente causador mais provável e qual a classificação de\ngravidade deste acidente?","options":{"A":"Jararaca / acidente moderado","B":"Cascavel / acidente grave","C":"Surucucu / acidente grave","D":"Cascavel / acidente moderado","E":"Jararaca / acidente grave"},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-366043","number":"366043","sourceNumber":"366043","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Ainda sobre os acidentes ofídicos, assinale a alternativa correta:\n\"https://www.saude.pr.gov.br/Pagina/Acidentes-por-Serpentes Nota Técnica N° 14/2021 -\nCIATOX-PR/DVZZI/CVIA/DAV/SESA: Acidentes ofídicos de interesse no Paraná - Vigilância e\nAssistência em Saúde.\"","options":{"A":"Acidentes crotálicos são mais comuns em áreas litorâneas e podem cursar com manifestações\nneurológicas, sendo a paralisia flácida uma das mais frequentes.","B":"Cobras corais verdadeiras são extremamente agressivas e a dose do soro antielapídico varia de\nacordo com a classificação de gravidade do acidente, que pode ser leve, moderado ou grave","C":"Nos casos de acidente botrópico, deve-se atentar para complicações tais como síndrome\ncompartimental, abscessos, necrose e lesão renal aguda.","D":"Considerando a abundante flora bacteriana presente na saliva das cobras, antibioticoterapia\nprecoce está indicada em todos os acidentes\nofídicos.","E":"Não há necessidade de profilaxia para tétano nos casos de acidente ofídico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-337896","number":"337896","sourceNumber":"337896","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Segundo o Ministério da Saúde (MS), a doença causada pelo vírus Monkeypox virus é\ntransmitida por animais (zoonose) e sua transmissão para humanos pode ocorrer através do\ncontato com um animal ou pessoa infectada, ou ainda com material corporal humano contendo o\nvírus. Assinale a alternativa correta em relação às seguintes situações: (NOTA TÉCNICA N°\n002/2022 SESA/SSVS/GEVS ? Monkeypox.)","options":{"A":"Caso confirmado: Paciente com histórico de viagem para país endêmico ou com casos\nconfirmados de Monkeypox nos 21 dias anteriores ao início dos sintomas e em confirmação\nlaboratorial.","B":"Caso provável: Indivíduo que atende à definição de caso provável que é confirmado\nlaboratorialmente para o vírus da Monkeypox por\nteste molecular (qPCR e/ou sequenciamento).","C":"Caso descartado: Paciente suspeito, mas com resultado de teste molecular (qPCR e/ou\nsequenciamento) positivo para o Smallpox.","D":"Quando o paciente é encaminhado para coleta em fase mais tardia na qual as lesões já estão\nsecas, o material a ser encaminhado são\ncrostas das lesões, preferencialmente optar pelas crostas\nmenos secas, ou seja, coletar aquelas em fase mais inicial de cicatrização.","E":"Sangue é o melhor material biológico para detecção de Poxvirus, pois o período de alta viremia é\nsimultâneo ao aparecimento das pústulas."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-326811","number":"326811","sourceNumber":"326811","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"?O Ministério da Saúde por meio da Sala de Situação, instalada em 23 de maio,\nmonitora as notificações de casos de\nMonkeypox no mundo e, no Brasil, além do monitoramento\ntambém é realizada a investigação dos casos, assim como a elaboração de documentos técnicos\npara fomentar ações públicas?. www.gov.br/saude. Segundo a nota técnica elaborada pelo\nMinistério da Saúde para orientação das equipes da Atenção Primária à Saúde (APS), é CORRETO\nafirmar:","options":{"A":"Idosos com comorbidades como hipertensão arterial sistêmica e diabetes tipo 2 são\nconsiderados grupo de risco.","B":"O monitoramento dos casos suspeitos deve ser realizado em domicílio e presencialmente pela\nequipe da APS.","C":"Os contatos assintomáticos de pacientes suspeitos ou confirmados tem necessidade de\nisolamento.","D":"O swab do material vesicular dos casos suspeitos deve ser coletado em duas ou mais amostras\nde locais distintos.","E":"Para definição de caso suspeito, é necessário ter vínculo epidemiológico com casos suspeitos,\nprováveis ou confirmados de Monkeypox."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-326817","number":"326817","sourceNumber":"326817","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Durante o ano de 2022, tivemos uma nova pandemia, agora de Varíola do Macaco\n(Monkeypox), sobre essa condição, assinale a alternativa CORRETA.","options":{"A":"A doença é uma zoonose, sendo transmitida principalmente de primatas para o ser humano.","B":"Essa doença era considerada erradicada no mundo há vários anos, porém devido à baixa\ncobertura vacinal, casos novos passaram a ser detectados nesse ano.","C":"A principal via de transmissão é a sexual, sendo que o maior grupo de risco, no momento, é o de\nhomens que fazem sexo com outros homens.","D":"Apesar de ser uma variante da varíola humana clássica, a vacina existente não produz\nimunidade.","E":"Apesar de ser considerada uma pandemia, a doença ainda está localizada ao continente\nafricano e asiático, com raros casos na Europa\ne nas Américas."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-342785","number":"342785","sourceNumber":"342785","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Na intoxicação aguda por carbamatos:","options":{"A":"Haverá inibição da colinesterase, resultando em síndrome colinérgica. O manejo inclui a\nadministração de atropina.","B":"Haverá inibição da colinesterase, resultando em síndrome colinérgica. O manejo inclui a\nadministração de naloxone.","C":"Haverá ativação de receptores GABA, resultando alteração do nível de consciência. O manejo\ninclui a administração de atropina.","D":"Haverá ativação de receptores GABA, resultando alteração do nível de consciência. O manejo\ninclui a administração de flumazenil.","E":"Haverá inibição da colinesterase, resultando em síndrome colinérgica. O manejo inclui a\nadministração de flumazenil."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-337929","number":"337929","sourceNumber":"337929","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A insuficiência renal aguda pode ser secundária a acidentes por animais peçonhentos,\npodemos afirmar que acidentes com serpentes de\nmaior incidência são: (Nefrologia\n\nPediatrica-Toporovski-Mello-Martini Filho-Benini-Andrade,2a edição-Cap.24, Pag.504.)","options":{"A":"Acidente Botrópico","B":"Acidente Crotálico","C":"Acidente Laquético","D":"Acidente por Loxcosceles","E":"Acidente por Lonomia"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-320950","number":"320950","sourceNumber":"320950","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"No mês de julho de 2022, a Organização Mundial da Saúde declarou a Monkeypox\ncomo Emergência de Saúde Pública de Importância\nInternacional, indicando a necessidade de\nmedidas para evitar a sua disseminação nos países. A respeito dessa infecção em crianças,\nassinale a alternativa correta.","options":{"A":"A antibioticoterapia está formalmente indicada a fim de evitar infecções bacterianas\nsecundárias.","B":"A principal forma de transmissão é por meio da aspiração de gotículas eliminadas pelos\npacientes infectados.","C":"As lesões de pele evoluem em estágios na sequência crostas, pústulas, vesículas, pápulas e\nmáculas.","D":"Junto com as gestantes e os imunodeprimidos, as crianças fazem parte dos grupos mais\nvulneráveis.","E":"O exame mais indicado para a confirmação dos casos é a cultura do Monkeypox vírus das\nlesões de pele ou mucosas."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-326857","number":"326857","sourceNumber":"326857","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Você está de plantão quando admite um paciente de 54 anos por tentativa de suicídio.\nEle fez uso de doses elevadas de veneno para\nratos, o aldicarb, popularmente conhecido como\n\n?chumbinho?. Na admissão encontra-se com hipersecreção pulmonar, salivação excessiva,\nbradicardia e com pupilas mióticas. Qual seria o medicamento mais adequado para o seu\ntratamento?","options":{"A":"Atropina.","B":"Bicarbonato de Sódio.","C":"Flumazenil.","D":"Naloxona.","E":"Vitamina K."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-304657","number":"304657","sourceNumber":"304657","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale a alternativa correta em relação à acidentes ofídicos:","options":{"A":"Para o tratamento de picada da cobra surucucu-bico-de-jaca é utilizado o soro anti-laquético","B":"Para o tratamento de picada da cobra cascavel é aplicado o soro anti-botrópico.","C":"Para o tratamento de picada da cobra jararaca é aplicado o soro anti-micrúrico","D":"Para o tratamento de picada da cobra coral é utilizado o soro anti-corálico.","E":"Para o tratamento de picada de cobra d?água é utilizado o soro antiofídico."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-314877","number":"314877","sourceNumber":"314877","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 83 anos, com história de insuficiência cardíaca e em uso de carvedilol 3,125mg\nde 12/12h, enalapril 5mg de 12/12h,\nfurosemida 40mg e digoxina 0,250mg 1x/dia, procurou\natendimento por quadro de dor abdominal, diarreia, oligúria e confusão mental. Refere início do\nquadro há cerca de 4 dias e que há um dia vem apresentando uma visão pouco amarelada. Ao\nexame, apresentava-se com pressão arterial de 90x60mmHg, frequência cardíaca de 38bpm,\nmucosas secas e dor abdominal difusa a palpação. Demais exames físicos sem alterações dignas\nde nota. Exames laboratoriais iniciais mostravam uma disfunção renal com creatinina de 2,8mg/dL,\nureia de 160mg/dL, potássio de 5,8mg/dL, nível de digoxina de 2,5ng/dL. Sobre o caso, marque a\nalternativa INCORRETA:","options":{"A":"Idade avançada, insuficiência renal e descompensação das doenças de base são fatores de\nrisco para o quadro acima.","B":"O eletrocardiograma associado a essa condição pode apresentar infradesnivelamento do\nsegmento ST, onda T plana ou negativa (conhecido com ?pá de pedreiro?) e intervalo QT curto.","C":"O tratamento dessa condição baseia-se em suspensão do medicamento culpado, hidratação e,\nem alguns casos, é necessário o implante de marca-passo até a compensação clínica.","D":"Com o aumento da incidência e prevalência da insuficiência cardíaca, cada vez mais é possível\nencontrar casos como esse, uma vez que o uso da medicação envolvida no quadro é essencial no\ntratamento dessa doença."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-297182","number":"297182","sourceNumber":"297182","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Nas intoxicações exógenas está indicado a realização de lavagem gástrica e carvão\nativado nas primeiras horas. No entanto, existem algumas substâncias que contra indicam esse\nprocedimento. Assinale a alternativa que possui uma substância em que NÃO é indicado esse\nprocedimento.","options":{"A":"Álcalis fortes (Substâncias causticas)","B":"Carbamazepina","C":"Fenitoina","D":"Digoxina"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-299267","number":"299267","sourceNumber":"299267","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 54 anos, portador de neoplasia de próstata com metástase óssea, porém\nindependentemente para as suas atividades básicas diárias, realizando tratamento com\nhormonioterapia, está em uso de Paracetamol 500mg associado a 30mg de codeína a cada 6 horas\npara dor, porém hoje tomou 2 comprimidos de Morfina 10mg devido à piora da dor. Nesse cenário é\nadmitido em serviço de emergência com quadro de rebaixamento do nível de consciência, com\npupilas mióticas puntiformes, pressão arterial de 80x40 mmHg, frequência cardíaca de 54bpm e\nfrequência respiratória de 6ipm. Qual é o manejo mais adequado para esse paciente?","options":{"A":"Infusão de Flumazenil por via intravenosa imediatamente.","B":"Infusão de Naloxona por via intravenosa imediatamente.","C":"Infusão de solução de bicarbonato de sódio a 8,4% com dose de 1 mEq/kg.","D":"Infusão de atropina na dose de 1 mg por via intravenosa.","E":"Como o paciente encontra-se em estado de terminalidade, oferecer apenas medidas de\nconforto, incluindo sedação e analgesia."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-303102","number":"303102","sourceNumber":"303102","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Adolescente de 13 anos, morador da zona rural, é trazido à emergência com dificuldade\npara respirar, deambular, mantém queda palpebral\nbilateral (olhar miastenico). O pai refere que 12\nhoras antes o filho sentiu uma picada no tornozelo, mas, não encontrou nenhum animal próximo ou\nsinal de lesão. Durante o exame físico não é notado sinal de picada no membro referido, durante a\ncoleta de exames verifica-se urina escurecida, cor avermelhado-amarronzada, e o tempo de\ncoagulação estava aumentado. Sua suspeita diagnóstica é:","options":{"A":"Acidente com escorpião amarelo.","B":"Acidente com Loxosceles.","C":"Acidente botrópico.","D":"Acidente crotálico.","E":"Acidente com Celenterados."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-304734","number":"304734","sourceNumber":"304734","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"J.F., 12 anos, é atendido no pronto-socorro pediátrico por sonolência e dificuldade de\ndeambulação. Há 3 dias, sempre no mesmo horário, por volta do meio dia, a menina apresenta\nsonolência, fala sem nexo, movimentos irregulares e dificuldade de marcha que melhoram com o\npassar do dia. Nega febre, vômitos e outros sintomas. Antecedente pessoais nada digno denota.\nAntecedentes familiares: irmão com diagnóstico de epilepsia. Ao exame físico: bom estado geral,\nacianótica, anictérica, afebril, FC= 100 bpm, FR= 24 ipm, PA= 110x70 mmHg. O exame neurológico\nrevela paciente sonolenta, desorientada, com nistagmo bilateral, força muscular de difícil\navaliação,\nreflexos presentes, marcha de base alargada. Qual a principal suspeita diagnóstica?","options":{"A":"Epilepsia","B":"Intoxicação exógena","C":"Tumor de cerebelo","D":"Malformação arteriovenosa","E":"Encefalite"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-304739","number":"304739","sourceNumber":"304739","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 12a, refere ter sido picado na perna direita por animal há 2 horas quando\nestava em mata, com dor no local desde então.\nExame físico: FC = 124 bpm, FR = 20 irpm, PA=\n100x60 mmHg; membro inferior direito: edema até fossa poplítea e equimose em tornozelo. O\nDIAGNÓSTICO É:","options":{"A":"Acidente elapídico.","B":"Acidente por Loxosceles.","C":"Acidente crotálico.","D":"Acidente botrópico.","E":"Acidente laquético."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-261944","number":"261944","sourceNumber":"261944","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente de 28 anos é admitido no pronto atendimento do Hospital Universitário\nCajuru trazido por familiares após ter\ningerido grande quantidade de medicamentos, em torno de 20\ncomprimidos de amitriptilina. A ingestão ocorreu há 3 horas. No momento, o paciente apresenta-se\nconfuso, escala de coma de Glasgow de 7, com sinais de desidratação. A sua temperatura é de\n38ºC, frequência respiratória de 22 ipm, frequência cardíaca de 110 bpm e pressão arterial de\n110x60 mmHg. No exame físico, percebemos pupilas midriáticas. Seu eletrocardiograma\ndemonstra um alargamento do QRS e do intervalo QT. Qual seria a sua conduta?","options":{"A":"A infusão de bicarbonato de sódio na dose de 1 meq/kg pode ser útil para esse paciente,\nvisando a prevenção de arritmias mais graves.","B":"A lavagem gástrica e infusão de carvão ativado devem ser a primeira conduta a ser realizada\npara esse paciente.","C":"Em caso de crise convulsiva, deve-se evitar o uso de benzodiazepínicos.","D":"A terapia mais eficaz para os casos graves é a retirada da droga de circulação por meio de\nhemodiálise.","E":"Uma terapia eficaz para o manejo do rebaixamento do nível de consciência do paciente seria o\nuso de flumazenil."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-261138","number":"261138","sourceNumber":"261138","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 6 anos, é trazido ao serviço de emergência com cefaléia intensa, náusea,\nvômitos, cólicas abdominais, tontura, fraqueza\ngeneralizada, dispnéia, salivação e sudorese\naumentadas. Ao exame físico apresenta temperatura axilar 37°C, pupilas puntiformes, sialorreia e\nmiofasciculações. A família refere ter utilizado, no dia anterior, um inseticida para tratar os\npiolhos\nda criança. O diagnóstico deste paciente será feito pela dosagem do nível de:","options":{"A":"Acetilcolinesterase no sangue.","B":"Chumbo no sangue.","C":"Malathion na urina.","D":"Mercúrio em urina de 24 horas."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-262796","number":"262796","sourceNumber":"262796","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente é admitido no pronto atendimento com quadro de hipersalivação, miose e\nbradicardia. Familiares relatam que ele apresentou os sintomas após ingerir alguma substância em\ncasa. Qual dos agentes abaixo pode ser responsável pelo quadro apresentado?","options":{"A":"Carbamato.","B":"Amitriptilina.","C":"Hipoclorito de sódio.","D":"Sertralina."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-261181","number":"261181","sourceNumber":"261181","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação aos procedimentos recomendados nos casos de exposição aos materiais\nbiológicos é correto afirmar que:","options":{"A":"Existem evidências que recomendam o uso de antissépticos ou a expressão do local do\nferimento na vigência de um acidente com material perfurocortante.","B":"Recomenda-se a lavagem exaustiva do local exposto com água e sabão nos casos de\nexposições percutâneas ou cutâneas.","C":"Não há estudos que justifiquem lavagem exaustiva com água ou com solução salina fisiológica,\nnas exposições de mucosas.","D":"Procedimentos que aumentam a área exposta (cortes, injeções locais) facilitam a limpeza e\ndevem ser realizados."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-255473","number":"255473","sourceNumber":"255473","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O uso do glucagon está indicado no tratamento da intoxicação aguda por","options":{"A":"antidepressivos tricíclicos.","B":"betabloqueadores.","C":"opioides.","D":"organofosforados."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-238448","number":"238448","sourceNumber":"238448","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual das opções abaixo contém o antidoto adequado para o tratamento de uma\nintoxicação grave por atenolol?","options":{"A":"Adrenalina","B":"Digoxina","C":"Amiodarona","D":"Glucagon","E":"Insulina NPH"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-253633","number":"253633","sourceNumber":"253633","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Com relação ao uso de benzodiazepínicos na Atenção Primária a Saúde, assinale a\nafirmativa CORRETA:","options":{"A":"Seu uso deve ser evitado na gestação; na lactação doses menores são utilizadas.","B":"O lorazepam tem a peculiaridade de ser o benzodiazepínico preferido para hepatopatas.","C":"Zolpidem é um hipnótico não benzodiazepínico que pode ser utilizados cronicamente na insônia\nporque não induz tolerância e nem abstinência.","D":"Não é necessário retirar benzodiazepínicos quando um quadro de ansiedade se estabilizou no\npaciente, pelo baixo percentual de efeitos colaterais que ele produz.","E":"Reduções abruptas são benéficas nos pacientes que fazem uso crônico de benzodiazepínicos."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-preventiva-med-pre-05-242038","number":"242038","sourceNumber":"242038","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"J.C.S, mulher, estudante, 22 anos, vem ao pronto socorro por tentativa de suicídio após\ningestão oral proposital de 400 mg de amitriptilina, um antidepressivo tricíclico com atividade\nanticolinérgica, há mais de 03 horas a sua chegada ao PS. Ao exame físico: confusa, em letargia e\ncom midríase bilateral. Seu eletrocardiograma no monitor mostra prolongamento do QRS, distúrbios\nde condução A-V e bradicardia. Neste caso, a melhor opção de tratamento seria:","options":{"A":"Uso de bicarbonato de sódio IV e colocação de marcapasso temporário","B":"Massagem do seio carotídeo","C":"Administração de amiodarona IV in bolus imediatamente","D":"Uso de procainamida IV e colocação de marcapasso temporário","E":"Gluconato de cálcio IV in bolus"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-242057","number":"242057","sourceNumber":"242057","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"J.F., 12 anos, é atendido no pronto-socorro pediátrico por sonolência e dificuldade de\ndeambulação. Há 3 dias, sempre no mesmo horário, por volta do meio dia, a menina apresenta\nsonolência, fala sem nexo, movimentos irregulares e dificuldade de marcha que melhoram com o\npassar do dia. Nega febre, vômitos e outros sintomas. Antecedente pessoais nada digno denota.\nAntecedentes familiares: irmão com diagnóstico de epilepsia. Ao exame físico: bom estado geral,\nacianótica, anictérica, afebril, FC= 100 bpm, FR= 24 ipm, PA= 110x70 mmHg. O exame neurológico\nrevela paciente sonolenta, desorientada, com nistagmo bilateral, força muscular de difícil\navaliação,\nreflexos presentes, marcha de base alargada. Qual a principal suspeita diagnóstica?","options":{"A":"Epilepsia","B":"Intoxicação exógena","C":"Tumor de cerebelo","D":"Malformação arteriovenosa","E":"Encefalite"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-239190","number":"239190","sourceNumber":"239190","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual a alternativa abaixo contem os sinais, sintomas e o manejo correto na intoxicação\npor lítio?","options":{"A":"Tremores grosseiros de extremidades, disartria, ataxia, diarréia e alteração do nível de\nconsciência. Manejo: coleta de litemia (parâmetro\npara acompanhamento), suspensão imediata do\nlítio, hidratação via endovenosa, controle de sinais vitais, monitoramento cardíaco e respiratório.","B":"Tremores grosseiros de extremidades, hiporreflexia, alteração do nível de consciência, dor\nabdominal e ataxia. Manejo: coleta de litemia (parâmetro para acompanhamento), suspensão\nimediata do lítio, hidratação via endovenos, controle dos sinais vitais, monitoramento cardíaco e\nrespiratório.","C":"Tremores grosseiros de extremidades, obstipação intestinal, hiporreflexia, febre, dispnéia e\ndisartria. Manejo suspensão do lítio para evitar virada maníaca, litemia seqüencial enquanto se\nrealizam sessões de diálise.","D":"Tremores grosseiros de extremidades, dispnéia, ataxia, febre e alteração do nível de\nconsciência. Suspensão progressiva do lítio para\nevitar virada maníaca, monitoramento cardíaco e\nrespiratório em jejum."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-217098","number":"217098","sourceNumber":"217098","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em unidade de pronto atendimento, dá entrada paciente vitima de tentativa de suicídio\npor ingesta de substâncias. Paciente\napresenta-se comatoso com pupilas mióticas, bastante\nsudoreico, com episódios de diarreia e com importante dispneia. À ausculta, roncos difusos em\npulmão, PA = 100 x 60 mmHg, FC = 42 bpm ao monitor em ritmos sinusal. Escolha a melhor\nalternativa sobre os sintomas e o agente mais provável:","options":{"A":"Pelos sintomas em sistema nervoso central, a intoxicação mais provável é por opioides com\nsintomas colinérgicos secundários.","B":"Trata-se de síndrome adrenérgica provavelmente relacionada à ingestão de antidepressivo\ntricíclico.","C":"Os sintomas são condizentes com síndrome colinérgica provocada por inibidores de\ncolinesterase como carbamato (?chumbinho?).","D":"Trata-se de síndrome adrenérgica provavelmente relacionada à ingestão de anfetaminas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-212439","number":"212439","sourceNumber":"212439","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"LME, 35 anos, dona de casa, chega ao Pronto-Socorro com a seguinte queixa:\n\n?Doutora, eu estava descansando na varanda de casa e senti uma picada no meu tornozelo, faz\nuns 20 minutos. Que dor horrorosa, meu\nDeus! Na hora doeu só o pé, mas agora a dor tá na perna\ntoda até na virilha. Não vi o que me mordeu, até procurei, mas não vi nada. Agora além da dor, tô\ncom vontade de vomitar.? Ao exame físico: REG, fácies de dor, palidez, discreta sudorese, FC =\n110 bpm, FR = 22, PA = 130x90 mmHg, Glasgow 15. BRNF 2T sem sopro, MV+ sem RA.\nNeurológico preservado. Em maléolo lateral observa-se ponto único de inoculação, edema de todo\no pé e tornozelo, coloração eritemato violacea ao redor do ponto de inoculação sem sinal de\nsangramento. Durante o exame físico paciente apresentou episódio de vômito. Você já tem ideia de\nque bicho mordeu essa senhora e decide pedir alguns exames: CPK e CKMB normais, ECG\nnormal, discreta hipopotassemia. Restante dos exames também normais: glicemia, sódio e amilase.\nCom base no caso acima marque a alternativa correta:","options":{"A":"Escorpionismo; classificação do acidente leve; controle da dor e alta;","B":"Escorpionismo; classificação do acidente moderada; controle da dor, monitoramento, soro\nescorpiônico;","C":"Botrópico; classificação do acidente moderada; controle da dor e soro antibotrópico;","D":"Loxoscelismo; classificação grave; controle da dor e soro antiloxoscélico;","E":"Acidente por abelha; classificação leve; controle da dor e alta."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-205736","number":"205736","sourceNumber":"205736","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A síndrome do QT longo com taquicardia ventricular por torsades de points é\ncaracterística por intoxicação exógena por:","options":{"A":"Ibuprofeno.","B":"Gasolina.","C":"Organofosforado.","D":"Paraquat.","E":"Cloranfenicol."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-178469","number":"178469","sourceNumber":"178469","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Faça a correlação entre agente tóxico e antídoto a ser usado em caso de intoxicação: I.\nOrganofosforado; II. Paracetamol; III. Benzodiazepínico; IV. Opiáceos; V. Cumarínicos; a.\n\nAcetilcisteina; b. Naloxona; c. Vitamina K; d. Flumazenil; e. Atropina.","options":{"A":"I - d, II - a, III - b, IV - c, V - e","B":"I - a, II - c, III - e, IV - b, V - d","C":"I - e, II - a, III - d, IV - b, V - c","D":"I - c, II - b, III - e, IV - a, V - d","E":"I - e, II - c, III - a, IV - d, V - b"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-178473","number":"178473","sourceNumber":"178473","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menina de 12 anos chega ao setor de emergência com o SAMU após ter sido\nencontrada no banheiro de casa, desacordada.\nAo exame físico é detectado: Glasgow 7, pupilas\nisocóricas puntiformes, temperatura corporal de 35,5 °C, pressão arterial 65/30. A partir dos dados\nacima qual a hipótese diagnostica?","options":{"A":"Intoxicação por barbitúrico.","B":"Intoxicação por atropina.","C":"Intoxicação por salicilato.","D":"Intoxicação por anfetamina.","E":"Intoxicação por antidepressivos tricíclicos."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-162055","number":"162055","sourceNumber":"162055","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A atitude contratural na qual o corpo passa a se apoiar na cabeça e nos calcanhares,\nassemelhando-se a um arco, comum em pacientes com tétano é:","options":{"A":"Posição de gatilho.","B":"Posição de arco.","C":"Opistótono.","D":"Ortótono."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-153196","number":"153196","sourceNumber":"153196","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Intoxicações medicamentosas são passíveis de ocorrer tanto acidental quando\nintencionalmente. É obrigação do médico ter\nconhecimento dos seus antídotos. Assinale qual das\nalternativas abaixo lista na ordem correta os antídotos dos seguintes medicamentos: paracetamol,\nopioides, benzodiazepínicos e cumarínicos.","options":{"A":"Acetilcisteína, flumazenil, naloxona e vitamina K.","B":"Vitamina K, flumazenil, naloxona e acetilcisteína.","C":"Vitamina K, naloxona, flumazenil e acetilcisteína.","D":"Naloxona, acetilcisteína, vitamina K e flumazenil.","E":"Acetilcisteína, naloxona, flumazenil e vitamina K."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-162347","number":"162347","sourceNumber":"162347","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre o choque anafilático assinale a alternativa CORRETA:","options":{"A":"a anafilaxia é a forma mais grave de manifestação alérgica sendo considerada uma emergência\nmédica","B":"como medida farmacológica, o corticoide é a droga de escolha como primeira linha de\ntratamento e desempenha o principal papel na abordagem do paciente com anafilaxia","C":"a adrenalina somente é recomendada nos casos de anafilaxia se não houver resposta ao\ncorticoide ou ao anti-histamíco","D":"somente é desencadeada por mecanismos imunológicos","E":"as alterações cutâneo-mucosas, respiratórias, gastrintestinais e cardiovasculares surgem cerca\nde minutos a horas após a exposição ao agente\ndesencadeante e não há possibilidade de novo\nepisódio ocorrer horas após a primeora manifestação, sem que tenha havido nova exposição ao\nalérgeno"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-162351","number":"162351","sourceNumber":"162351","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Com relação à intoxicação exógena, assinale a alternativa INCORRETA quanto a droga\ne seu antídoto:","options":{"A":"acetominofen, antídoto acetilcisteína","B":"barbitúricos, antídoto azul de metileno","C":"cumarínicos, antídoto vitamina K","D":"diazepínicos antídoto flumazenil","E":"organofosforados, antídoto atropina"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-149452","number":"149452","sourceNumber":"149452","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 22 anos de idade, é trazida pelos pais ao serviço de emergência com quadro\nde confusão mental, midríase, taquicardia,\nsedação, evoluindo em alguns minutos com convulsão.\nOs pais relatam que encontraram há meia hora a paciente deitada no chão do quarto e várias\ncartelas de comprimidos vazias. Contam que a paciente foi diagnosticada como sendo ?bipolar?\npelo generalista, tomava lítio, imipramina e diazepam e que vinha muito deprimida nos últimos dias.\nDeixou um bilhete de suicídio pedindo desculpas e dizendo que iria tomar todos os comprimidos de\num dos medicamentos que tinha, pois lera na bula que a intoxicação poderia ser fatal. A respeito\ndesse quadro clínico, assinale a alternativa CORRETA:","options":{"A":"A causa mais frequente de morte por intoxicação da medicação ingerida são arritmias cardíacas\ncomo distúrbios de condução.","B":"A combinação terapêutica de lítio e imipramina é considerada como de primeira linha para a\ndepressão bipolar.","C":"O remédio responsável pela intoxicação foi o carbonato de lítio e, por isso, deve ser realizada\nreposição volêmica vigorosa.","D":"Provavelmente, trata-se de intoxicação por benzodiazepínico e a convulsão ocorreu por\nsíndrome de abstinência.","E":"Por ter deixado um bilhete avisando sobre a ingestão, a intencionalidade do suicídio pode ser\nconsiderada baixa."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-126675","number":"126675","sourceNumber":"126675","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Adolescente, 16 anos de idade, sexo masculino, é trazido rapidamente ao\n\npronto-socorro por amigos, com história de ter ?passado mal? cerca de 30 minutos após receber\nmúltiplas picadas de inseto (abelha) durante\numa pescaria. Ao exame, estava em MEG, afebril,\ntaquidispneico (frequência respiratória = 36 irpm), com pressão arterial = 64/36 mmHg, com\nfrequência cardíaca = 144 bpm e com cianose de extremidades. Observavam-se lesões\nurticariformes disseminadas em membros e tronco e angioedema de lábios e pálpebras. À ausculta\npulmonar, apresentava estridor. Negava história prévia de reações alérgicas, rinite ou dermatite\natópica. Sobre o quadro apresentado, considere as afirmativas a seguir. I. A ausência de história\nprévia de atopia torna muito improvável o diagnóstico de choque anafilático. II. Os glicocorticoides\nsão o principal tratamento e devem ser administrados o mais precocemente possível. III. Deve ser\nadministrada adrenalina, preferencialmente por via intramuscular ou endovenosa. IV. Glucagon é\numa opção nos casos não responsivos à adrenalina ou com uso prévio de betabloqueadores.\n\nAssinale a alternativa correta.","options":{"A":"Somente as afirmativas I e II são corretas.","B":"Somente as afirmativas I e IV são corretas.","C":"Somente as afirmativas III e IV são corretas.","D":"Somente as afirmativas I, II e III são corretas.","E":"Somente as afirmativas II, III e IV são corretas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-102868","number":"102868","sourceNumber":"102868","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O acidente ofídico de maior importância epidemiológica no Brasil é o botrópico\nresponsável por 90% dos acidentes ofídicos. A\nrespeito dos acidentes por picada de Jararaca é\ncorreto afirmar:","options":{"A":"Tempo de Coagulação é um exame muito importante para elucidação diagnóstica e norteador\npara necessidade ou não de dose adicional de soro\nantibotrópico.","B":"O tempo de Protrombina é o exame mais indicado a ser feito antes da administração do soro\nespecífico e 24h após a primeira dose do soro antibotrópico.","C":"O veneno da jararaca produz lesão local por ação proteolítica mas não leva à alteração da\nfunção plaquetária ou plaquetopenia.","D":"Fenômenos hemorrágicos e até coagulação intravascular disseminada não são complicações\nesperadas em picadas por jararaca.","E":"O soro antibotrópico deve ser administrado apenas por acesso venoso central evitando-se ao\nmáximo o acesso periférico."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-106098","number":"106098","sourceNumber":"106098","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 3 anos de idade dá entrada no PS após apresentar rebaixamento do nível\nde consciência. Estava brincando na vizinha quando começou a ficar hipotônica. Nega febre. Ao\nexame apresenta-se sonolenta e bradicárdica, sem rigidez de nuca, pupilas isocóricas com RFM\nlento. Hipótese diagnóstica mais provável:","options":{"A":"Meningite viral.","B":"Hemorragia subaracnóidea.","C":"Intoxicação exógena.","D":"Distúrbio hidroeletrolítico.","E":"Tumor cerebral."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-106121","number":"106121","sourceNumber":"106121","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em casos de acidentes com animais peçonhentos, assinale a alternativa correta:","options":{"A":"Na maioria dos casos de acidentes com escorpiões, o tratamento é sintomático com infiltração\nde anestésico com vasoconstritor e analgésico\nsistêmico.","B":"Na grande maioria dos casos de acidentes com Loxosceles sp. ocorre hemólise intravascular\nnas\n\nprimeiras 24 horas após a picada que caracteriza a chamada forma cutâneo-visceral.","C":"O envenenamento causado pela penetração de cerdas de lagartas do gênero Lonomia na pele\npodem determinar manifestações hemorrágicas como gengivorragia e epistaxe.","D":"Se um paciente submetido à soroterapia anticrotálica há três semanas evolui com temperatura\nde 37,8º C, dores nos cotovelos e joelhos e\nadenomegalia subclavicular e retroauricular podemos\nestar diante de um caso de reação anafilática aos componentes do soro.","E":"No Brasil, dos quatro gêneros principais de serpentes peçonhentas, verifica-se o predomínio dos\nacidentes crotálicos (73,5%), seguidos do botrópico (7,5%), do elapídico (3%) e por último o\nláquético (0,7%)."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-100909","number":"100909","sourceNumber":"100909","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança oriunda de região rural é trazida ao pronto atendimento apresentando\nsinais de acidente por animal peçonhento,\nocorrido há mais de 12 horas. No tornozelo,\napresentava pequeno edema não doloroso, um pouco de formigamento; as pálpebras superiores\nestavam semicerradas, o que a impedia de enxergar direito; queixa-se de dores na nuca e desde o\nocorrido estava urinando cada vez menos. Baseado nestes dados, que tipo de acidente sofreu esta\ncriança?","options":{"A":"Picada de cobra do grupo botrópico.","B":"Picada de cobra do grupo crotálico.","C":"Picada de cobra do grupo elapídico.","D":"Picada de aranha ? Phoneutria.","E":"Picada de aranha ? Loxosceles."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-101429","number":"101429","sourceNumber":"101429","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um lavrador de 42 anos de idade é trazido ao pronto-socorro pelos familiares\napresentando mal-estar geral, dispneia, sudorese\nprofusa e diarreia há cerca de seis horas, com\npiora progressiva do quadro. Refere ter passado o dia aplicando inseticida na plantação de\ntomates, sem equipamento de proteção individual. Ao exame, encontra-se em REG; depletado\n2+/4+; PA = 112 x 58 mmHg; FC = 52 bpm; FR = 26 irpm; com diaforese, miose e lacrimejamento\nbilateral; sialorreia; roncos e sibilos difusos à ausculta pulmonar. Quanto ao diagnóstico mais\nprovável e o melhor tratamento indicado nesse caso, considere as afirmativas a seguir: I. Deve-se\nefetuar descontaminação imediata e progressiva com remoção das roupas e irrigação cutânea; II.\nAs principais causas de morte são insuficiência respiratória e colapso cardiovascular; III. É\nfortemente recomendada a confirmação do diagnóstico com dosagem do agente tóxico no plasma;\n\nIV. Pralidoxima deve ser administrada antes da atropina, para melhores resultados. Assinale a\nalternativa CORRETA:","options":{"A":"Somente as afirmativas I e II são corretas.","B":"Somente as afirmativas I e IV são corretas.","C":"Somente as afirmativas III e IV são corretas.","D":"Somente as afirmativas I, II e III são corretas.","E":"Somente as afirmativas II, III e IV são corretas."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-78947","number":"78947","sourceNumber":"78947","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Criança com 5 anos é levada ao serviço de emergência com quadro clínico de\nintoxicação, caracterizado por vômitos, diarreia e visão borrada. Ao exame físico apresenta\ntemperatura axilar 37°C, pupilas puntiformes, sialorreia e miofasciculações. A família utilizou\ninseticida, dias atrás, para \"desinfetar\" o colchão da criança. O diagnóstico deste paciente será\nfeito pela dosagem do nível de:","options":{"A":"Acetilcolinesterase no sangue.","B":"Chumbo no sangue.","C":"Malathion na urina.","D":"Mercúrio em urina de 24 horas.","E":"Meta-hemoglobina no sangue."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-81393","number":"81393","sourceNumber":"81393","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale a alternativa correta.","options":{"A":"Flumazenil deve ser utilizado nos casos de suspeita de intoxicação por opioides.","B":"A utilização da meperidina é preferencial em relação à morfina em virtude de seus poucos\nefeitos colaterais.","C":"A morfina pode ser utilizada com segurança em pacientes asmáticos, pois a mesma não produz\nliberação de histamina.","D":"Os efeitos colaterais mais comuns com o uso da dexmedetomidina são hipotensão e bradicardia.","E":"Benzodiazepínicos devem ser a primeira escolha na sedação dos pacientes graves, pois os\nmesmos estão relacionados com menor incidência de delirium."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-80545","number":"80545","sourceNumber":"80545","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O loxoscelismo é a forma mais frequente do aracneísmo no Brasil, em particular nas\nregiões sul e sudeste do país. Caracteriza-se como um problema de saúde pública por serem, em\ndeterminadas épocas do ano, motivos frequentes de consultas em unidades de saúde. Um menino\nde 05 anos é avaliado pelo médico com quadro de lesão sugestiva de acidente por animal\npeçonhento. O médico deve duvidar do diagnóstico de acidente por loxosceles quando:","options":{"A":"Dor em queimação no local da picada.","B":"Presença de bolha e mancha equimótica.","C":"Localização em parte coberta do corpo.","D":"Dor intensa e súbita logo após a picada.","E":"Área de necrose central com halo isquêmico."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-81404","number":"81404","sourceNumber":"81404","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem de 54 anos, com história de lombalgia crônica com uso prolongado de\n\nanti-inflamatório não hormonal e paracetamol associado à codeína, é admitido no pronto-socorro\ncom quadro de 3 dias de evolução com icterícia\ne náuseas. Relata ingestão de 4 garrafas de\ncervejas/dia há vários anos. Ao exame, paciente apresenta-se orientado, mas com asterix. Exames\ncomplementares evidenciaram AST: 2.840 U/L; ALT: 2.320 U/L; creatinina sérica: 2,8 mg/dl e pH:\n7,20. Qual deve ser a conduta?","options":{"A":"Iniciar protocolo de sepse, corticoterapia, antibioticoterapia de amplo espectro e indicar\nbiópsia\nhepática.","B":"Interromper a medicação e fazer acompanhamento ambulatorial com consultas e testes\nhepáticos semanais, prescrevendo complexo B e silimarina domiciliar.","C":"Iniciar protocolo de sepse, corticoterapia, antibioticoterapia de amplo espectro e observação\nclínica.","D":"Iniciar N-acetilcisteína em doses elevadas e hospitalização em serviço com equipe de\ntransplante hepático.","E":"Hospitalização em enfermaria para observação e acompanhamento da função hepática."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-58806","number":"58806","sourceNumber":"58806","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Embora a maioria dos pacientes com aumento da temperatura corporal apresente\nfebre, existem circunstâncias nas quais essa\nelevação de temperatura representa hipertermia,\ncaracterizada por elevação não controlada da temperatura corporal que excede a capacidade\norgânica de perder calor. A respeito do assunto, identifique as afirmativas a seguir como\nVerdadeiras (V) ou Falsas (F): ( ) Hipertermia induzida por drogas pode estar associada à\nutilização de anfetaminas, antidepressivos tricíclicos e cocaína. ( ) Na hipertermia maligna ocorre\nrápido aumento no cálcio intracelular em resposta ao halotano, outros anestésicos inalatórios ou à\nsuccinilcolina. ( ) A síndrome neuroléptica maligna está associada ao uso de neurolépticos, como\no haloperidol, e caracteriza-se por tônus muscular diminuído. ( ) Diarreia, tremor e mioclonia\nestão\nassociados à hipertermia relacionada à síndrome serotoninérgica. Assinale alternativa que\napresenta a sequência CORRETA, de cima para baixo:","options":{"A":"V ? V ? F ? V.","B":"F ? F ? V ? F.","C":"F ? F ? V ? V.","D":"V ? F ? V ? F.","E":"V ? V ? F ? F."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-66003","number":"66003","sourceNumber":"66003","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual dos pacientes abaixo apresentaria miose como manifestação de intoxicação\nexógena aguda?","options":{"A":"Homem de 24 anos após uso inalatório de cocaína.","B":"Mulher de 60 anos após intoxicação exógena intencional por morfina.","C":"Homem de 40 anos após intoxicação exógena intencional por bupropiona.","D":"Mulher de 32 anos após intoxicação exógena intencional por mirtazapina.","E":"Mulher de 18 anos após intoxicação exógena intencional por amitriptilina."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-63998","number":"63998","sourceNumber":"63998","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um adolescente que apresenta constantes mudanças de humor, comportamento\narredio e agressivo, mau rendimento escolar, deve\nser investigado em relação a:","options":{"A":"Traumatismo cranioencefálico.","B":"Hidrocefalia.","C":"Meningite subaguda.","D":"Uso de drogas ilícitas.","E":"Encefalite crônica."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-58618","number":"58618","sourceNumber":"58618","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 48 anos, masculino, com história de abuso de cocaína (crack) foi trazido ao\nPronto-Socorro (PS) por quadro de agitação e agressividade com início há 5 dias. Necessitou, ao\nchegar, de contenção física e medicamentosa (Haloperidol 5 mg 1 amp IM + Midazolam 15 mg 1\namp IM) repetidas vezes, o que se repetiu até o dia seguinte. Familiares relatam que o paciente\niniciou o quadro com falta de sono, passando a noite ao telefone e se apresentava sexualmente\ndesinibido. Após 48 horas de permanência no PS aguardando vaga para internação psiquiátrica,\ncomeçou a apresentar acentuação da confusão mental, períodos de sudorese franca, taquicardia,\npressão arterial instável e rigidez muscular intensa e persistente. Com 72 horas de evolução\napresentava grave hipertermia (T = 40,3°C) e piora ainda maior da confusão mental com períodos\nde mutismo. Foram solicitados exames, sendo os principais resultados hemograma com leucocitose\n(Leuc = 20000) sem desvio à esquerda, TSH = 0,5; T4 Livre = 1,2; CPK = 5639, hipernatremia,\ncreatinina = 1,6 e densidade urinária elevada (1030). Foi realizada punção liquórica, com exames\nnormais. O plantonista solicitou transferência para a UTI. Assinale abaixo a hipótese que melhor\nexplica a evolução clínica apresentada:","options":{"A":"Síndrome Neuroléptica Maligna.","B":"Síndrome de Abstinência à Cocaína.","C":"Tireotoxicose.","D":"Infecção do Sistema Nervoso Central.","E":"Delirium tremens."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-71605","number":"71605","sourceNumber":"71605","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um homem de 30 anos, trabalhador rural, alcoolista há 10 anos, tem rebaixamento do\nnível de consciência, pupilas mióticas, FC = 135 bpm, PA = 160 x 90 mmHg, FR = 18 irpm, SatO2 =\n92%, sialorreia abundante, ausculta pulmonar com roncos e fasciculações e piloereção em\nextremidades. Qual a conduta correta?","options":{"A":"Intubação orotraqueal e naloxana.","B":"Intubação orotraqueal e oxigênio a 100%.","C":"Intubação orotraqueal e atropina endovenosa.","D":"Intubação orotraqueal e TC de crânio."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-58826","number":"58826","sourceNumber":"58826","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Adolescente de 16 anos de idade é atendido por ataxia aguda. Foram afastadas causas\ninfecciosas e traumáticas. Assinale a alternativa com as substâncias que podem estar relacionadas\na esse quadro.","options":{"A":"Ácido valproico e fenobarbital.","B":"Cocaína e carbamazepina.","C":"Álcool e fenitoína.","D":"Clonazepam e propranolol.","E":"Manitol e diazepam."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-45977","number":"45977","sourceNumber":"45977","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Quanto ao uso, abuso e dependência de drogas, associe as colunas e assinale a\nalternativa que contém a sequência CORRETA:","options":{"I":"Ecstasy; II) Heroína; III) Maconha; IV) Cocaína. (\n\n) Pode produzir aumento da frequência cardíaca e pressão arterial, a eliminação é lenta, levando\ncerca de 40 horas para que 95% da droga\nseja eliminada, o que explica a persistência de alguns\nefeitos por um ou dois dias; ( ) A euforia é o efeito mais proeminente de seu uso e está\nrelacionada com o aumento da dopamina na fenda sináptica em regiões cerebrais relacionadas ao\nprazer e recompensa; ( ) O seu uso crônico está associado à ocorrência da síndrome\namotivacional, caracterizada pela diminuição da energia, além da dificuldade em persistir em\nqualquer tarefa que exija atenção prolongada ou tenacidade. ( ) No tratamento da intoxicação por\nessa droga usa-se naloxona, além do tratamento das complicações clínicas e da possível síndrome\nde abstinência.","A":"IV - I - II - III.","B":"I - III - II - IV.","C":"II - I - IV - III.","D":"I - IV - III - II.","E":"Nenhuma das sequências acima propostas estão corretas."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-34395","number":"34395","sourceNumber":"34395","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 4 anos de idade dá entrada no PS com história de vômitos há 1 dia, sendo\nmedicada, sem receita médica. Nega febre. Ao exame alterna sonolência e agitação e apresenta\nopistótono. O diagnóstico e a conduta a ser tomada:","options":{"A":"Meningite bacteriana, iniciar corticoide antes da primeira dose de Cefalosporina de 3ª geração.","B":"Síndrome de liberação extrapiramidal, iniciar biperideno.","C":"Meningite viral, medidas sintomáticas.","D":"Intoxicação exógena, iniciar hiper-hidratação e benzodiazepínico.","E":"Desidratação hipertônica, corrigir hipernatremia imediatamente."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-34497","number":"34497","sourceNumber":"34497","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A lesão abaixo é decorrente de acidente ofídico em área de mata no interior do Paraná.\nHavia ocorrido aproximadamente há 4 horas da entrada do paciente no hospital. Não há sintomas\nsistêmicos, apenas dor intensa no local. Pelo aspecto da lesão, assinale a alternativa que sugere\nCORRETA e RESPECTIVAMENTE a ação da peçonha e o gênero do ofídeo. (VER IMAGEM)","options":{"A":"Ação proteolítica e coagulante, gênero Bothrops.","B":"Ação proteolítica e coagulante, gênero Crotalus.","C":"Ação miotóxica e coagulante, gênero Micrurus.","D":"Ação miotóxica e neurotóxica, gênero Crotalus.","E":"Ação proteolítica e neurotóxica, gênero Bothrops."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-34340","number":"34340","sourceNumber":"34340","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sonolência, miose, coma, hipotensão arterial e depressão respiratória são sintomas de\nintoxicação por:","options":{"A":"Cocaína.","B":"Saliclatos.","C":"Fenotiazidas.","D":"Barbitúricos.","E":"Maconha."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-362234","number":"362234","sourceNumber":"362234","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente do sexo masculino, 25 anos de idade, residente na Ilha-do-Marajó no Estado\ndo Pará, foi picado por uma cobra na face\nlateral da perna esquerda, quando caminhava em área\nde campo aberto. Inicialmente não apresentou nenhuma sintomatologia; relatava apenas parestesia\nno local da picada, sem edema, eritema ou dor. Procurou atendimento médico após 12 horas do\nacidente no Hospital do Município e apresentava ptose bipalpebral e mandibular, oftalmoplegia,\nmialgias, oligúria e urina escura. Sobre o caso apresentado, é CORRETO afirmar que","options":{"A":"a serpente do acidente em questão tem como principal representante no Brasil a cobra coral\nverdadeira (Micrurus lemniscatus).","B":"o paciente pode apresentar como complicações gengivorragia, sangramento maciço, síndrome\ncompartimental e insuficiência renal aguda.","C":"se o acidente for classificado como grave, devem ser administradas 10 ampolas do soro\nantiofídico indicado para o caso.","D":"o soro ou antiveneno deve ser administrado o mais rapidamente possível por via intramuscular.","E":"se fosse vista, a cobra do caso seria de fácil identificação, pois teria fosseta loreal e na\ncauda\num chocalho ou guizo."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-313669","number":"313669","sourceNumber":"313669","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente de 25 anos foi trazido para a emergência, com rebaixamento do nível de\nconsciência e dispneia. Acompanhantes relataram que o quadro clínico começou com agitação\npsicomotora, durante a qual o paciente dizia que não estava enxergando direito. À admissão, ele\nestava normotenso, mas com acentuada taquipneia e torporoso. Gasimetria arterial, revelou intensa\nacidose metabólica com pH 7,12, bicarbonato 7 mEq/L e ânion gap elevado. Qual das opções\nabaixo melhor justificaria o quadro clínico-laboratorial desse caso?","options":{"A":"Cetoacidose diabética","B":"Intoxicação por metanol","C":"Sepse","D":"Acidose tubular renal tipo 2","E":"Desidratação secundária à diarreia e vômitos"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-313749","number":"313749","sourceNumber":"313749","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Os acidentes por animais peçonhentos no Brasil é tema de grande relevância, pois\npodem estar relacionados à ocorrência de\nóbitos ou produção de sequelas. Sobre esses acidentes,\nassinale a alternativa INCORRETA.","options":{"A":"São quatro os gêneros de serpentes de interesse médico: Bothrops, Crotalus, Lachesis e\nMicrurus.","B":"No ofidismo, o soro ou antiveneno deve ser específico para cada tipo de acidente, e a via de\nadministração é a endovenosa.","C":"No escorpionismo, o soro antiescorpiônico ou antiaracnídico é indicado nos acidentes\nmoderados e graves.","D":"O araneísmo constitui, dentre os acidentes por animais peçonhentos, o de maior interesse\nmédico devido à frequência e gravidade.","E":"A picada de aranha do gênero Loxosceles pode causar úlcera necrótica na região afetada."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-242193","number":"242193","sourceNumber":"242193","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma mulher de 31 anos que trabalha como auxiliar de serviços gerais em um hospital\nfoi trazida para a emergência com suspeita de\nintoxicação exógena. Ela tem acesso a todos os\nsetores do hospital; os funcionários da farmácia estão levantando os estoques para definir a falta\nde algum medicamento, mas essa informação ainda não está disponível. Ao exame, ela se\napresenta agitada, em aparente delirium, com flushing facial, pele seca, hipertermia, midríase e\ntaquicardia. O exame do abdome demonstra ausência de ruídos hidroaéreos e globo vesical\npalpável. Eletrocardiograma mostrou alargamento do complexo QRS. Com base nos dados do\nexame físico, qual o provável agente ingerido?","options":{"A":"Amitriptilina.","B":"Morfina.","C":"Diazepam.","D":"Metanol.","E":"Neostigmine."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-245517","number":"245517","sourceNumber":"245517","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher, 23 anos, trazida por familiares a unidade de emergência, sonolenta, Glasgow\n10, FC = 100 bat/min, PA = 120/73 mmHg,\nafebril, Glicemia capilar de 160mg%. Sem doenças\nprevias. Família informa uso recente de clonazepan. A conduta inicial é:","options":{"A":"Intubação oro traqueal, expansão volêmica, passar SNG e carvão ativado.","B":"Expansão volêmica e Flumazenil endovenoso.","C":"Expansão volêmica e Naloxona injetável.","D":"Fazer 10 unidades de insulina regular, expansão volêmica e piridoxina.","E":"Fazer expansão volêmica e glucagon injetável."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-338033","number":"338033","sourceNumber":"338033","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O abuso de medicações opioides continua sendo um grande desafio médico. Analise as\nafirmações a seguir e marque a que contenha sintomas característicos de intoxicação pelos\nopioides:","options":{"A":"pico hipertensivo e convulsão.","B":"diminuição da frequência cardíaca e pupilas mióticas.","C":"hipotensão e taquipneia.","D":"aumento dos ruídos hidroaéreos e midríase.","E":"hipertermia e taquicardia."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-338001","number":"338001","sourceNumber":"338001","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Intoxicação aguda por monóxido de carbono é uma intercorrência grave que pode\ncausar sintomas críticos como convulsões, dispneia\ne coma, sendo capaz de levar até o óbito. Na\nintoxicação aguda moderada por monóxido de carbono, espera-se encontrar:","options":{"A":"paO2 normal","B":"Alcalose respiratória","C":"Alcalose metabólica","D":"Acidose metabólica sem hiperlactatemia","E":"Diminuição dos níveis de carboxi-hemoglobina"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-341351","number":"341351","sourceNumber":"341351","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Antes de o Brasil registrar qualquer caso suspeito de Mpox, termo definido pela\nOrganização Mundial de Saúde (OMS) para\ndenominação da varíola dos macacos, o Ministério da\nSaúde estabeleceu uma Sala de Situação para monitorar o cenário da doença no país. Desde\nentão, a pasta analisa diuturnamente a situação epidemiológica, para orientar as ações de\nvigilância. Sobre a vigilância epidemiológica da Mpox, assinale a alternativa CORRETA.","options":{"A":"Por se tratar de uma doença rara, em fase inicial de disseminação, a Mpox ainda não foi incluída\nna Lista Nacional de Notificação Compulsória\nde doenças, agravos e eventos de saúde pública nos\nserviços de saúde públicos e privados em todo o Brasil.","B":"Todos os resultados de testes diagnósticos para detecção da varíola dos macacos feitos por\nlaboratórios das redes pública, privada, universitários e quaisquer outros em todo o País precisam\nser informados ao Ministério da Saúde de forma imediata, em até 24 horas.","C":"Para quem testou positivo para Mpox, não há necessidade de isolamento até o desaparecimento\ndas crostas e a completa cicatrização da pele,\nsem a necessidade de um novo teste.","D":"Frente à suspeita clínica de Mpox, recomenda-se solicitar exames diagnósticos e aguardar o\nresultado para poder comunicar as autoridades sanitárias sobre o possível caso da doença.","E":"A definição de caso de Mpox é ?individuo com histórico de relação sexual do mesmo sexo, de\nqualquer idade que apresente início súbito de lesão em mucosas e/ou erupção cutânea aguda\nsugestiva de Mpox, única ou múltipla, em qualquer parte do corpo (incluindo região genital/perianal,\noral) E/OU proctite (por exemplo, dor anorretal, sangramento), E/OU edema peniano, podendo\nestar associada a outros sinais e sintomas?."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-216782","number":"216782","sourceNumber":"216782","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Tatiana, 16 anos, é trazida à emergência após tentativa de suicídio. Ingeriu cerca de 30\ncomprimidos de acetominofen 500 mg há cerca de cinco horas. No momento, encontra-se estável\nhemodinamicamente e com náuseas. Sem outras queixas ou achados no exame físico. Assinale a\nconduta CORRETA.","options":{"A":"Uma SNG deverá ser passada e uma lavagem gástrica deverá ser realizada imediatamente.\n\nHidratação venosa deverá ser instalada e o bicarbonato de sódio está indicado.","B":"Uma SNG deverá ser passada e uma lavagem gástrica deverá ser realizada imediatamente.\n\nHidratação venosa deverá ser instalada e o xarope de ipeca está indicado.","C":"Administrar primeira dose de N-Acetilcisteína VO ou IV, solicitar dosagem do nível plasmático de\nparacetamol e provas de função hepática.","D":"Plasma-light deverá ser prescrito imediatamente, além de solicitar provas de função renal e\nmedular.","E":"Nenhuma das anteriores está correta."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-162604","number":"162604","sourceNumber":"162604","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 3a, é trazida pela mãe, que refere aparecimento de lesão em dorso de pé\ndireito há 3 dias, que inicialmente era uma\nbolha com conteúdo seroso com edema local, evolui\ncom piora progressiva da lesão. Exame físico: Pele: lesão dolorosa, endurada, equimótica,\nmesclada com áreas pálidas de isquemia com bolha necro-hemorrágica em dorso de pé esquerdo.\nO quadro acima se refere a acidente:","options":{"A":"Escopiônico","B":"Brotrópico","C":"Crotélico","D":"Loxoscélico","E":"Nenhuma das respostas anteriores."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-162614","number":"162614","sourceNumber":"162614","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 5a, retorna para avaliação de hemograma solicitado anteriormente. De acordo\ncom a mãe, este exame foi repetido pois os\nanteriores tinham uma alteração nas ?células\nbrancas?. Previamente hígido. Exame físico: descorado +/4+, sem outras alterações. Hemograma:\nHb= 10,4g/dL; Ht: 30%, RDW= 14%, Leucócitos= 2.600mm3 (1% bastonetes, 40% segmentados,\n2% eosinófilos, 50% linfócitos típicos e 7% monócitos). A causa mais comum que explica estas\nalterações hematológicas é:","options":{"A":"Presença de anticorpos anti-leucócitos.","B":"Exposição a pesticidas/derivados de benzeno.","C":"Sepse.","D":"Hipoplasia medular.","E":"Uso de dipirona."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-111528","number":"111528","sourceNumber":"111528","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre o manejo das intoxicações exógenas em Pediatria, assinale a alternativa\nINCORRETA:","options":{"A":"O tratamento deve ser imediato a fim de prevenir a absorção do tóxico e aumentar a sua\neliminação.","B":"A hiperventilação pulmonar é indicada para facilitar a eliminação de tóxicos voláteis.","C":"A lavagem gástrica deverá ser realizada, em todos os pacientes agitados ou comatosos, ainda\nnas primeiras duas horas após ingestão das substâncias tóxicas a fim de diminuir a absorção do\nagente e o risco de agravamento clínico.","D":"O carvão ativado apresenta alto poder de adsorção e está indicado em caso de\nintoxicação por antidepressivos tricíclicos, fenobarbital e carbamazepina. Pode causar abdome\nagudo obstrutivo como efeito colateral.","E":"Os compostos tóxicos removíveis por diálise devem apresentar baixo peso molecular, alta\nhidrossolubilidade, baixa ligação proteica e moléculas não-ionizadas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-354271","number":"354271","sourceNumber":"354271","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Nos Estados Unidos da América (EUA), em 2018, a maconha foi utilizada por 43\nmilhões de pessoas. De 2008 a 2017, a\nconcentração de tetrahidrocanabinol (THC) aumentou de\n8,9 para 17,1% e, atualmente, em alguns preparados para vaping chega até 95%. Analise as\nafirmativas a seguir sobre o uso de maconha: I) Craving pela substância, dificuldade para\ndesempenhar o papel acadêmico ou profissional, ansiedade, inquietação, insônia e redução do\napetite após a cessação do seu uso são sintomas que podem indicar um padrão problemático do\nuso de maconha. II) Idade precoce de início do uso da substância, frequência de uso e exposição a\nmaconha com alta concentração de THC aumentam o risco do desenvolvimento de um transtorno\nmental e do comportamento por uso de cannabis. III) O uso de preparações comestíveis de\nmaconha (edibles) não está relacionado ao risco de overdose. Pode-se afirmar que está(ão)\ncorreta(s) a(s) afirmativa(s):","options":{"A":"II","B":"I","C":"I e II","D":"II e III"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-354256","number":"354256","sourceNumber":"354256","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Nos EUA, há uma verdadeira crise de abuso de opioides. Apesar de no Brasil o quadro\nnão ser tão calamitoso, é preciso que todo\nmédico esteja preparado para rapidamente reconhecer e\ntratar uma overdose destas substâncias. Pode-se afirmar, neste contexto, que:","options":{"A":"à monitorização cardíaca, isquemia miocárdica e intervalo QT encurtado são eventualmente\nobservados","B":"respiração superficial e lenta, hipertermia, midríase e bradicardia estão tipicamente presentes","C":"lacrimejamento, rinorreia, dores musculares, inquietação e diarreia são frequentes nos jovens","D":"apesar de raro, quadros convulsivos às vezes ocorrem nos casos de uso de altas doses de\ntramadol"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-330383","number":"330383","sourceNumber":"330383","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem, 54 anos, é vítima de picada de cobra em membro superior direito. Pode-se\nafirmar que a melhor conduta é:","options":{"A":"remover o paciente da área de perigo; realizar torniquete no membro superior até transportar\npara o hospital objetivando diminuir circulação\nde toxinas","B":"limpar a ferida e elevar o membro afetado; prosseguir com aspiração da ferida objetivando\naspirar o conteúdo tóxico; transportar para o\nhospital para avaliação de administração de soro\nantiofídico","C":"remover o paciente da área de perigo; limpar a ferida e elevar o membro; transportar para o\nhospital para avaliação de necessidade de administração de soro antiofídico","D":"limpar a ferida; realizar crioterapia local; transportar para o hospital para avaliação de\nnecessidade de administração de soro antiofídico"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-266279","number":"266279","sourceNumber":"266279","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 2 anos, é levado à emergência após ser encontrado, há cerca de uma hora e\nmeia, com um frasco vazio de descongestionante nasal (cujo princípio ativo era a nafazolina).\n\nSegundo o pai, o frasco estava cheio, pois havia sido aberto no dia anterior. Exame físico:\nhipotérmico; bradicárdico; pálido; sonolento; com\ndiaforese; hipotenso; com pausas respiratórias. A\nconduta mais adequada, neste momento para a criança, é:","options":{"A":"iniciar imediatamente n-acetilcisteína na dose de 140mg/kg","B":"esvaziar o estômago através de sonda gástrica e o utilizar carvão ativado","C":"induzir vômito utilizando detergente líquido","D":"aquecer e monitorar no hospital por seis horas"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-246039","number":"246039","sourceNumber":"246039","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Nos últimos anos, observamos um aumento no número de acidentes por escorpião.\nAcerca destes acidentes, assinale a assertiva\nINCORRETA:","options":{"A":"Em casos leves, com manifestações apenas locais, o tratamento é apenas sintomático.","B":"Casos graves são mais frequentes em crianças menores de 10 anos.","C":"Deve-se procurar atendimento médico imediatamente.","D":"As manifestações sistêmicas são sempre tardias.","E":"A intensidade das manifestações depende da quantidade de veneno inoculada."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-59661","number":"59661","sourceNumber":"59661","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O antídoto para intoxicação por paracetamol na criança é:","options":{"A":"A acetilcisteína.","B":"O fometizol.","C":"A vitamina K.","D":"A clonidina."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-371221","number":"371221","sourceNumber":"371221","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Monkeypox (MPX) é uma doença zoonótica viral, causada pelo Monkeypox vírus, do\ngênero Orthopoxvirus e família Poxviridae. O nome deriva da espécie em que a doença foi\ninicialmente descrita em 1958. Sobre essa doença, podemos afirmar que:","options":{"A":"os primatas não humanos (macacos) são reservatórios do vírus","B":"a doença evolui sempre de forma rápida e dramática, com necessidade de cuidados intensivos","C":"a incubação dura de 2 a 7 dias, em média, podendo chegar a 14 dias","D":"a transmissão ocorre desde o aparecimento dos sinais e sintomas até a erupção de pele ter\ncicatrizado completamente, com a formação de uma nova camada de pele"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-368817","number":"368817","sourceNumber":"368817","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente busca pronto socorro após episódio de acidente ofídico. Segundo relato dele\nfoi picado por uma cascavel, entretanto o\npaciente não soube descrever bem o animal tão pouco o\nlevou a unidade de saúde. A ferida apresentava edema e dor intensa local com algumas bolhas de\ncaracterística necrótica. Além disso o paciente apresentava gengivorragia. Diante do quadro qual a\nmelhor conduta a seguir?","options":{"A":"Administrar o soro anticrotálico uma vez que se trata de uma picada de cascavel.","B":"Administrar o soro antibotrópico-antilaquético ainda que o paciente tenha referido uma picada de\ncascavel.","C":"A cascavel não é uma cobra presente na fauna brasileira, portanto deve-se desconsiderar o\npotencial peçonhento e focar na infecção secundária da ferida administrando antibióticos venosos.","D":"Deve-se procurar pela cobra para sua identificação e tratamento correto."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-351770","number":"351770","sourceNumber":"351770","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente chega ao pronto socorro do HCTCO, referindo ter ingerido grande\nquantidade de hioscina, que é um medicamento\ncom efeito anticolinérgico, para controle de dor\nabdominal. Dentre os efeitos do abuso do medicamento podemos encontrar os seguintes achados,\nEXCETO:","options":{"A":"Miose","B":"Midríase","C":"Hipertensão","D":"Taquicardia","E":"Mucosas secas"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-343100","number":"343100","sourceNumber":"343100","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Monkeypox é uma doença causada pelo Monkeypox vírus, uma doença zoonótica viral.\nSobre essa patologia, podemos AFIRMAR:","options":{"A":"a transmissão ocorre apenas quando há erupção cutânea em fase exudativa","B":"a transmissão entre humanos ocorre através do contato pessoal próximo","C":"a incubação dura de 2 a 7 dias, em média, podendo chegar a 10 dias","D":"os principais reservatórios são os primatas não humanos"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-343102","number":"343102","sourceNumber":"343102","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A doença Monkeypox se tornou uma preocupação do Ministério da Saúde (MS) o qual\nvem monitorando desde do surgimento de casos. Com relação as características gerais desta\ndoença, está INCORRETO afirmar que:","options":{"A":"a transmissão ocorre por contato direto com lesões de pele, erupções cutâneas, crostas ou\nfluidos corporais de uma pessoa infectada (secreções, sangue)","B":"a doença geralmente evolui com sinais e sintomas leves (febre, erupção cutânea, calafrios)","C":"o período de incubação dura em média de 3 a 5 dias, podendo chegar a 9 dias","D":"a manifestação cutânea típica é do tipo papulovesicular"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-323791","number":"323791","sourceNumber":"323791","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Diante da epidemia atual de varíola símia (Monkeypox), o CDC (Centers for Disease\nControl and Prevention) liberou para uso em\ncaráter excepcional nos pacientes com a forma grave\nda doença o uso de terapia antiviral. O antiviral em questão é o:","options":{"A":"Aciclovir.","B":"Foscarnet.","C":"Baloxavir-marboxil.","D":"Tecovirimat.","E":"Ribavirina."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-332543","number":"332543","sourceNumber":"332543","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menina, 3 anos é trazida ao pronto-socorro por ter ingerido, há cerca de 3 horas, alguns\nmedicamentos de sua mãe, que tem hipertensão arterial, asma e diabete mellitus. A criança é\nadmitida no hospital com saturação arterial de 97%, frequência cardíaca de 45 bpm, pressão\narterial de 60x35 mmHg, frequência respiratória de 18 mpm e glicemia capilar de 250 g/dl. O mais\nprovável medicamento envolvido na intoxicação desta criança é um:","options":{"A":"Diurético.","B":"Corticoide.","C":"Bloqueador do canal de cálcio.","D":"Hipoglicemiante oral."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-344922","number":"344922","sourceNumber":"344922","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre acidente por ingestão de material cáustico, é INCORRETO afirmar:","options":{"A":"O tratamento inicial inclui remoção completa do produto da pele ou olhos por meio do uso de\njatos d'água.","B":"O carvão ativado não deve ser usado porque não se liga a esse agente e pode predispor o\npaciente a vômitos e subsequente aspiração.","C":"A endoscopia deve ser realizada no período de 12-24 horas da ingestão em pacientes\nsintomáticos ou naqueles nos quais haja\nsuspeita de lesão com base na história e características\ndo produto ingerido.","D":"O uso de corticosteróides não é benéfico no manejo de lesões grau I e grau III.","E":"Deverá ser inserida sonda nasogástrica por enfermeiro experiente para evitar estenoses\nassociadas à queimadura química no trato gastrointestinal."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-323831","number":"323831","sourceNumber":"323831","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Apesar da indisponibilidade no Brasil, o CDC e o ACIP (Advisory Committee on\nimmunization Practices) já emitiram orientações acerca da vacina JYNNEOS para varíola /\nmonkeypox. Qual das afirmativas abaixo, segundo o CDC e ACIP, está correta:","options":{"A":"Apenas o uso profilático da JYNNEOS é eficaz.","B":"JYNNEOS está recomendada em até quatro dias após a exposição. Se administrada entre 4 e\n14 dias após exposição, consideramos a\nvacinação, mesmo que menos eficaz.","C":"Somente indivíduos que nunca foram vacinados para varíola devem receber a JYNNEOS após\nexposição.","D":"Por ser uma vacina de vírus vivo atenuado não replicante, seu uso em imunodeprimidos está\nproscrito.","E":"O esquema vacinal é composto por três doses, com intervalo de dois meses entre cada dose."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-340829","number":"340829","sourceNumber":"340829","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma jovem de 15 anos chega à emergência após ingerir vários comprimidos de\nclonazepam e propranolol. Encontra-se sonolenta, desorientada, bradicárdica, hipotensa e\nlevemente cianótica. Entre as medidas gerais de suporte foram utilizados os antídotos:","options":{"A":"Bicarbonato de sódio e gluconato de cálcio","B":"Adrenalina e digoxina","C":"Atropina e insulina","D":"Flumazenil e glucagon","E":"Sulfato de magnésio e noradrenalina"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-323762","number":"323762","sourceNumber":"323762","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Levando em consideração os efeitos de intoxicação por antidepressivos tricíclicos\n(amitriptilina), ocorrida há mais de 4 horas, devemos imediatamente iniciar: ECG triciclicos.","options":{"A":"Carvão ativado por via enteral","B":"Bicarbonato de sódio endovenoso","C":"Flumazenil endovenoso","D":"Gluconato de cálcio endovenoso","E":"Naloxona"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-339574","number":"339574","sourceNumber":"339574","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente masculino, 34 anos, bissexual, refere febre, cefaléia, tosse, mialgia,\nlinfadenopatia cervical. Apresentava ainda lesões\nno rosto, que surgiram 2 dias após o início do\nquadro e que se tornaram disseminadas pelo corpo. Estas inicialmente eram eritematosas e sobre\nas mesmas surgiram vesículas com secreção, que romperam com surgimento de crostas. Qual a\nprincipal suspeita diagnóstica e qual exame laboratorial para confirmar o diagnóstico?","options":{"A":"Sífilis ? FTAbs","B":"Monkeypox ? qPCR","C":"Cancro Mole ? cultura","D":"COVID-19 ? RT-PCR"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-344823","number":"344823","sourceNumber":"344823","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em 23/07/2022, a Organização Mundial da Saúde (OMS) reconheceu que a\ndisseminação internacional do vírus da Varíola dos\nMacacos (MPX) constitui uma emergência em\nsaúde pública de interesse internacional. Em relação às características epidemiológicas da\nepidemia do vírus da Varíola dos Macacos (MPX) de 2022, é CORRETO afirmar que:","options":{"A":"A concentração de casos entre homens que fazem sexo com homens era esperada,\nconsiderando o número de parceiros sexuais neste grupo.","B":"A rápida disseminação em regiões não endêmicas sugere que o MPX já estava circulando de\nforma não detectada por algum tempo.","C":"A transmissão ocorre prioritariamente pelo sêmen e por secreções vaginais.","D":"A variante 1, antiga variante da África Ocidental e considerada uma das mais virulentas, é a\nresponsável pela disseminação global em 2022."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-313959","number":"313959","sourceNumber":"313959","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Como proceder em caso de acidente escorpiônico?","options":{"A":"Amarrar ou fazer torniquete.","B":"Aplicar algum tipo de substância sobre o local da picada (fezes, álcool, querosene, fumo, ervas,\nurina) e fazer curativos que fechem o local.","C":"Cortar, perfurar ou queimar o local da picada.","D":"Dar bebidas alcoólicas ao acidentado, ou outros líquidos como álcool, gasolina, querosene para\naliviar a dor.","E":"Limpar o local com água e sabão, procurar orientação médica imediata e mais próxima do local\nda ocorrência do acidente e se for possível,\ncapturar o animal e levá-lo ao serviço de saúde, pois a\nidentificação do escorpião causador do acidente pode auxiliar o diagnóstico."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-300757","number":"300757","sourceNumber":"300757","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança de 3 anos é trazida ao pronto-socorro por ter ingerido, há cerca de 3\nhoras, alguns medicamentos de sua avó, que tem\nhipertensão arterial, asma e diabete mellitus. A\ncriança é admitida no hospital com saturação arterial de 97%, frequência cardíaca de 45 bpm,\npressão arterial de 60x35 mmHg, frequência respiratória de 18 mpm e glicemia capilar de 250 g/di.\nO mais provável medicamento envolvido na intoxicação desta criança é um:","options":{"A":"Diurético.","B":"Corticoide.","C":"Bloqueador do canal de cálcio.","D":"Inibidor da monoamina oxidase.","E":"Hipoglicemiante oral."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-296958","number":"296958","sourceNumber":"296958","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale qual droga é utilizada como antagonista dos opióides, nos casos de depressão\nrespiratória?","options":{"A":"Salbutamol","B":"Flumazenil","C":"N-Acetilcisteína","D":"Naloxona","E":"Atropina"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-316857","number":"316857","sourceNumber":"316857","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Correlacione: I - Benzeno; II - Organofosforado; III - Piretróides; IV - Carbamatos; ( )\nLeucemia; ( ) Alergia; ( ) Parkinsonismo; ( ) Comprometimento sistema nervoso autônomo; Assinale\na sequência correta:","options":{"A":"I ? II ? III ? IV","B":"I ? III ? IV ? II","C":"II ? I ? IV ? III","D":"IV ? II ? III ? I","E":"III ? I ? II ? IV"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-273231","number":"273231","sourceNumber":"273231","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente de 26 anos dá entrada na emergência com quadro de náuseas, vômitos,\ndor abdominal, redução no volume urinário, seguidos\nde sinais de paralisia facial, visão turva,\ndesorientação e crise convulsiva. Acompanhante informa a ingesta de cerveja artesanal cerca de\n48 horas atrás. Suspeitou-se de intoxicação exógena por etilenoglicol. Assinale a alternativa\nCORRETA em relação ao provável quadro laboratorial que esse paciente apresentará.","options":{"A":"Sódio = 140 mEq/L; cloreto = 102 mEq/L; bicarbonato = 10 mEq/L; glicose = 100 mg/dl; ureia =\n120 mg/dl e medida direta da osmolaridade\nsérica = 325 mOsm/L.","B":"Sódio = 140 mEq/L; cloreto = 116 mEq/L; bicarbonato = 10 mEq/L; glicose = 100 mg/dl; ureia =\n120 mg/dl e medida direta da osmolaridade\nsérica = 325 mOsm/L.","C":"Sódio = 140 mEq/L; cloreto = 102 mEq/L; bicarbonato = 10 mEq/L; glicose = 100 mg/dl; ureia =\n120 mg/dl e medida direta da osmolaridade\nsérica = 305 mOsm/L.","D":"Sódio = 140 mEq/L; cloreto = 116 mEq/L; bicarbonato = 10 mEq/L; glicose = 100 mg/dl; ureia =\n120 mg/dl e medida direta da osmolaridade\nsérica = 305 mOsm/L.","E":"Sódio = 140 mEq/L; cloreto = 116 mEq/L; bicarbonato = 28 mEq/L; glicose = 100 mg/dl; ureia =\n120 mg/dl e medida direta da osmolaridade\nsérica = 305 mOsm/L."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-273232","number":"273232","sourceNumber":"273232","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente de 26 anos dá entrada na emergência com quadro de náuseas, vômitos,\ndor abdominal, redução no volume urinário,\nseguidos de sinais de paralisia facial, visão turva,\ndesorientação e crise convulsiva. Acompanhante informa a ingesta de cerveja artesanal cerca de\n48 horas atrás. Suspeitou-se de intoxicação exógena por etilenoglicol. Ainda sobre o enunciado da\nquestão anterior, assinale a alternativa CORRETA em relação à medida terapêutica de escolha:","options":{"A":"reposição de bicarbonato de sódio;","B":"etanol;","C":"fomepizole;","D":"hemodiálise;","E":"metanol."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-278040","number":"278040","sourceNumber":"278040","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente feminina, 58 anos, deu entrada na emergência com quadro de hipotensão,\ndiarreia, tremores e confusão mental há cerca de 12\nhoras. Tem diagnóstico prévio de transtorno\nbipolar e faz uso de carbonato de lítio há 08 meses. Na última avaliação, apresentava dosagem\nsérica de lítio de 1,1 mEq/L (N: 0,8?1,2). Ao exame: desidratada, confusa, com tremores de\nextremidades, nistagmo e ataxia. PA = 90 x 50 mmHg. Exames laboratoriais: ureia = 70 mg/dl;\ncreatinina = 1,9 mg/dl; lítio = 3,8 mEq/L; glicemia = 92 mg/dl. Além da hidratação com solução\nsalina, a conduta indicada é:","options":{"A":"Lavagem gástrica.","B":"Naloxone IV.","C":"Hemodiálise.","D":"Atropina IV."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-287701","number":"287701","sourceNumber":"287701","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Criança de 4 anos de idade é encontrada, na área de serviço, comatosa, apresentando\nbradicardia, miose, sialorreia e fraqueza muscular. Apresenta um odor de petróleo. Suspeitando de\nque tenha ocorrido uma intoxicação exógena, o agente mais provável é:","options":{"A":"A água sanitária.","B":"A pseudoefedrina.","C":"Um organofosforado.","D":"Um antidepressivo tricíclico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-283664","number":"283664","sourceNumber":"283664","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre os acidentes por serpentes de importância médica, qual gênero é o de maior\nimportância e distribuição dentre os acidentes ofídicos no Brasil:","options":{"A":"Crotálico.","B":"Eunectes.","C":"Botrópico.","D":"Elapídico.","E":"Laquético."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-283693","number":"283693","sourceNumber":"283693","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente vítima de acidente ofídico com história de dor e edema leves, restritos ao\nredor da picada. Evoluiu com manifestações neuroparalíticas com progressão craniocaudal,\niniciando-se por ptose palpebral, turvação visual e oftalmoplegia. Progressivamente, houve o\naparecimento de mialgia generalizada e escurecimento da cor da urina (cor de \"Coca-Cola\"),\ninsuficiência renal aguda e óbito. Qual o provável gênero do animal peçonhento descrito neste\ncaso?","options":{"A":"Lachesis.","B":"Bothrops.","C":"Crotalus.","D":"Bothrocophias.","E":"Philodryas."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-286558","number":"286558","sourceNumber":"286558","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O acidente botrópico é o de maior importância e distribuição dentre os acidentes\nofídicos no Brasil. Qual das alternativas\nabaixo descreve o quadro clínico do paciente vítima deste\nacidente ofídico?","options":{"A":"Presença de dor, edema e equimose na região da picada. Bolhas com conteúdo seroso ou\nserohemorrágico podem surgir e originar áreas de necrose, que, juntamente com infecção\nsecundária, constituem as principais complicações locais e podem levar à amputação e/ou deficit\nfuncional do membro. A ocorrência de sangramentos em pele e mucosas são comuns\n(gengivorragia, equimoses a distância do local da picada); hematúria, hematêmese e hemorragia\nem outras cavidades. Hipotensão pode ser decorrente de sequestro de líquido no membro picado\nou hipovolemia consequente a sangramentos, que podem contribuir para o desenvolvimento de\ninsuficiência renal aguda","B":"Ocorre dor, edema e equimose na região da picada (pode progredir ao longo do membro\nacometido). As marcas de picada e sangramento nem sempre são visíveis nos pontos de\nintrodução das presas. As alterações vagais (náuseas, vômitos, cólicas abdominais, diarreia,\nhipotensão, choque) estão presentes na totalidade dos casos que não recebem soroterapia\noportunamente","C":"Não se evidenciam alterações significativas. Dor e edema são usualmente discretos e restritos\nao redor da picada. Eritema e parestesia são\ncomuns. As manifestações sistêmicas\nneuroparalíticas com progressão crânio-caudal, iniciando-se por ptose palpebral, turvação visual e\nofalmoplegia. Distúrbios de olfato e paladar, ptose mandibular e sialorreia podem ocorrer com o\npassar das horas. Raramente, a musculatura da caixa torácica é acometida. Essas manifestações\nneurotóxicas regridem lentamente, porém são reversíveis. Raramente pode haver gengivorragia e\noutros sangramentos discretos. Progressivamente, surgem mialgia generalizada e escurecimento\nda cor da urina (cor de \"\"coca-cola\"\" ou \"\"chá preto\"\"). A insuficiência renal aguda é a principal\ncomplicação e causa de óbito","D":"Localmente o paciente manifesta dor e parestesia na região da picada discretos, não havendo\n\nlesões evidentes. Caracteristicamente, o paciente apresenta fácies miastênica ou neurotóxica. As\npossíveis complicações são decorrentes da progressão da paralisia da face para músculos\nrespiratórios.","E":"A dor (instalação imediata em praticamente todos os casos) é o principal sintoma, podendo se\nirradiar para o membro e ser acompanhada de parestesia, eritema e sudorese local. Em geral, o\nquadro mais intenso de dor ocorre nas primeiras horas após o acidente. Após intervalo de minutos\naté poucas horas (duas a três) podem surgir, principalmente em crianças, os seguintes sintomas:\nsudorese profusa, agitação psicomotora, tremores, náuseas, vômitos, sialorreia, hipertensão ou\nhipotensão arterial, arritmia cardíaca, insuficiência cardíaca congestiva, edema pulmonar agudo e\nchoque."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-242089","number":"242089","sourceNumber":"242089","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Lactente de 18 meses foi trazido à emergência devido à ingestão de um frasco de\nsolução oral de medicamento antitérmico infantil. A conduta mais eficaz para prevenir este tipo de\nacidente é:","options":{"A":"Manter vigilância constante sobre a criança","B":"Manter produtos tóxicos em locais fora do alcance das crianças","C":"Comercializar medicamentos em recipientes com tampa de segurança","D":"Comercializar produtos tóxicos em frascos que não atraiam a atenção das crianças"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-255147","number":"255147","sourceNumber":"255147","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual o tratamento preconizado para um paciente vítima de acidente escorpiônico que\napresente somente quadro de dor leve local?","options":{"A":"Alívio da dor por infiltração de anestésico com vasoconstritor ou analgésico via oral.","B":"Sintomático, com infiltração de anestésico sem vasoconstritor, como lidocaína 2%, ou analgésico\nsistêmico, como dipirona 10mg/kg.","C":"Prescrição de soro antiescorpiônico 2-3 ampolas, independente do peso do paciente.","D":"Prescrição de 2 ampolas de soro antiescorpiônico associado a infiltração de lidocaína 2%.","E":"Prescrição de soro antiescorpiônico 4-6 ampolas independente do peso do paciente, infiltração\nde anestésico com vasoconstritor."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-242144","number":"242144","sourceNumber":"242144","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma jovem de 26 anos portadora de transtorno bipolar é trazida à emergência por\nfamiliares com quadro de hiperidrose,\nsialorreia, miose, hipersecreção brônquica, vômitos, cólicas e\ndiarréia e bradicardia. O plantonista suspeitou de intoxicação por carbamato e perguntou a família\nse alguém havia comprado recentemente algum raticida, sendo a resposta do pai da paciente\npositiva. Assinale a alternativa que contém o motivo pelo qual o plantonista suspeitou desse tipo de\nintoxicação e o tratamento recomendado para a mesma:","options":{"A":"Presença de sinais e sintomas colinérgicos/atropina.","B":"Presença de sinais e sintomas anticolinérgicos/atropina.","C":"Presença de sinais e sintomas colinérgicos/atropina e pralidoxima.","D":"Presença de sinais e sintomas anticolinérgicos/atropina e pralidoxima."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-252086","number":"252086","sourceNumber":"252086","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale a alternativa que contém a correta associação entre fármaco e seu antídoto,\nem caso de intoxicação:","options":{"A":"Zolpidem/flumazenil","B":"Buprenorfina/nalorfina","C":"Propranolol/glucagon","D":"Acetaminofeno/D-penicilamina"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-252091","number":"252091","sourceNumber":"252091","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente vítima de intoxicação exógena por amitriptilina apresentando midríase, boca\nseca, retenção urinária, taquicardia,\nhipotensão e sedação. Além do suporte clínico às vias aéreas\ne manutenção hemodinâmica, podemos usar como antídoto:","options":{"A":"Bicarbonato de sódio.","B":"Glucagon.","C":"N-acetilcisteína.","D":"Flumazenil."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-220485","number":"220485","sourceNumber":"220485","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem, vive em zona rural em cidade do cerrado mineiro e no mês de março é picado,\nno fim da tarde, por cobra não\nidentificada e não recuperada. Apresenta quadro clínico com a\npicada na perna direita, sem sinais inflamatórios ou edema local e pouca dor. As marcas são bem\nvisíveis e o paciente apresenta ptose palpebral bilateral, urina escura, mialgia e coagulograma\nalargado. Qual é a serpente que causou o quadro?","options":{"A":"Jiboia.","B":"Cascavel.","C":"Coral.","D":"Jararaca."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-208282","number":"208282","sourceNumber":"208282","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Correlacione corretamente os agentes de intoxicações agudas com seus respectivos\nantídotos: I. Veneno de rato cumarínico;\nII. Benzoadiazepínico; III. Opioides; IV. Antidiabéticos\norais; ( ) Flumazenil; ( ) Naloxone; ( ) Octreotida; ( ) Vitamina K. Assinale a alternativa que\ndemonstra a relação CORRETA entre elas","options":{"A":"(II), (III), (IV) e (I)","B":"(II), (IV), (III), e (I)","C":"(III), (I), (IV) e (II)","D":"(III), (II), (I) e (IV)"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-205137","number":"205137","sourceNumber":"205137","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual a droga de escolha para o tratamento da intoxicação por benzodiazepínicos?","options":{"A":"Naloxone.","B":"Atropina.","C":"Flumazenil.","D":"Piridoxina.","E":"Nitrato de sódio."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-219647","number":"219647","sourceNumber":"219647","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Face a taquicardia atrial com bloqueio, devido a intoxicação digitálica, em paciente com\ninsuficiência cardíaca importante, indica-se como primeira opção terapêutica:","options":{"A":"Cardioversao eltétrica.","B":"Gluconato de cálcio.","C":"Procaínamida.","D":"Quinidina.","E":"Fenitoina."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-214263","number":"214263","sourceNumber":"214263","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Nas intoxicações por benzodiazepínicos, o antídoto a ser utilizado é o(a):","options":{"A":"Insulina.","B":"Glucagon.","C":"Piridoxina.","D":"Flumazenil."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-217472","number":"217472","sourceNumber":"217472","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual o antídoto de escolha para anafilaxia por betabloqueador?","options":{"A":"Adrenalina","B":"N-acetilcisteína","C":"Terbutalina","D":"Glucagon"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-219694","number":"219694","sourceNumber":"219694","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale a alternativa correta que correlaciona o agente causal com as manifestações\nclínicas dos acidentes ofídicos: I-\nBotrópico; II- Laquético; III- Crotálico. 1. Manifestações\nneuroparalíticas com progressão crânio-caudal, iniciando-se por ptose palpebral, turvação visual e\noftalmoplegia. Progressivamente, surgem mialgia generalizada e escurecimento da cor da urina\n(cor de \"coca-cola\" ou \"chá preto\"). A insuficiência renal aguda é a principal complicação e causa\nde óbito. 2. As marcas de picada e sangramento nem sempre são visíveis nos pontos de introdução\ndas presas. Bolhas com conteúdo seroso ou sero-hemorrágico podem surgir e originar áreas de\nnecrose, que, juntamente com infecção secundária, constituem as principais complicações locais e\npodem levar à amputação e/ou deficit funcional do membro. Sangramentos em pele e mucosas são\ncomuns (gengivorragia, esquimoses a distância do local da picada); hematúria, hematêmese e\nhemorragia em outras cavidades. Hipotensão pode ser decorrente de sequestro de líquido no\nmembro picado ou hipovolemia consequente a sangramentos; 3. Presença de alterações vagais\n(náuseas, vômitos, cólicas abdominais, diarreia, hipotensão, choque).","options":{"A":"I-3; II-1; III-2","B":"I-2; II-1; III-3","C":"I-1; II-3; III-2","D":"I-3; II-2; III-1","E":"I-2; II-3; III-1"},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-184961","number":"184961","sourceNumber":"184961","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Algumas substâncias tóxicas possuem antídotos específicos. Estão corretamente\ncorrelacionados a substância tóxica e o antídoto específico em:","options":{"A":"opioides x nalmefeno","B":"metanol x octreotida","C":"anticolinérgicos x atropina","D":"anticolinesterásicos x fisostigmina"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-178141","number":"178141","sourceNumber":"178141","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mãe de um pré-escolar de 2 anos e três meses o leva à emergência por apresentar\nagitação psicomotora, midríase, boca seca e rubor\nfacial. Ela informa que observou tais sintomas\nhá uma hora, quando chegou à casa. O menor fica em casa com a prima de 9 anos no período da\nmanhã, até o retorno da mãe no horário do almoço. Provavelmente, trata-se de intoxicação por:","options":{"A":"Dipirona;","B":"Salbutamol;","C":"Paracetamol ;","D":"Clorpromazina;","E":"Dexclorfeniramina;"},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-180658","number":"180658","sourceNumber":"180658","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente cardiopata grave em uso de beta bloqueador, diurético de alça digital e IECA é\nadmitido na Unidade de Emergência do Hospital Casa de Portugal, com náuseas, vômitos, diarréia,\npalpitações, bradicardia e hipotensão arterial. Refere alteração do paladar e na percepção de cores\nECG evidencia BAVT. Qual a hipótese diagnostica?","options":{"A":"hiperpotassemia","B":"intoxicação digitálica","C":"gastroenterite aguda","D":"hipomagnesemia"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-180634","number":"180634","sourceNumber":"180634","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 35 anos proveniente do Sítio de seu avô em Vargem Grande onde refere\nque há mais ou menos 6 horas foi vítima de\nacidente com cobra venenosa filhote de jararaca\nidentificada por biólogo do instituto Butantan que é vizinho de seu avô. Chega ao Pronto - Socorro\ndo Hospital Casa de Portugal com feridas puntiformes em calcanhar, dor e edema até a parte\nproximal de perna direita. Você consulta a Infectologista de seu hospital que orienta as condutas\npara o caso:","options":{"A":"Alta com prescrição de repouso pois a cobra era filhote não há peçonha formada ainda","B":"Somente orienta vacinação anti-tetânica, antibióticos e repouso","C":"Somente internação para observação por 72h","D":"Solicita a enfermagem analgesia, exames laboratoriais hemograma bioquímica, enzimas\nmusculares, EAS, tempo de coagulação, TAP e\nPTT, EAS e PCR além de Medicação pré soro e\nSoro conforme a gravidade e solicita internação em unidade fechada"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-151452","number":"151452","sourceNumber":"151452","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Você foi chamado para avaliar um paciente de 35 anos em pós-operatório de fratura de\nfêmur após um acidente automobilístico. Ele vem recebendo paracetamol para controle álgico e\ndoses frequentes de morfina e apresentou quadro súbito de agitação, tremor, diaforese e\ndesorientação alopsíquica, mantendo orientação autopsíquica. Hemograma e bioquímica estão\nnormais e não há comorbidades relatadas em prontuário. Seu exame físico revela febre (39°C),\ntaquicardia (110 bpm). Pressão arterial de 180 x 90 mmHg e frequência respiratória de 18 irpm.\n\nPulmões limpos à ausculta pulmonar. Ferida operatória limpa. Qual o diagnóstico mais provável?","options":{"A":"Delirium induzido pela morfina.","B":"Embolia gordurosa.","C":"Abstinência ao álcool.","D":"Pneumonia.","E":"Infecção de sítio cirúrgico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-151109","number":"151109","sourceNumber":"151109","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação à cocaína e à anestesia geral, podemos afirmar que todas estão\nCORRETAS, EXCETO:","options":{"A":"Bloqueia a recaptação de catecolaminas, aumentando a estimulação de células receptoras.","B":"Tem efeito anestésico local, bloqueando os canais de sódio nas células neuronais, o que impede\na condução de impulsos nervosos.","C":"De forma aguda, pode estar associada à hipertermia, hipertensão arterial, taquicardia, midríase,\nestupor e depressão respiratória.","D":"No miócito cardíaco, reduz a velocidade de despolarização, a amplitude e a velocidade de\ncondução do potencial de ação, podendo causar\narritmias cardíacas.","E":"O uso isolado de antagonista beta-adrenérgico pode levar a menor agonismo alfa, com piora da\nhipertensão arterial."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-151448","number":"151448","sourceNumber":"151448","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Pré-escolar, 2 anos, chega a emergência com história súbita de perda da consciência e\nsalivação intensa. Mãe nega febre ou qualquer outro sintoma anterior. Ao exame, encontra-se\ncomatosa, com pupilas mióticas, bradicárdica, com aumento da peristalse e diarreia importante. O\nquadro é compatível com intoxicação exógena por qual substância?","options":{"A":"Anti-histamínico.","B":"Opioide.","C":"Etanol.","D":"Organofosforado.","E":"Salicilato."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-151451","number":"151451","sourceNumber":"151451","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual a droga de escolha na intoxicação por benzodiazepínicos?","options":{"A":"Naloxone.","B":"Dopamina.","C":"Atropina.","D":"N-acetilcisteína.","E":"Flumazenil."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-139869","number":"139869","sourceNumber":"139869","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Julia, 3 anos, é levada pelos pais ao Pronto Socorro em coma, pupilas mióticas e não\nreagentes, hipotonia generalizada, secreções orais e arreflexia. Poucas horas antes de ir ao pronto\nsocorro a criança tinha iniciado quadro de broncoespasmo, tosse, diarreia e sudorese. Para\nmanejar este quadro clínico, qual o medicamento mais indicado para ser prescrito:","options":{"A":"Edrofônio.","B":"Atropina.","C":"Adrenalina.","D":"Metilprednisolona."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-129588","number":"129588","sourceNumber":"129588","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma paciente de 30 anos portadora de doença psiquiátrica é levada à emergência com\nquadro de coma, taquicardia, hipotensão arterial, depressão respiratória e midríase. Realizado\neletrocardiograma que revelou taquicardia sinusal (112 bpm), BAV de 1º grau (PR2 200ms),\nbloqueio completo de ramo direito e bloqueio fascicular esquerdo anterossuperior, além de\nalterações secundárias da repolarização ventricular. Suspeitou-se de intoxicação exógena por\ntentativa de suicídio. Assinale a alternativa que contém a provável substância ingerida pela\npaciente e seu respectivo tratamento:","options":{"A":"Benzodiazepínico/flumazenil.","B":"Benzodiazepínico/naloxona.","C":"Antidepressivo tricíclico/bicarbonato de sódio.","D":"Antidepressivo tricíclico/gluconato de cálcio."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-137723","number":"137723","sourceNumber":"137723","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Adolescente, com história sugestiva de intoxicação exógena, chega à emergência\ninconsciente, com hipotonia, hipotensão e miose. O antídoto que deve ser utilizado é:","options":{"A":"Flumazenil.","B":"Naloxona.","C":"Atropina.","D":"EDTA.","E":"Adrenalina."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-137894","number":"137894","sourceNumber":"137894","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O Corpo de Bombeiros conduz à emergência dois primos de três e quatro anos de\nidade apresentando cianose intensa de mucosas e\nextremidades, ambos sem história prévia de\ndoença cardíaca. As crianças estavam brincando na casa da tia materna que fazia tratamento há\nanos de uma doença de pele. As evidências clínicas desta história induzem o médico a investigar:","options":{"A":"Cardiopatia congênita cianótica.","B":"Intoxicação exógena e meta-hemoglobinemia.","C":"Ingestão não controlada de azul de metileno.","D":"Dermatopatia genética com defeito da melanina.","E":"Efeito tardio de corantes utilizados em folguedos infantis."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-135862","number":"135862","sourceNumber":"135862","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Crianças são as principais vítimas de intoxicações exógenas acidentais em domicílio. O\nantídoto para intoxicação por paracetamol é:","options":{"A":"Diazóxido.","B":"Difenidramina.","C":"N-acetilcisteína.","D":"Bicarbonato de sódio."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-133511","number":"133511","sourceNumber":"133511","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança de três anos é levada ao pronto-socorro, 30 minutos após ela ingerir 30\ncomprimidos de sulfato ferroso. Apresentou vômitos após a ingestão. Neste caso, a conduta deve\nser:","options":{"A":"Lavagem gástrica com solução salina.","B":"Fazer endoscopia de urgência.","C":"Administrar eméticos.","D":"Administrar carvão ativado por sonda nasogástrica."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-110860","number":"110860","sourceNumber":"110860","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Com relação aos antídotos a serem utilizados para a intoxicação aguda, assinale a\nalternativa que apresenta a relação CORRETA entre agente tóxico-antídoto:","options":{"A":"Acetaminofeno ? naloxona.","B":"Opioide ? acetilcisteína.","C":"Benzodiazepínico ? fisostigmina.","D":"Betabloqueador ? glucagon.","E":"Isoniazida ? atropina."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-107070","number":"107070","sourceNumber":"107070","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Pré-escolar de três anos deu entrada no pronto-socorro apresentando cianose intensa\nde mucosas e extremidades. Não apresentava\ndificuldade respiratória, ausculta cardíaca sem\nanormalidades e sem história prévia de doença cardíaca. Estava recebendo oxigenoterapia quando\num primo de quatro anos deu entrada no mesmo hospital com quadro semelhante. Ambos haviam\npassado as últimas 12 horas na casa da avó materna, que fazia tratamento há anos de uma\ndoença de pele. As evidências clínicas desta história induzem o médico a investigar:","options":{"A":"Cardiopatia congênita cianótica.","B":"Ingestão não controlada de azul de metileno.","C":"Intoxicação exógena e metemoglobinemia.","D":"Efeito tardio de corantes utilizados em folguedos infantis."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-109871","number":"109871","sourceNumber":"109871","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Toxicômaco dá entrada na emergência com crise convulsiva. O médico que o atende\nsuspeita de intoxicação aguda por cocaína, porque há concomitantemente:","options":{"A":"Hiportemia e nistagmo.","B":"Arritmia cardíaca e nistagmo.","C":"Arritmia cardíaca e hipertemia.","D":"Hipotermia e hipertensão arterial.","E":"Hipotermia e hipotensão arterial."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-102558","number":"102558","sourceNumber":"102558","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A síndrome composta por salivação e sudorese intensas, bradicardia e miose é\nencontrada em intoxicações por:","options":{"A":"Inseticidas organofosforados.","B":"Inseticidas organoclorados.","C":"Inseticidas mercuriais.","D":"Solventes orgânicos dos inseticidas.","E":"Metanfetamina."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-104895","number":"104895","sourceNumber":"104895","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A síndrome do QT longo com taquicardia ventricular por torsades de pointes é\ncaracterística por intoxicação exógena por:","options":{"A":"Ibuprofeno.","B":"Cloranfenicol.","C":"Gasolina.","D":"Organofosforados.","E":"Paraquat."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-106215","number":"106215","sourceNumber":"106215","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O Centro de diagnóstico, prevenção e controle de doenças dos EUA (CDC), designou\ndiversos agentes biológicos na categoria A de\nacordo com a capacidade de serem utilizados como\narmas biológicas. Na categoria A estão inclusos os agentes que podem ser facilmente transmitidos,\nresultando em alta mortalidade, calamidade pública, e requerem um programa de preparo com\natenção especial da saúde pública. Todos os agentes abaixo podem ser considerados agentes\nbiológicos da categoria A EXCETO:","options":{"A":"Bacillusanthracis.","B":"Francisellatularensis.","C":"Toxina de rícino do Ricinuscommunis.","D":"Varicella.","E":"Yersiniapestis."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-107833","number":"107833","sourceNumber":"107833","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A conduta a ser tomada em um caso de ingestão acidental de gasolina em uma criança\nde 2 anos será:","options":{"A":"Provocar vômito, observar sinais de sangramento e observar sintomas extrapiramidais.","B":"Provocar vômito, monitorizar os sintomas respiratórios e observar sinais de depressão do\nsistema nervoso central.","C":"Provocar vômito, observar sinais de sangramento e observar sinais colinérgicos como salivação\ne lacrimejamento.","D":"Não provocar vômito, monitorizar os sintomas respiratórios e observar sinais de depressão do\nsistema nervoso central.","E":"Oferecer leite e observar a criança por 12 horas."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-110660","number":"110660","sourceNumber":"110660","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Os compostos organofosforados atuam por meio do bloqueio à acetilcolinesterase,\nlevando ao acúmulo de acetilcolina endógena.\nQual das alternativas abaixo melhor caracteriza um\nquadro de intoxicação colinérgica aguda?","options":{"A":"Miose, lacrimejamento, fasciculações e fraqueza muscular.","B":"Diarreia intensa, irritabilidade e demência.","C":"Midríase, demência e agressividade.","D":"Miose, depressão e diarreia intensa.","E":"Letargia, dificuldade de concentração e diarreia intensa."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-106167","number":"106167","sourceNumber":"106167","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A intoxicação exógena por entorpecentes provoca sinais e sintomas oculares\ncaracterísticos. Qual é a correlação CORRETA\nentre as drogas e sinais/sintomas oculares típicos?\n\n1. Ácido Lisérgico Dietilamida (LSD). 2. Etanol. 3. Cocaína. 4. Crack. 5. Cannabis. I. Nistagmo. II.\nHipotensão ocular. III. Midríase. IV. Úlceras de córnea. V. Neuropatia óptica.","options":{"A":"1 - I; 2 - II; 3 - III; 4 - IV; 5 - V.","B":"1 - II; 2 - IV; 3 - I; 4 - V; 5 - III.","C":"1 - III; 2 - I; 3 - V; 4 - IV; 5 - II.","D":"1 - IV; 2 - V; 3 - II; 4 - I; 5 - III.","E":"1 - V; 2 - IV; 3 - III; 4 - II; 5 - I."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-113002","number":"113002","sourceNumber":"113002","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um menino de 2 anos é encontrado pouco responsivo por sua babá. A criança foi\nencontrada no chão do lado de fora da casa, no jardim. A pele da criança está pálida, com\nsialorreia, bradicárdica, miótica, com incontinência urinária e apresenta dificuldade respiratória.\nO\npediatra de plantão revela que sentiu cheiro de alho na respiração da criança. Sendo assim,\nresponda a qual substância este menino foi exposto?","options":{"A":"Gasolina.","B":"Etilenoglicol.","C":"Cloro.","D":"Organofosforado."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-110495","number":"110495","sourceNumber":"110495","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Segundo estudo de \"Sangenis et al.\", o município de Valença concentra grande número\nde acidentes ofídicos por serpentes do gênero\nCrotalus. O acidente por este gênero de serpente se\ncaracteriza por:","options":{"A":"Apresentar manifestações inflamatórias no local da picada e alta incidência de reações\nhemorrágicas.","B":"Apresentar manifestações locais pouco evidentes e paralisia respiratória por mecanismo de\nbloqueio neuromuscular pós-sináptico.","C":"Provocar maior incidência de acidentes graves com fácies miastênica, mioglobinúria e necrose\ntubular aguda precoce.","D":"Provocar insuficiência respiratória precoce por bloqueio neuromuscular pré e pós-sináptico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-112646","number":"112646","sourceNumber":"112646","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação a acidentes por animais peçonhentos, podemos afirmar com EXCEÇÃO\nde:","options":{"A":"Em caso de acidentes por animais peçonhentos que necessitem utilização de soroterapia,\nrecomenda-se às equipes de assistência dos\npontos de atendimento, que a prescrição do soro\nseja respaldada por profissionais de referência (segundo opinião clínica), geralmente de Centros de\nInformações Toxicológicas (CITs).","B":"É necessário informar às equipes de assistência no atendimento aos acidentados por animais\npeçonhentos a necessidade do uso racional dos soros antivenenos, visando a correta utilização das\nampolas.","C":"Conforme o manual de diagnóstico e tratamento de acidentes por animais peçonhentos\npublicado pelo Ministério da Saúde, segundo\nestudo realizado, o gênero de serpentes mais\nenvolvidos nos acidentes é o Bothrops.","D":"Entre os locais mais frequentes de picada de serpentes destacam-se como maiores ocorrências\nas picadas em mãos e na face.","E":"Dentre os efeitos do acidente botrópico, podemos destacar a ação proteolítica do veneno."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-82790","number":"82790","sourceNumber":"82790","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente masculino jovem, com agitação psicomotora, agressividade e alucinações\nauditivas e visuais. Queixa-se também de\nfraqueza muscular difusa. Ao exame: temperatura de\n38°C; FC = 120 bpm; PA = 150 x 100 mmHg. A urina tem coloração de chá escuro, o EAS revela\nproteinúria sem hematúria. A pesquisa de cocaína na urina é positiva. O diagnóstico mais provável\npara o quadro clínico é:","options":{"A":"Rabdomiólise.","B":"Leptospirose.","C":"Nefropatia por IgA.","D":"Encefalopatia hepática."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-89386","number":"89386","sourceNumber":"89386","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Foi recentemente noticiado na imprensa mundial o uso do Gás Sarin como arma\nquímica de destruição em massa. Várias\nfontes estimaram de 322 a 1.729 mortes, em Ghouta,\ndurante a guerra civil na Síria em 21 de agosto de 2013. Descoberto em 1938, em Wuppertal\nElberfeld, na Alemanha, por cientistas da IG Farben que tentavam criar pesticidas mais fortes,\nsendo o Sarin o mais tóxico dos agentes neurotóxicos da época. O Sarin tem alta volatilidade\n(facilidade com que um líquido pode transformar-se em gás) relativamente semelhante a outros\nagentes do sistema nervoso, portanto, não só sua inalação pode ser muito perigosa, como até\nconcentrações de seu vapor podem penetrar a pele de imediato. As roupas de uma pessoa podem\nliberar Sarin em cerca de 30 minutos depois de terem entrado em contato com o gás, o que pode\nlevar à exposição de outras pessoas. Mesmo em concentrações muito baixas, o Sarin pode ser\nfatal. A morte pode seguir cerca de um minuto após a ingestão direta de uma dose letal, se seu\nantídoto não for administrado. A intoxicação aguda pelo Sarin causa sialorreia intensa,\nlacrimejamento, diurese, diaforese, diarreia e vômitos. Outros sintomas clínicos mais importantes\ncomo broncorreia (edema pulmonar), bradicardia, broncoespasmo, fraqueza e fasciculações\nmusculares e convulsões também fazem parte desta síndrome. Marque outro possível agente\ncausador da síndrome descrita acima e seu respectivo antídoto:","options":{"A":"Fluoxetina / fisostigmina.","B":"Carbamato / atropina.","C":"Cocaína / diazepam.","D":"Acetaminofeno / acetilcisteína."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-89768","number":"89768","sourceNumber":"89768","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em uma criança de 3 anos com quadro clínico de hipertensão, taquicardia, hipertermia,\nsede, rubor, midríase, pele e mucosas secas,\ndeve-se suspeitar de intoxicação por:","options":{"A":"Álcool.","B":"Benzodiazepínicos.","C":"Salicilatos.","D":"Barbitúricos.","E":"Anti-histamínicos."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-82911","number":"82911","sourceNumber":"82911","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Na intoxicação pelo chumbo, observa-se que:","options":{"A":"os efeitos tóxicos manifestam-se sobretudo nos sistemas gastrointestinal, hematopoiético,\nnervoso (central e periférico) e renal.","B":"não há associação clara entre os níveis de chumbo no sangue e a presença de sintomas.","C":"a forma de intoxicação mais comum é a crônica.","D":"a anemia é geralmente macrocítica."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-82895","number":"82895","sourceNumber":"82895","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A família traz Manoel à unidade de atenção primária. Manoel tem 35 anos de idade e\nvem acompanhado pelo médico da família e pelo\npsiquiatra por apresentar transtorno afetivo\nbipolar. Nos últimos meses, Manoel estava numa fase depressiva. Hoje de manhã, os familiares o\nencontraram no leito, sonolento, e com uma caixa de diazepam vazia sobre ele. Não sabem dizer\nhá quanto tempo Manoel está nessa situação. Chegou à unidade com escore de 10 na escala de\nGlasgow. A conduta CORRETA é:","options":{"A":"Iniciar lavagem gástrica com soro fisiológico 2-3 litros, enviar para casa e explicar para a\nfamília\nque os efeitos da medicação passarão nas próximas horas.","B":"Providenciar serviço de remoção para seu encaminhamento ao serviço de emergência e iniciar\nlavagem gástrica com soro fisiológico.","C":"Iniciar lavagem gástrica com carvão ativado e encaminhar ao serviço de emergência mais\npróximo da unidade.","D":"Encaminhar ao serviço de emergência mais próximo, já que pouco se pode fazer na unidade."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-84317","number":"84317","sourceNumber":"84317","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O EDTA cálcio é indicado como antídoto na intoxicação exógena por:","options":{"A":"paracetamol.","B":"benzodiazepínicos.","C":"metais pesados.","D":"digitálicos.","E":"opiáceos."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-86968","number":"86968","sourceNumber":"86968","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"As serpentes são as principais causadoras de acidentes por animais peçonhentos no\nBrasil. Dentre as opções abaixo, qual apresenta somente espécies peçonhentas, comumente\nencontradas no Brasil?","options":{"A":"Bothrops jararaca e Boa constrictor.","B":"Corallus caninus e Crotalus durissus.","C":"Eunectes murinus e jararacussu.","D":"Corallus caninus e Bothrops jararaca.","E":"Bothrops jararaca e jararacussu."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-87214","number":"87214","sourceNumber":"87214","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente com acidose metabólica, ânion gap reduzido, aumento no gap osmolar\ntem provável intoxicação por qual substância?","options":{"A":"Lítio.","B":"Metanol.","C":"Codeína.","D":"Propileno glicol."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-74791","number":"74791","sourceNumber":"74791","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"No recente incêndio ocorrido em boate na região Sul do país, o cianeto liberado pela\ncombustão de espuma sintética, inadequadamente empregada como isolante acústico, espalhou-se\nno ar ambiente e intoxicou centenas de jovens. Em pessoas inconscientes, a intoxicação requer\natendimento médico sem delonga que, dentre outras medidas terapêuticas específicas, inclui o\nemprego venoso de:","options":{"A":"Tiossulfato de sódio.","B":"Sulfanilamida.","C":"Dimercaprol.","D":"Pralidoxima."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-62337","number":"62337","sourceNumber":"62337","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O avanço tecnológico e a miniaturização dos videogames fizeram aumentar a\nincidência de acidentes com deglutição de corpo\nestranho. A ingestão de baterias esféricas deve\nser tratada com:","options":{"A":"Lavagem gástrica.","B":"Administração de carvão ativado.","C":"Endoscopia.","D":"Antiácidos.","E":"Benzodiazepínico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-69497","number":"69497","sourceNumber":"69497","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Celultites resultantes de infecção complicando mordeduras de cães e gatos devem ser\npreferencialmente tratadas com:","options":{"A":"cefalexina.","B":"amoxicilina + clavulanato.","C":"trimetoprim + sulfametoxazol.","D":"azitromicina."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-44136","number":"44136","sourceNumber":"44136","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um jovem dá entrada no pronto-socorro com história de precordialgia típica, após, em\numa festa, ter feito uso de cocaína. Qual das\nopções abaixo NÃO estaria indicada?","options":{"A":"Ácido acetilsalicílico.","B":"Nitrato sublingual.","C":"Betabloqueadores.","D":"Antagonista dos canais de cálcio não di-hidropiridínicos.","E":"Clopidogrel."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-49860","number":"49860","sourceNumber":"49860","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Sobre a ingestão de substâncias potencialmente tóxicas, evento frequente em crianças\ne adolescentes, pode-se dizer que:","options":{"A":"A administração de carvão ativado deve, preferencialmente, ser feita até uma hora após a\ningestão de um produto potencialmente tóxico.","B":"A indução de vômitos com xarope de ipeca é um procedimento de primeira escolha nos casos de\ningestão de um produto potencialmente tóxico, por sua comprovada eficácia.","C":"A lavagem gástrica deve ser considerada rotineiramente em casos de intoxicações agudas,\nsendo esse o método de escolha quando a\ningestão da substância ocorreu há mais de quatro\nhoras.","D":"O uso de catárticos ajuda a aumentar o tempo de trânsito de agentes tóxicos no trato\ngastrointestinal, potencializando o efeito benéfico constipante do carvão ativado."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-37839","number":"37839","sourceNumber":"37839","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente dá entrada no Serviço de Emergência alegando ter sido agredido por um\nofídio. Queixa-se de dor no local atingido (face lateral do pé esquerdo), onde há edema e calor\nlocal. Há adenopatia inguinal e lesões equimóticas ao longo da perna. O tempo de coagulação é\nmaior que 25 minutos. O soro necessário é o:","options":{"A":"Antielapídico.","B":"Anticrotálico.","C":"Antibotrópico.","D":"Antiloxoscélico.","E":"Antimicrúrico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-31674","number":"31674","sourceNumber":"31674","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menina de dois anos e seis meses reside em uma comunidade, na periferia do Rio de\nJaneiro. Brincava sozinha com caixa de medicamentos e, logo depois, apresentou-se taquipneica,\nsudoreica e sonolenta. Ao exame, a criança encontrava-se torporosa, desidratada, frequência\nrespiratória: 32 incursões respiratórias por minuto, sendo as incursões rápidas e profundas.\n\nFrequência cardíaca: 128 batimentos por minuto, pressão arterial dentro dos limites da\nnormalidade, Tax. 37.8ºC. A gasometria arterial\nrevelava: pH - 7,20/PaO2 - 98/pCO2 - 24/BE -\n2/HCO3 - 15/SAT - 96%. A hipótese diagnóstica mais provável é intoxicação exógena por:","options":{"A":"Salicilato.","B":"Digitálico.","C":"Neuroléptico.","D":"Anti-hipertensivos."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-36300","number":"36300","sourceNumber":"36300","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente masculino, 40 anos, dá entrada no setor de urgência com quadro de icterícia,\nconfusão mental e hemorragia digestiva alta após overdose por acetaminofeno. Qual dos seguintes\nparâmetros é indicativo de transplante hepático neste paciente?","options":{"A":"pH > 7,30.","B":"INR > 6,5.","C":"Creatinina sérica > 3,4 mg/dl.","D":"Bilirrubina total > 10."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-7938","number":"7938","sourceNumber":"7938","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um distúrbio de ritmo, comum na intoxicação digitálica é a(o):","options":{"A":"onda P.","B":"ritmo sinusal.","C":"taquicardia atrial.","D":"fibrilação atrial.","E":"extrassístole ventricular."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-58631","number":"58631","sourceNumber":"58631","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente masculino de 78 anos, portador de diabetes melito, hipertensão arterial e\ntranstorno afetivo bipolar, deu entrada no\npronto-socorro após episódio de síncope. Apresentava\nFC = 38 bpm e PA = 74 x 36 mmHg ao exame físico. Encontrava-se sonolento, confuso, febril,\nsecretivo e com hiperglicemia. Foi internado na UTI e evoluiu com insuficiência renal aguda,\nnecessitando de terapia dialítica. O paciente fazia uso previamente de insulina glargina 30 UI/dia e\nLispro 04 UI nas refeições, losartan 50 mg 2x/dia, citalopram 20 mg/dia e carbonato de lítio 300 mg\n3x/dia. Com base no caso acima, é CORRETO afirmar:","options":{"A":"A associação do lítio ao losartan aumenta drasticamente os níveis de potássio, o que concorreu\npara a bradicardia sintomática do\npaciente.","B":"A associação de lítio ao citalopram foi responsável pelo quadro de síncope, pela elevação da\nglicemia e pela alteração do estado mental.","C":"Esse paciente apresentou piora da função renal devido, provavelmente, à acidose metabólica e\nà hipocalcemia aguda relacionadas ao lítio e ao\nseu potencial dano tubulointersticial.","D":"Esse paciente, devido à cardiotoxidade provocada pelo lítio (disfunção do nó sinusal),\nnecessitará de marca-passo provisório até a depuração desse fármaco pela diálise."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-7079","number":"7079","sourceNumber":"7079","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Relacione a coluna da direita com a da esquerda, considerando as drogas e os\nrespectivos mecanismos de ação. (VER IMAGEM) A opção em que todas as correlações estão\ncorretas é:","options":{"A":"1d, 2b, 3a, 4c.","B":"1c, 2b, 3d, 4a.","C":"1d, 2c, 3b, 4a.","D":"1b, 2c, 3a, 4d."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-344012","number":"344012","sourceNumber":"344012","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mãe comparece a UBS referindo que o filho de 2 anos ingeriu alguns comprimidos de\nparacetamol há 30 min. Você:","options":{"A":"Encaminha para o pronto socorro pelo risco de hepatotoxicidade","B":"Encaminha para o pronto socorro pelo risco de coma","C":"Encaminha para o pronto socorro pelo risco de hemólise maciça","D":"Encaminha para o pronto socorro pelo risco de depressão respiratória."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-341893","number":"341893","sourceNumber":"341893","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em caso de acidente ofídico, o tempo até o início dos sintomas e para a apresentação\nclínica é muito variável, dependendo da\nespécie envolvida, da localização da picada e da\nquantidade de veneno inoculada na vítima. Uma das complicações potenciais locais é a necrose\ndos tecidos, sobretudo agravada pelo garrote. Este tipo de complicação está relacionado sobretudo\ncom o veneno de ação:","options":{"A":"Quelante","B":"Neurotóxico","C":"Hemorrágico","D":"Proteolítico","E":"Coagulante"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-312427","number":"312427","sourceNumber":"312427","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em caso de acidente ofídico, o tempo até o início dos sintomas e para a apresentação\nclínica é muito variável, dependendo da\nespécie envolvida, da localização da picada e da\nquantidade de veneno inoculada na vítima. Uma das complicações potenciais locais é a necrose\ndos tecidos, sobretudo agravada pelo garrote. Este tipo de complicação está relacionado sobretudo\ncom o veneno de ação:","options":{"A":"Hemorrágico","B":"Quelante","C":"Proteolítico","D":"Neurotóxico"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-312439","number":"312439","sourceNumber":"312439","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança com 7 anos de idade, moradora de zona rural, relata acidente por animal\ndesconhecido há 4 horas. No momento, refere formigamento no local da picada, boca seca,\ndiplopia, dificuldade de deglutição, dores musculares generalizadas, oligúria e urina com coloração\nvermelha escura. Ao exame físico, apresenta ptose palpebral bilateral e midríase. O resultado do\nexame de urina rotina evidenciou mioglobinúria. Exames de sangue ainda em processamento. Com\nbase nesses dados, qual a soroterapia especifica indicada ao quadro?","options":{"A":"Soro anti-botrópico.","B":"Soro anti-escorpiônico.","C":"Soro anti-crotálico.","D":"Soro anti-elapídico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-315283","number":"315283","sourceNumber":"315283","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente é atendido em pronto-socorro com os seguintes sinais e sintomas:\nformigamento boca e língua, náuseas, vômitos e\nhipotensão arterial, fasciculação muscular e ptose\npalpebral. Dentre os animais peçonhentos relacionados, qual apresenta maior compatibilidade com\no caso?","options":{"A":"Aranha marrom","B":"Escorpião","C":"Cascavel","D":"Aranha caranguejeira"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-279797","number":"279797","sourceNumber":"279797","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Considere as assertivas abaixo em relação às intoxicações exógenas. I - Salvo poucas\nexceções, administração de carvão ativado isoladamente é a intervenção adequada em caso de\nintoxicação por ingestão de medicamentos. II - Lavagem gástrica está contraindicada em caso de\ningestão de substâncias cáusticas. III - Xarope de Ipeca (para induzir vômitos) está indicado para\npacientes que apresentam piora progressiva de sensório. Quais as CORRETAS?","options":{"A":"Apenas I","B":"Apenas II","C":"Apenas I e II","D":"I, II e III"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-280784","number":"280784","sourceNumber":"280784","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Analise o conjunto de manifestações relacionadas à intoxicação ou efeitos adversos de\nalgumas substâncias/medicamentos. Em seguida, marque a alternativa que relaciona\nCORRETAMENTE cada uma das substâncias ao conjunto de manifestações correspondentes: I.\nSudorese profusa, sialorreia, hipersecreção brônquica; miose e bradicardia. II. Euforia, hipertensão\narterial, taquicardia e midríase. III. Mucosas secas, hiper-reflexia tendinosa, agitação\npsicomotora e\nhipertermia. IV. Náuseas, tremores de extremidades, polidipsia, poliúria e disfunção renal.","options":{"A":"I ? Organofosforado; II ? Haloperidol; III ? Lítio; IV ? Fluoxetina.","B":"I ? Cocaína; II ? Fluoxetina; III ? Haloperidol; IV ? Lítio.","C":"I ? Carbamato; II ? Tricíclico; III ? Lítio; IV ? Fluoxetina.","D":"I ? Carbamato; II ? Cocaína; III ? Fluoxetina; IV ? Lítio."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-133120","number":"133120","sourceNumber":"133120","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um jovem dá entrada no pronto-socorro com história de precordialgia típica, após, em\numa festa ter feito uso de cocaína. Qual das\ndrogas abaixo não estaria indicada?","options":{"A":"Betabloqueador.","B":"Ácido acetilsalicílico.","C":"Antagonista dos canais de cálcio não diidropiridínicos.","D":"Clopidogrel.","E":"Furosemida."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-104127","number":"104127","sourceNumber":"104127","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Você atende no pronto-socorro paciente de 78 anos com edema agudo pulmonar. Há\nhistória de hipertensão arterial há 20 anos e hipertrofia do ventrículo esquerdo. Você administra as\nseguintes drogas por via endovenosa: 1- furosemida 40 mg; 2- morfina 10 mg; 3- aminofilina 240\nmg; 4- cedilanida 0,4 mg. A paciente evolui com hipoventilação grave e cianose. Para reverter a\ndepressão respiratória, indica-se o uso de:","options":{"A":"Efedrina.","B":"Flumazenil.","C":"Naloxona.","D":"Cloreto de edrofônio."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-104162","number":"104162","sourceNumber":"104162","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente é trazido ao hospital inconsciente, bradicárdico, miótico, com história de\nvômitos e diarreia. Após intubação,\npercebe-se muita secreção pulmonar e sialorréia. A hipótese é\nde intoxicação por:","options":{"A":"Organofosforados.","B":"Digitálicos.","C":"Opióides e benzodiazepínicos.","D":"Lítio."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-259498","number":"259498","sourceNumber":"259498","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente com 14 anos estava fazendo uma trilha em local de mata nativa e foi picado\nno tornozelo direito. Apresentou imediata e\nsignificativa dor local, com edema que rapidamente\nprogrediu pela perna e, após 1 hora, atingiu a coxa, dificultando a deambulação. Apresentou\nequimoses e pequenas bolhas de conteúdo seroso no local da picada e não foi observada qualquer\nmanifestação neurológica. Essa apresentação clínica caracteriza um acidente:","options":{"A":"Botrópico.","B":"Elapídico.","C":"Loxoscélico.","D":"Escorpiônico."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-229612","number":"229612","sourceNumber":"229612","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Recém-nascido apresenta sintomas compatíveis com dependência devido ao uso de\nsubstâncias tóxicas pela mãe. A investigação pode ser complementada com um exame toxicológico\nde urina da mãe. Diante desse quadro, assinale a assertiva CORRETA.","options":{"A":"A cocaína costuma permanecer na urina por até 3 dias após o último episódio de uso.","B":"Medicamentos administrados durante o parto não interferem na interpretação dos resultados do\nexame de urina.","C":"A maconha é muito rapidamente metabolizada e costuma desaparecer da urina em até 24 horas\napós o último episódio de uso.","D":"A maconha e a cocaína, devido ao rápido metabolismo de primeira passagem, não são\ndetectáveis na urina.","E":"Um resultado negativo do exame de urina é suficiente para descartar o uso de qualquer\nsubstância."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-255532","number":"255532","sourceNumber":"255532","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"São pares adequados, substância e antídoto, para o tratamento das intoxicações: I.\nOpiáceos e naloxona. II. Benzodiazepínicos e flumazenil. III. Ferro e deferoxamina. IV. Metanol e\netanol. Quais estão corretos?","options":{"A":"Apenas I e II.","B":"Apenas II e III.","C":"Apenas I, II e III.","D":"I, II, III e IV."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-255533","number":"255533","sourceNumber":"255533","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Os critérios diagnósticos para intoxicação por álcool são baseados em evidências de\ningestão recente de etanol, comportamento desadaptativo e alguns correlatos fisiológicos. NÃO é\num sinal de intoxicação por álcool:","options":{"A":"Alucinações visuais.","B":"Nistagmo.","C":"Visão dupla.","D":"Fala arrastada."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-140266","number":"140266","sourceNumber":"140266","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A medida do nível plasmático de qual dos agentes listados abaixo NÃO está indicada\npara o manejo adequado da intoxicação?","options":{"A":"Acetaminofeno.","B":"Fenobarbital.","C":"Lítio.","D":"Ferro.","E":"Atropina."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-140343","number":"140343","sourceNumber":"140343","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Acetaminofen é um analgésico e antitérmico amplamente utilizado na faixa etária\npediátrica. Qual é o antídoto que deve ser empregado nos casos de intoxicação?","options":{"A":"Naloxone.","B":"Prostigmine.","C":"N-acetilcisteína.\n\n.","D":"Sulfato de atropina.","E":"Flumazenil."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-60379","number":"60379","sourceNumber":"60379","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menina de 4 anos foi trazida à emergência com história de hipertonia, trismo e\nopistótono de início súbito. Na admissão,\nencontrava-se acordada, consciente e chorosa. Qual o\nagente tóxico mais provável?","options":{"A":"Opiáceo.","B":"Fenotiazínico.","C":"Barbitúrico.","D":"Antidepressivo tricíclico.","E":"Benzodiazepínico."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-33162","number":"33162","sourceNumber":"33162","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Associe as medidas terapêuticas propostas às respectivas substâncias tóxicas. 1 -\n\nN-acetilcisteína. 2 - Hemodiálise/hemoperfusão. 3 - Desferroxamina. 4 - Teofilina. 5 - Naloxona. ( )\nFerro. ( ) Acetaminofeno. ( ) Salicilatos. A sequência numérica correta, de cima para baixo, é:","options":{"A":"1 - 2 - 4.","B":"1 - 5 - 2.","C":"3 - 1 - 2.","D":"3 - 2 - 1.","E":"5 - 1 - 4."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-7913","number":"7913","sourceNumber":"7913","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação ao uso de substâncias psicoativas, qual a alternativa correta?","options":{"A":"O ?pulmão de crack? assemelha-se, clinicamente, ao quadro de pneumonia grave, podendo\nevoluir para o óbito.","B":"A cocaína provoca alterações das funções mentais após 10 minutos de seu uso,\nindependentemente da via ser sob forma de pó, injetada ou fumada.","C":"O crack tem ação semelhante à das anfetaminas, sendo ambas as substâncias sintéticas\ndisseminadas no Brasil.","D":"O uso do crack causa danos agudos e crônicos ao organismo, sendo o sistema reprodutivo, o\ncérebro e os pulmões os mais atingidos, sendo mínimas as alterações cardiovasculares.","E":"O uso da cocaína, durante a gestação, provoca retardo do desenvolvimento fetal, malformações\ncardiovasculares e glaucoma congênito."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-272754","number":"272754","sourceNumber":"272754","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Adolescente, sexo feminino, 15 anos, com história de tentativa de suicídio, chega à\nemergência trazida por amigos devido a estado mental alterado. Está sonolenta, mas responde a\nestímulos verbais, com sinais vitais normais, exceto por taquicardia. Exames laboratoriais: AST =\n\n10.500 UI/L, ALT = 9.800 UI/L, RNI = 1.1 e bilirrubina total de 3.5 mg/dl. A causa mais plausível\npara este caso é que seja uma ingesta\nexcessiva de e a terapêutica indicada é\n\n. As informações que completam CORRETAMENTE as lacunas, na ordem em\nque se encontram, estão contidas na\nalternativa:","options":{"A":"Alprazolam ? lavagem gástrica.","B":"Ácido acetilsalicílico ? lavagem gástrica.","C":"Álcool metílico ? N-acetilcisteína endovenosa.","D":"Acetaminofeno ? N-acetilcisteína endovenosa."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-179612","number":"179612","sourceNumber":"179612","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"O New England Journal of Medicine de 21/11/2017, traz uma publicação que é\nintroduzida da seguinte maneira: ? Mortes\npor overdose de opióides tem aumentado\nconsideravelmente nos últimos 15 anos nos EUA, com mais de 33.000 mortes desse tipo relatadas\nem 2015?. Diante da ?crise dos opióides?, a American Heart Association (AHA) incluiu nas\nDiretrizes Atualizadas de Atendimento de Parada Cardiorrespiratória em 2015, a administração de\nnaloxone em casos de parada respiratória, inclusive por por socorristas leigos. Qual a função desta\ndroga?","options":{"A":"Agonista parcial","B":"Agonista puro","C":"Agonista-antagonista","D":"Antagonista","E":"Nenhuma das anteriores"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-141204","number":"141204","sourceNumber":"141204","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Acetaminofen é um analgésico e antitérmico amplamente utilizado na faixa etária\npediátrica. Qual é o antídoto que deve ser empregado nos casos de intoxicação?","options":{"A":"Naloxone.","B":"Prostigmine.","C":"N-acetil-cisteína.","D":"Sulfato de atropina.","E":"Flumazenil."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-106473","number":"106473","sourceNumber":"106473","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A maioria dos casos envolvendo crianças costuma evoluir de forma benigna, mas\ncertos agentes e circunstâncias podem produzir\nintoxicações graves e, mais raramente, óbito.\nAssinale a alternativa que NÃO apresenta um agente causador dessas intoxicações em crianças:","options":{"A":"Acetaminofeno: a partir de 140 mg/kg.","B":"Antidepressivos tricíclicos: a partir de 5 mg/kg.","C":"Sulfonilureias: 1 comprimido.","D":"Ferro elementar: acima de 5 mg/kg.","E":"Descongestionante nasal tópico (nafazolina): 2,5 ml."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-87704","number":"87704","sourceNumber":"87704","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Chega à emergência do pronto-socorro, com história de precordialgia típica após ter\nfeito uso de cocaína em uma festa, um\nindivíduo de 26 anos. Qual das opções a seguir NÃO seria\nindicada?","options":{"A":"Ácido acetilsalicílico.","B":"Nitrato sublingual.","C":"Betabloqueadores.","D":"Antagonista dos canais de cálcio não di-hidropiridínicos.","E":"Clopidogrel."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-83641","number":"83641","sourceNumber":"83641","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"No paciente com alteração do estado mental, o diâmetro pupilar pode ser útil no\ndiagnóstico diferencial. Correlacione o diâmetro\npupilar e o tipo de lesão correspondente: 1. Pupilas\nmióticas; 2. Pupilas midriáticas; 3. Pupilas medianas. ( ) Intoxicação por cogumelos; ( ) Hemorragia\npontina; ( ) Encefalopatia metabólica; ( ) Intoxicação por marijuana; ( ) Intoxicação alcoólica.","options":{"A":"1 - 1 - 3 - 1 - 2.","B":"2 - 3 - 2 - 2 - 1.","C":"2 - 1 - 3 - 2 - 1.","D":"1 - 2 - 1 - 3 - 1.","E":"1 - 2 - 3 - 2 - 2."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-65427","number":"65427","sourceNumber":"65427","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Considere as afirmativas abaixo sobre procedimentos em acidentes escorpiônicos: I.\nLimpar o local com água e sabão e aplicar compressa morna no local. II. Não aplicar nenhum tipo\nde substâncias sobre o local da picada (fezes, álcool, querosene, fumo, ervas, urina) nem fazer\ncurativos que fechem o local. III. Se for possível, capturar o animal e levá-lo ao serviço de saúde.\nQuais estão corretas?","options":{"A":"Apenas I.","B":"Apenas I e II.","C":"Apenas I e III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-48072","number":"48072","sourceNumber":"48072","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual das drogas abaixo pode produzir edema pulmonar não cardiogênico?","options":{"A":"Cocaína.","B":"Crack.","C":"Cannabis sativa.","D":"Ecstasy.","E":"Heroína."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-48121","number":"48121","sourceNumber":"48121","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Mulher de 72 anos, com ansiedade de longa data, tratada com diazepam, decide\ntriplicar a dose de sua medicação em\ndecorrência de um medo crescente de ?ruídos ambientais?.\nVários dias depois, uma vizinha a encontra totalmente letárgica e irresponsiva. O exame mostra\nestado torporoso, pouca sensibilidade à dor e reflexos diminuídos. Frequência respiratória de 8\nirpm, com respiração superficial. Qual das medicações abaixo poderia ser ministrada para tentar\nreverter o quadro?","options":{"A":"Naltrexona.","B":"Fisostigmina.","C":"Pralidoxima.","D":"Flumazenil.","E":"Naloxona."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-35480","number":"35480","sourceNumber":"35480","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 5 anos, é admitido no Pronto-Socorro com história de dor intensa no pé direito,\nagitação psicomotora, sudorese profusa e vômitos incoercíveis, após ter sido picado por animal não\nidentificado no dorso do pé direito há uma hora. Ao exame físico: FC = 180 bpm, FR = 60 mrpm,\nsudorese generalizada, palidez cutânea, perfusão periférica lentificada, presença de B3 audível em\nfoco mitral e estertores crepitantes nas bases. Trata-se, possivelmente, de acidente:","options":{"A":"Por Lonomia spp.","B":"Escorpiônico.","C":"Por Lycosa spp.","D":"Elapídico.","E":"Por Loxosceles spp."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-8037","number":"8037","sourceNumber":"8037","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Criança de 2 anos é trazida para a Emergência. Está comatosa, bradicárdica,\nbradipneica, hipotensa, hipotérmica e com\nhiporreflexia. Familiares informam que até há 3 horas\nestava normal. Foi encontrada no quarto dos avós juntamente com um frasco vazio de remédios há\ncerca de 2 horas. Os mesmos fazem uso regular de diazepínicos, de antiparkinsonianos e de\nteofilina. Em relação a esta situação, são apresentadas as seguintes assertivas: I. A descrição da\nsíndrome relaciona-se com possibilidade de intoxicação exógena por antiparkinsonianos. II. A\nindução de vômito com xarope de ipeca deve ser realizada nesta criança. III. Está indicado o uso\nde carvão ativado neste caso. Qual é a alternativa correta?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e III.","E":"I, II e III."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-8057","number":"8057","sourceNumber":"8057","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual a afirmativa correta em relação à conduta referente ao tratamento de um paciente\ndependente de cocaína em uma unidade de atenção primária?","options":{"A":"A primeira escolha de tratamento farmacológico é a olazapina.","B":"O enfoque terapêutico mais eficaz é o que associa prevenção à recaída com tratamento\nfarmacológico de eventuais co-morbidades.","C":"A entrevista motivacional é a intervenção mais eficaz para pacientes com baixa capacidade de\naderência ao tratamento disponibilizado.","D":"O aprendizado de estratégias para o reconhecimento das situações que levam à recaída é o\nenfoque mais eficaz para pacientes com danos cerebrais provocados pela droga.","E":"Devido à gravidade da dependência que a droga promove, o único tratamento eficaz é o da\nredução de danos, mediante encaminhamento a internação especializada, para manutenção em\nprograma terapêutico."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-250509","number":"250509","sourceNumber":"250509","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"As manifestações clínicas observadas nas intoxicações com inibidores da colinesterase\ndependem do mecanismo de ação, sendo correto o item:","options":{"A":"Também da intensidade com a qual os diversos receptores colinérgicos, presentes em diferentes\nórgãos e tecidos, são estimulados.","B":"Independente da intensidade com a qual os diversos receptores colinérgicos, presentes em\ndiferentes órgãos e tecidos, são estimulados.","C":"Também da intensidade com a qual os diversos receptores anticolinérgicos, presentes em\ndiferentes órgãos e tecidos, são estimulados.","D":"Também da intensidade com a qual os diversos receptores colinérgicos, presentes em diferentes\nórgãos e tecidos, são inibidos."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-179946","number":"179946","sourceNumber":"179946","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Criança de 8 anos é trazida do interior do Estado por ter sido vítima de acidente\nofídico.\nDentre os itens abaixo, qual destas deve ser a sua primeira conduta:","options":{"A":"iniciar a soroterapia","B":"iniciar a hidratação vigorosa do paciente","C":"iniciar a medicação pré-soro","D":"aplicar vacina antitetânica"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-108965","number":"108965","sourceNumber":"108965","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Assinale a alternativa INCORRETA quanto à abordagem de paciente com suspeita de\nintoxicação exógena.","options":{"A":"Diante de qualquer paciente com suspeita de intoxicação exógena, a prioridade é manter as vias\naéreas prévias , de modo que se o paciente tiver Glasgow = 8, a intubação orotraqueal é\nmandatória.","B":"É sensato administrar tiamina (vitamina BI) lOOmg IV antes de se administrar glicose ao\npaciente com rebaixamento do nível de consciência por hipoglicemia e que seja etilista crônico.","C":"Em caso de intoxicação por antidepressivos tricíclicos, o antídoto a ser utilizado é o\nflumazenil.","D":"A síndrome simpaticomimética é caracterizada, dentre outras manifestações, por hipertensão\narterial, palidez cutaneomucosa, midriase,\ndiaforese, convulsões, coma. Ocorre no caso de\nintoxicação por cocaína, anfetaminas e ecstasy.","E":"Na intoxicação por anti-histamínicos, tricíclicos e antipsicóticos, ocorre a chamada síndrome\nanticolinérgica, caracterizada por rubor facial, midriase, hipertermia, ressecamento de pele e\nmucosas, sonolência, convulsões e coma."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-84582","number":"84582","sourceNumber":"84582","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"No serviço de emergência, uma paciente com 25 anos é admitida com agitação\npsicomotora, alucinação, temperatura de 39°C, PA =\n250 x 150 mmHg e múltiplas extrassístoles\nventriculares. Não há historia prévia de qualquer patologia. O diagnóstico provável é intoxicação\npor:","options":{"A":"Maconha.","B":"Carbamato.","C":"Cocaína.","D":"Mercúrio.","E":"Álcool Etílico."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-84607","number":"84607","sourceNumber":"84607","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um homem de 25 anos de idade é trazido de ambulância após atendimento\n\npré-hospitalar de emergência em uma festa no 3º dia de carnaval. Ao exame: pulso = 140 bpm; FR\n\n= 32 bpm; PA = 180 x 120 mmHg; e temperatura = 39°C. Oximetria na ambulância entre 90 e 95%.\nAlém de uma convulsão tratada com diazepam, tinha pupilas dilatadas, sudorese e odor alcoólico.\nUm amigo que o acompanhava, relata que ele estava há 3 dias em Salvador \"brincando o\ncarnaval\". No pronto atendimento, os exames revelaram pH = 7,25; K = 2,7 mEq/L; creatinina = 3;\nureia = 220; PaCO2 = 40; HCO3 = 18; Na 125; cloro = 89; PO2 = 85 e CPK = 100.000 U. Frente ao\n\nquadro, o paciente recebeu fluidos, bicarbonato e melhorou acentuadamente. Metabólitos de\ncocaína negativa. Posteriormente, admitiu ter\nusado uma droga. O quadro ácido-básico,\nrabdomiólise, mioglobulinúria, desidratação, hipertensão e hipertermia sugerem que esse paciente\nusou:","options":{"A":"Ketamina.","B":"Inalantes voláteis (\"lança perfume\").","C":"MDMA (\"êxtase\").","D":"Anfetamina","E":"Tetraidrocanabiol."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-297340","number":"297340","sourceNumber":"297340","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 62 anos de idade é trazida pelos familiares ao serviço de emergência por\nter ingerido aproximadamente quarenta\ncomprimidos de amitriptilina 25 mg. A paciente\n\nencontrava-se agitada e confusa. Sobre intoxicação por substâncias com efeitos anticolinérgicos, é\ncorreto afirmar:","options":{"A":"Sialorreia é um achado comum.","B":"Alterações eletrocardiográficas são raras.","C":"Dosagem do nível sérico de colinesterase é mandatória.","D":"O uso de atropina está indicado em alguns casos.","E":"Exame físico abdominal com presença de globo vesical pode estar presente."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-258325","number":"258325","sourceNumber":"258325","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Avalie o conjunto de manifestações descrito abaixo: 1. Sudorese profusa, sialorreia,\nhipersecreção brônquica; miose e bradicardia. 2. Euforia, hipertensão arterial, taquicardia e\nmidríase. 3. Mucosas secas, hiper-reflexia tendinosa, agitação psicomotora e hipertermia. 4.\n\nNáuseas, tremores de extremidades, polidipsia, poliúria e disfunção renal. Assinale a alternativa\ncom a respectiva droga (ou classe\nfarmacológica) que se associa a cada conjunto de\nmanifestações acima.","options":{"A":"1. Cocaína; 2. Fluoxetina; 3. Haloperidol; 4. Lítio.","B":"1. Carbamato; 2. Tricíclico; 3. Lítio; 4. Fluoxetina.","C":"1. Carbamato; 2. Cocaína; 3. Fluoxetina; 4. Lítio.","D":"1. Fluoxetina; 2. Lítio; 3. Cocaína; 4. Haloperidol.","E":"1. Organofosforado; 2. Haloperidol; 3. Lítio; 4. Fluoxetina."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-227707","number":"227707","sourceNumber":"227707","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Intoxicações por diferentes substâncias apresentam em comum a necessidade do\nmanejo da via aérea. Assinale a alternativa com a substância(s) que acarrete(m) o maior risco de\nhipoxemia durante a intubação orotraqueal.","options":{"A":"Lítio","B":"Tricíclicos","C":"Antiepilépticos","D":"Organofosforados","E":"Benzodiazepínicos"},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-200096","number":"200096","sourceNumber":"200096","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Com respeito às intoxicações por organofosforado e carbamato, assinale a alternativa\nCORRETA.","options":{"A":"O sistema nervoso central não é comprometido.","B":"A administração de atropina deve ser suspensa somente após o paciente evoluir com midríase.","C":"A hipersecreção brônquica pode causar insuficiência respiratória aguda.","D":"Sudorese profusa é uma manifestação específica da intoxicação por organofosforado.","E":"A medida seriada do diâmetro pupilar é um método acurado para monitorar a resposta\nterapêutica."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-149306","number":"149306","sourceNumber":"149306","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menina de 3 anos deu entrada na emergência pediátrica com salivação, disfagia,\nhiperemia de mucosa oral, edema de língua e\nlábios. Sinais estáveis, urina amarelo-ouro, sem\nsinais de cianose. Segundo a mãe, a criança estava bem, alimentou-se normalmente no almoço,\nnão fez uso de nenhum medicamento e passou grande parte da tarde brincando na garagem com\noutras crianças. Às 17 horas, a mãe observou que a criança estava chorosa e com os lábios\ninchados. 15 minutos mais tarde, deu entrada na emergência junto com uma coleguinha de 4 anos\ncom os mesmos sinais clínicos. O quadro sugere intoxicação por:","options":{"A":"Raticida.","B":"Picada de abelha.","C":"Psicotrópicos.","D":"AAS ([Ácido Acetilsalicílico).","E":"Plantas com oxalato (Dieffenbachia picta Schott ? comigo-ninguém-pode)."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-101285","number":"101285","sourceNumber":"101285","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"M.R.S., 52 anos de idade, hipertensa, em uso de captopril, é trazida pela filha ao\nHospital Universitário por agitação e dor em MID\napós ter sido picada por uma cobra. A paciente\npossui história de doença psiquiátrica, com algumas internações e má aderência ao tratamento.\nMora nos fundos da casa da filha, é divorciada e possui comportamento muitas vezes exaltado e\nagressivo. A família relata que nos últimos meses gasta além de sua aposentadoria em roupas e\nobjetos fúteis, gerando dívidas. Ao exame, está orientada e hiperativa. Enquanto tenta contar como\naconteceu o acidente, percebe-se um discurso com pensamento acelerado e distraibilidade. Mostra\no animal, um filhote de jararaca, morto numa sacola como quem ergue um troféu. Com relação ao\ncaso clínico e prováveis diagnósticos, assinale a alternativa CORRETA.","options":{"A":"O humor disfórico da paciente, no momento do atendimento, dificulta a avaliação clínica.","B":"O uso de lítio associado a inibidor da enzima conversora da angiotensina é contraindicado\ndevido ao risco de hepatotoxicidade.","C":"Anticonvulsivantes são opções terapêuticas para o distúrbio psiquiátrico, podendo ser usados\nem associação com estabilizadores do humor.","D":"A picada por filhote de jararaca leva a quadro de intoxicação leve, com menor incidência de\ncomplicações locais e de disfunção renal.","E":"Complicações possíveis do acidente botrópico são: fenômenos trombóticos, isquemia, infecção e\nsíndrome compartimental; antibioticoprofilaxia é indicada no manejo inicial."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-78308","number":"78308","sourceNumber":"78308","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança com três anos é levada ao serviço de emergência com quadro clínico de\nintoxicação, caracterizado por vômitos, diarreia e visão borrada. O exame físico revelou pupilas\npuntiformes, sialorreia, sudorese e miofasciculações. Estava normotérmica. A família relatou o uso\nde veneno na salsicha para matar ratos. Pelo quadro clínico é fácil identificar o mecanismo do\nveneno envolvido, identificar a síndrome que o paciente está apresentando. O médico deve ligar\npara o Centro de Informações Toxicológicas da região, iniciar imediatamente o uso de antídoto e\nsolicitar exame laboratorial que confirme o diagnóstico. Assinale a alternativa que identifica\nCORRETAMENTE a síndrome clínica, o antídoto e o exame laboratorial a ser solicitado.","options":{"A":"Síndrome adrenérgica, antídoto atropina, nível de mercúrio em urina de 24h.","B":"Síndrome colinérgica, antídoto atropina, atividade sérica de acetilcolinesterase.","C":"Síndrome colinérgica, antídoto N-acetilcisteína, dosar a atividade da colinesterase.","D":"Síndrome anticolinérgica, antídoto atropina, nível urinário de anticoagulante.","E":"Síndrome anticolinérgica, antídoto atropina, dosar a atividade da colinesterase."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-preventiva-med-pre-05-43822","number":"43822","sourceNumber":"43822","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente feminina, 22 anos de idade, estava caminhando na trilha da praia da Lagoinha\ndo Leste quando sofreu acidente botrópico.\nTrazida pelo Serviço de Atendimento Móvel de\nUrgência (SAMU), chega ao Hospital Universitário para avaliação no Centro de Informações\nToxicológicas (CIT) apresentando local de inoculação em tornozelo, com dor, edema e equimose, e\ncom tempo de protrombina e tempo de coagulação incoaguláveis. Feita a soroterapia, ainda\nmanteve, após 12 horas, o tempo de coagulação e o tempo de protrombina incoaguláveis. A\npaciente encontra-se em bom estado geral e assintomática quando em repouso. A CONDUTA\nADEQUADA é:","options":{"A":"( ) não dar alta para a paciente e repetir exame em 12 horas.","B":"( ) transfundir plasma fresco congelado.","C":"( ) administrar vitamina K parenteral.","D":"( ) administrar dose adicional de soro antibotrópico.","E":"( ) administrar ácido aminocaproico."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-327444","number":"327444","sourceNumber":"327444","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um grupo de turistas de 5 pessoas começou uma trilha em Florianópolis - SC até uma\npraia famosa. Porém, após saírem da trilha para o meio da mata devido a um desafio, um deles\nacidentou-se com um animal peçonhento. Infelizmente, o passeio terminou mais cedo e tiveram que\nprocurar um centro de saúde. Eles não capturaram o animal para mostrar ao médico de saúde da\nfamília. Sobre acidentes com animais peçonhentos, marque a alternativa correta:","options":{"A":"Se 24 horas após iniciar com bolha de conteúdo hemorrágico, circundada por halo isquêmico\nseguido por área eritematosa e ulceração, deve ter sido picado por aranha-marrom.","B":"Se dor importante, com eritema e prurido, sem bolha, deve ter sido picado por aranha\ncaranguejeira, havendo risco de hemorragia, com necessidade de encaminhamento para\nemergência.","C":"Se houver a presença de tentáculos aderidos, eles devem ser retirados, evitar o uso de água\ndoce para lavar o local e não esfregar com\npanos secos, que são orientações para acidente com\nLonomia obliqua.","D":"Se houver a presença de ferroadas ou mordeduras descarta-se que o acidente tenha sido\ncausado por animais marinhos, pois o quadro habitual é de eritema e prurido com dor local."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-317005","number":"317005","sourceNumber":"317005","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"A cafeína é a substância psicoativa mais consumida no mundo, com os estudos\nepidemiológicos demonstrando sintomas de\nabstinência em 50% a 75% de todos usuários, e é\nencontrada, entre outros, em café, alguns chás, chocolate e alguns medicamentos e refrigerantes.\nAlém da abstinência, também pode causar: I. Intoxicação, que dependendo da dose pode causar\nsintomas mais leves, como ansiedade, inquietação e irritabilidade, até sintomas mais graves,\nconvulsões generalizadas, insuficiência respiratória e morte. II. O uso contínuo causa dependência\ne tolerância à substância. III. Em relação ao sono, pode causar despertares mais precoces,\ndificuldades em iniciar e manter o sono. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas III.","C":"Apenas II e III.","D":"I, II e III."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-83060","number":"83060","sourceNumber":"83060","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente chega à Unidade Básica de Saúde com infecção por mordedura de cão,\nocorrida 24 horas antes. Qual o esquema de antibiótico mais adequado, além das medidas de\nlimpeza e curativo?","options":{"A":"Não é necessário antibioticoterapia.","B":"Penicilina ? doxiciclina.","C":"Amoxaciclina ? clindamicina.","D":"Cefoxitina ? doxiciclina.","E":"Amoxacilina ? ácido clavulânico."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-83048","number":"83048","sourceNumber":"83048","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma paciente chega ao Pronto Atendimento levada por familiares com história de uso\nde grande quantidade de antidepressivos\ntricíclicos. Qual a afirmação correta sobre a abordagem\nda intoxicação nesse caso?","options":{"A":"No caso de crises convulsivas, a fenitoína é a 1ª escolha como anticonvulsivante.","B":"O uso de bicarbonato de sódio está indicado quando houver QRS > 0,10, arritmias ventriculares\nou hipotensão.","C":"O uso de anticolinesterásico, como a fisostigmina, é indicado.","D":"Em caso de agitação, é recomendado o uso de neurolépticos.","E":"A hemodiálise é a 1ª escolha no tratamento."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-83097","number":"83097","sourceNumber":"83097","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Qual das seguintes drogas é a que tem efeito tóxico direto sobre o hepatócito?","options":{"A":"Clorpromazina.","B":"Isoniazida.","C":"Halotano.","D":"Rosuvastatina.","E":"Acetaminofeno."},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-84234","number":"84234","sourceNumber":"84234","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em vítimas de acidentes botrópicos que desenvolvem reação precoce ao soro\nheterólogo, qual a droga de primeira escolha no tratamento?","options":{"A":"Adrenalina.","B":"Hidrocortisona.","C":"Clorpromazina.","D":"Ranitidina."},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-32887","number":"32887","sourceNumber":"32887","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Relacionado com quadros de intoxicação exógena, identifique como verdadeira (V) ou\nfalsa (F) as relações abaixo, entre agente causador e quadro clínico. ( ) Cocaína: Ansiedade,\ntremores, midríase, hipertensão, psicose. ( ) Carbamazepina: Taquicardia, midríase, sonolência,\ncoma. ( ) Opioides: Diarreia, vômitos, salivação, miose, tremores musculares, broncorreia. Assinale\na alternativa que indica a sequência correta, de cima para baixo.","options":{"A":"V ? V ? V","B":"V ? V ? F","C":"F ? V ? V","D":"F ? V ? F","E":"F ? F ? F"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-32724","number":"32724","sourceNumber":"32724","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em relação às intoxicações exógenas e seus antídotos, correlacione os antídotos com\na intoxicação exógena correspondente.\n1.Flumazenil. 2.N-acetilcisteína. 3.Glucagon. 4.Cálcio.\n\n5.EDTA. ( ) Chumbo. ( ) Paracetamol. ( ) Propanolol. ( ) Hipermagnesemia. ( ) Diazepam. Assinale a\nalternativa que apresenta a numeração correta da coluna da direita, de cima para baixo.","options":{"A":"4 - 2 - 1 - 3 - 5.","B":"5 - 2 - 4 - 1 - 3.","C":"5 - 2 - 3 - 4 - 1.","D":"3 - 2 - 1 - 5 - 4.","E":"1 - 3 - 2 - 5 - 4."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-37535","number":"37535","sourceNumber":"37535","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Lavrador, 30 anos, tentativa de suicídio, em insuficiência respiratória apresentando\nsudorese profusa, miofasciculações,\nbroncorreia, pupilas mióticas e bradicardia. Qual a provável\netiologia e como deve ser medicado, visando as manifestações muscarínicas?","options":{"A":"Síndrome colinérgica aguda por organofosforados ? atropina;","B":"Síndrome colinérgica aguda por organoclorados ? pralidoxina;","C":"Intoxicação por paraquat ? atropina;","D":"Síndrome colinérgica aguda por organofosforados ? naloxano;","E":"Intoxicação por carbamato ? hidratação venosa vigorosa"},"answer":"A","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-372754","number":"372754","sourceNumber":"372754","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma mulher de 42 anos, diagnosticada com esquizofrenia aos 24 anos de idade, em\nuso de Olanzapina, iniciou há 3 dias\nsintomas de febre de 39 graus, rigidez em extremidades,\nconfusão mental e episódios de taquicardia. Há seis dias passou em consulta com psiquiatra, que\naumentou a dose da Olanzapina e, também, introduziu lítio para melhor controle dos sintomas.\n\nExames laboratoriais coletados no pronto-socorro demonstraram leucocitose importante, com\ncontagem de glóbulos brancos de 33.000,\ncreatinina 3,2, ureia 52 e CPK 5.320. Diante da situação\nhipotética, assinale a alternativa que apresenta o diagnóstico mais provável.","options":{"A":"Síndrome neuroléptica maligna é a principal suspeita diagnóstica neste caso, associado a\nalguma infecção sistêmica como pneumonia ou ITU, visto que nesta doença nunca se observam\nníveis de leucócitos acima de 20.000.","B":"Síndrome neuroléptica maligna é a principal suspeita diagnóstica neste caso e o tratamento é a\nsuspensão da Olanzapina e lítio, tratamento de suporte objetivando manter a estabilidade\nventilatória, cardíaca, euvolemia, controle de hipertermia, além de medicações como\nbenzodiazepínicos, dantrolene, amantadina ou bromocriptina a depender do caso.","C":"Síndrome neuroléptica maligna não deve ser considerada neste caso, uma vez que a paciente\nfaz uso de antipsicótico há muitos anos e esta\ncondição ocorre apenas no início do tratamento.","D":"A principal hipótese diagnóstica neste caso é meningite bacteriana e a conduta é iniciar\nantibioticoterapia empírica e coleta de LCR de urgência. A paciente não apresenta critérios\ndiagnósticos compatíveis com síndrome neuroléptica maligna.","E":"Síndrome serotoninérgica é um diagnóstico diferencial importante a ser considerado, visto que o\nquadro clínico e fatores desencadeantes são exatamente os mesmos relacionados à síndrome\nneuroléptica maligna, sendo impossível distinguir ambas clinicamente, apenas laboratorialmente."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-362777","number":"362777","sourceNumber":"362777","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Paciente de 5 anos, sexo masculino, sem antecedentes relevantes foi encontrado\ndesacordado em casa pela avó e levado\nprontamente ao hospital. Ele estava aos cuidados do\nirmão de 16 anos, que aparentemente havia saído e deixado o menor assistindo à televisão. Até\nentão, ele estava bem e assintomático. Ao exame em sala de emergência, o paciente apresentava\nvia aérea pérvia, FR: 22 ipm, SpO² 96%, ausculta e expansibilidade pulmonar preservadas, FC: 140\nbpm, PA: 130x80 mmHg, pulso e perfusão preservadas, apresentando mucosas secas. Na\navaliação neurológica alternava períodos de sonolência com agitação e pupilas midriáticas. Bexiga\npalpável próxima à região umbilical, temperatura de 37, 9 °C. Exposição sem hematomas, face\nconforme a imagem a seguir: Assinale qual é o mecanismo responsável pelo quadro clínico\napresentado","options":{"A":"Estímulo agonista sobre o receptores opioides Delta, Kappa e Mu.","B":"Hipertensão intracraniana.","C":"Hemorragia cerebral frontal, interhemisférica e retiniana.","D":"Bloqueio dos receptores muscarínicos de acetilcolina."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-372740","number":"372740","sourceNumber":"372740","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um paciente do sexo masculino, de 60 anos de idade, portador de hipertensão arterial\nsistêmica, diabetes do tipo 2, doença renal crônica, iniciou quadro de cefaleia de forte\nintensidade e\nfraqueza em dimídio esquerdo. Ao chegar à sala de emergência do hospital, apresentava PA 240 X\n120, FC 98, FR 18, SatO2 97% e dextro 121, fraqueza em hemicorpo esquerdo, NIHSS 12 e a\ntomografia inicial revelou uma hemorragia em região nucleocapsular direita. Foi internado em UTI\ndevido ao AVC hemorrágico e, ao longo de uma semana, evoluiu com melhora parcial do défict à\ndireita, porém apresentava controle da pressão arterial difícil, sendo necessárias altas doses de\nNitroprussiato ao longo dos dias. No oitavo dia de internação, evoluiu com crise convulsiva\npresenciada pela equipe médica, confusão mental, ansiedade, alucinações visuais e zumbido. Ao\nexame físico, a força mantinha-se estável e apresentava pupilas 'mióticas. Realizado exame de RM\nde crânio nesse contexto, que demonstrava estabilidade da lesão hemorrágica, sem expansão do\nsangramento, edema ou outras alterações que justificassem o quadro atual. Diante desse quadro,\nassinale a alternativa que apresenta a principal hipótese diagnóstica e tratamento.","options":{"A":"Vasoespasmo sintomático ? realizar arteriografia confirmatória e iniciar Nimodipino.","B":"Intoxicação pelo cianeto/tiocianato devido ao uso prolongado de Nitroprussiato - suspender a\nmedicação, iniciar Hidroxicobalamina e Tiossulfato de sódio.","C":"Epilepsia sintomática, provavelmente associada à hiponatremia grave em paciente com AVC\nhemorrágico - coletar exames laboratoriais para avaliação e distúrbios hidroeletrolíticos e iniciar\nfenitoína endovenosa.","D":"Progressão esperada do AVC hemorrágico - conduta conservadora.","E":"Síndrome da Encefalopatia Posterior Reversível (PRES) - manter uso de Nitroprussiato para\nredução da pressão arterial."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-368235","number":"368235","sourceNumber":"368235","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma criança de 6 anos é levada ao pronto-socorro pediátrico após ter sofrido acidente\nescorpiônico há 2 horas. A criança apresenta dor intensa no local da picada, sudorese, taquicardia\ne sialorreia discreta. Não apresentou vômitos. A pressão arterial está dentro dos valores normais.\nConsiderando as informações no quadro apresentado, assinale a alternativa correta.","options":{"A":"Deve-se aguardar a realização de exames laboratoriais para determinar a melhor conduta.","B":"A presença de hipotensão não mudaria a conduta do caso.","C":"A melhor conduta é a analgesia e a hidratação, sem a administração de soro antiescorpiônico,\npois trata-se de acidente escorpiônico leve.","D":"Deve-se realizar a administração de 2 a 3 ampolas de soro antiescorpiônico.","E":"Além do soro antiescorpiônico, deve-se administrar corticoide sistêmico e aplicação de gelo no\nlocal da picada."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-353129","number":"353129","sourceNumber":"353129","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Criança de 2 anos, estava brincando nos fundos de casa, quando iniciou choro intenso.\nApós alguns minutos, apresentou muitos\nepisódios de vômitos, sudorese e palidez. Mãe procurou\natendimento de urgência. Ao exame: sonolenta, sudoreica, com extremidades frias, sialorreica. FC:\noscilando de 90 a 166 bpm, FR: 45 ipm, oximetria de pulso: 90% em ar ambiente, PA: 138/80\nmmHg. Ausculta cardíaca arrítmica, sem sopros. Ausculta pulmonar: murmúrios reduzidos e com\nestertores em bases. Glicosimetria capilar: 364 mg/dL. Considerando o caso clínico acima, qual o\ntipo de choque envolvido?","options":{"A":"Hipovolêmico.","B":"Anafilático.","C":"Cardiogênico.","D":"Séptico."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-353151","number":"353151","sourceNumber":"353151","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Adolescente de 16 anos chega à sala de emergência com história de ter sido\nencontrada desacordada em seu quarto há 1 hora.\nAo exame físico: sonolenta (Escala de Coma de\nGlasgow 11), frequência respiratória de 30 ipm, frequência cardíaca de 100 bpm, pressão arterial\nde 100/70 mmHg, pulsos amplos e simétricos, tempo de enchimento capilar de 2 segundos. A\nacompanhante relata ter encontrado uma cartela de comprimidos vazia ao lado da cama da\npaciente. A gasometria arterial mostra: pH: 7,52 PO?:100 mmHg; PCO?:22 mmHg; Bicarbonato: 14\nmEq/L; Base Excess: 11; sódio plasmático: 140 mEq/L; potássio plasmático: 4,0 mEq/L; cloro\nplasmático: 103 mEq/L. Qual é o provável agente causador da intoxicação?","options":{"A":"Benzodiazepínico.","B":"Antidepressivo tricíclico.","C":"Ácido acetil salicílico.","D":"Opioide."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-357659","number":"357659","sourceNumber":"357659","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Homem de 35 anos chega ao Pronto-Socorro 3 horas após picada de serpente não\nidentificada. Apresenta ptose bilateral, dor muscular intensa e urina com coloração avermelhada.\nHá 2 orifícios puntiformes em sua perna esquerda e não há sinais inflamatórios ou dor local. O tipo\nde acidente ofídico mais provável é","options":{"A":"botrópico.","B":"elapídico.","C":"crotálico.","D":"laquético."},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-323256","number":"323256","sourceNumber":"323256","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma mulher de 23 anos de idade foi encaminhada para a UTI, após tentativa de\nsuicídio, com quadro de agitação, delirium, em midríase, hipertérmica, taquicárdica, hipertensa,\npele seca, quente e avermelhada. As mucosas estão secas. A causa mais provável pela\nsintomatologia de intoxicação exógena da paciente, dentre as substâncias abaixo, é:","options":{"A":"Tramadol.","B":"Diazepam.","C":"Aldicarb (\"chumbinho\").","D":"Imipramina."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-328250","number":"328250","sourceNumber":"328250","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma mulher de 56 anos de idade foi levada inconsciente ao hospital pelo SAMU. Na\nentrada, apresentava-se sonolenta, e seus dados eram os seguintes: frequência cardíaca de 40\nbpm; pressão arterial de 100 mmHg x 55 mmHg; saturação de 97%; pupilas mióticas pouco\nfotorreagentes. O restante do exame físico resultou normal. Durante seu tratamento, a paciente\nevoluiu com FC de 120 bpm, ausculta com estertores crepitantes bilaterais difusos e saturação de\n85%. Assinale a alternativa que apresenta, respectivamente, o quadro provavelmente associado a\nesse caso clínico e a medicação indicada.","options":{"A":"síndrome anticolinérgica; atropina","B":"edema pulmonar cardiogênico; flumazenil","C":"edema pulmonar hipertensivo; dexametasona","D":"edema pulmonar cardiogênico; adrenalina","E":"edema pulmonar não cardiogênico; naloxona"},"answer":"E","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-324581","number":"324581","sourceNumber":"324581","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um pré-escolar de 4 anos e 12 kg foi submetido a cirurgia abdominal de baixa\ncomplexidade com anestesia geral, sem\nintercorrências. Ao final do procedimento, recebeu uma\ndose adicional endovenosa de fentanil e cetoprofeno para analgesia. Veio direto para enfermaria\npediátrica, 1 hora após o final da cirurgia. Após 30 minutos, você é chamado para avaliar a criança,\npois a mãe diz que ela não acorda. Ao exame físico: corada, hidratada, acianótica, anictérica e\nafebril. Frequência cardíaca 110 bpm, frequência respiratória 10 irpm, pressão arterial 95 x 55\nmmHg, saturação periférica de oxigênio 90% em ar ambiente. Ausculta respiratória mostra\nmurmúrio vesicular simétrico, sem ruídos adventícios. Ausculta cardíaca revela ritmo regular, duas\nbulhas normofonéticas, sem sopros, pulsos centrais e periféricos fortes, tempo de enchimento\ncapilar 2 segundos. Abdome sem anormalidades. Pupilas mióticas e isocóricas. Com base no\nquadro clínico acima, qual o tratamento farmacológico imediato mais adequado para esta situação\nclínica?","options":{"A":"Haloperidol.","B":"Flumazenil.","C":"Glicose.","D":"Naloxona."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-338856","number":"338856","sourceNumber":"338856","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Menino, 1a, é trazido à Emergência com história de choro intenso, agitação, sudorese\nfria e seis episódios de vômito há cerca de\numa hora. Exame físico: regular estado geral; sonolento;\nchoroso; T=36,8°C; FC=175bpm; FR=32irpm; pulsos cheios, enchimento capilar=2seg. Levado à\nSala de Urgência. Eletrocardiograma: ritmo sinusal, onda T invertida em algumas derivações e\npresença de onda U. Glicemia capilar=204mg/dL. A HIPÓTESE DIAGNÓSTICA É:","options":{"A":"Síndrome do QT longo.","B":"Acidente escorpiônico.","C":"Sepse criptogênica.","D":"Cetoacidose diabética."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-328297","number":"328297","sourceNumber":"328297","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Um menino de dois anos de idade, previamente hígido, foi levado ao pronto-socorro\ninfantil com histórico de sonolência súbita.\nO pai relatou que o menino estava tratando um quadro\nde infecção de vias aéreas superiores com lavagem nasal e inalação com soro fisiológico havia três\ndias. No presente dia, pela manhã, o pai não havia achado o soro fisiológico para realizar a\nlavagem nasal, então usou a medicação que ele utilizava normalmente para ?descongestionar o\nnariz?. Entre as alternativas a seguir, assinale aquela que apresenta a provável causa da\nintoxicação exógena no caso clínico acima e o seu tratamento adequado, respectivamente.","options":{"A":"morfina ? naloxona","B":"nafazolina ? naloxona","C":"nafazolina ? medidas de suporte","D":"morfina ? medidas de suporte","E":"morfina ? flumazenil"},"answer":"C","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-336429","number":"336429","sourceNumber":"336429","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Em 23/07/2022, a Organização Mundial da Saúde (OMS) reconheceu que a\ndisseminação internacional do vírus da Varíola dos\nMacacos (MPX) constitui uma emergência em\nsaúde pública de interesse internacional. Em relação às características epidemiológicas da\nepidemia do vírus da Varíola dos Macacos (MPX) de 2022, é correto afirmar que:","options":{"A":"a concentração de casos entre homens que fazem sexo com homens era esperada,\nconsiderando o número de parceiros sexuais neste grupo.","B":"a rápida disseminação em regiões não endêmicas sugere que o MPX já estava circulando de\nforma não detectada por algum tempo.","C":"a transmissão ocorre prioritariamente pelo sêmen e por secreções vaginais.","D":"a variante 1, antiga variante da África Ocidental e considerada uma das mais virulentas, é a\nresponsável pela disseminação global em 2022."},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-340520","number":"340520","sourceNumber":"340520","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Quanto à intoxicação exógena, considere as seguintes possibilidades de quadros\nclínicos, agentes causadores e medidas de\ntratamento específicas. Paciente A: pupilas\nrapidamente variáveis, convulsão, pele fria, bradicardia. Paciente B: pupilas mióticas, broncorreia,\nhipersalivação, bradicardia. Paciente C: pupilas muito mióticas, hipoventilação, bradipneia. Agente\n1: opioide. Agente 2: betabloqueador. Agente 3: organofosforado. Medida X: glucagon, gluconato\nde cálcio. Medida Y: naloxone. Medida Z: atropina e pralidoxima. A partir dessas informações,\nassinale a alternativa que apresenta a correlação mais adequada entre o quadro clínico, o agente\ncausador e a medida de tratamento.","options":{"A":"A-1-X; B-2-Y; C-3-Z","B":"A-2-X; B-3-Z; C-1-Y","C":"A-3-Z; B-1-Y; C-2-X","D":"A-1-Z; B-2-X; C-3-Y","E":"A-2-Y; B-1-X; C-3-Z"},"answer":"B","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-preventiva-med-pre-05-310961","number":"310961","sourceNumber":"310961","collectionBlock":"med:med-preventiva-med-pre-05","collectionLabel":"MED · MED PRE 05","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"MED PRE 05","subtopic":"","stem":"Uma mulher de 23 anos de idade foi levada por seus familiares ao setor de emergência,\npor rebaixamento do nível de consciência. Ela fora\nencontrada em sua casa, pelos familiares,\ndesacordada e ao lado de embalagens vazias de comprimidos, em especial, os que sua avó, em\ncuidados paliativos, utiliza para controle da dor. Tem antecedentes de uso de drogas ilícitas e\netilismo. Exame físico: letárgica; abertura ocular ao estímulo doloroso; balbucia palavras quando\nestimulada; e com miose bilateral e bradipneia. Com base nesse caso hipotético, assinale a\nalternativa que apresenta a melhor escolha de antídoto para a paciente.","options":{"A":"flumazenil.","B":"fisostigmina.","C":"glicose e tiamina.","D":"naloxona.","E":"glucagon."},"answer":"D","source":"Preventiva/MED PRE 05/MED PRE 05.txt","sourceLabel":"MED · MED PRE 05","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","MED PRE 05","MED"],"answerSource":"explicit","commentDeferred":true}]};
